INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a557665d-5c9d-45d7-822f-e75e725cc1df', '詩三百三首 二百二', '诗三百三首 二百二', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["我向前谿照碧流，或向巖邊坐磐石。","心似孤雲無所依，悠悠世事何須覓。"]', '["我向前谿照碧流，或向巖邊坐磐石。","心似孤云無所依，悠悠世事何須覓。"]', '诗', 'shi', '', NULL, '詩三百三首 二百二 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('706700a2-1cf3-445d-8b86-98e15150e338', '詩三百三首 二百三', '诗三百三首 二百三', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["我家本住在寒山，石巖棲息離煩緣。","泯時萬象無痕跡，舒處周流徧大千。","光影騰輝照心地，無有一法當現前。","方知摩尼一顆珠，解用無方處處圓。"]', '["我家本住在寒山，石巖棲息離煩緣。","泯时万象無痕跡，舒处周流徧大千。","光影腾輝照心地，無有一法當現前。","方知摩尼一顆珠，解用無方处处圓。"]', '诗', 'shi', '', NULL, '詩三百三首 二百三 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fa7707ba-5634-4dce-8307-683cb3345457', '詩三百三首 二百四', '诗三百三首 二百四', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["世人何事可吁嗟，苦樂交煎勿底涯。","生死往來多少劫，東西南北是誰家。","張王李趙權時姓，六道三途事似麻。","只爲主人不了絕，遂招遷謝逐迷邪。"]', '["世人何事可吁嗟，苦乐交煎勿底涯。","生死往来多少劫，东西南北是誰家。","張王李趙權时姓，六道三途事似麻。","只爲主人不了絕，遂招遷謝逐迷邪。"]', '诗', 'shi', '', NULL, '詩三百三首 二百四 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a7de0e8-31fe-41f4-a8de-cc41a423a5e4', '詩三百三首 二百五', '诗三百三首 二百五', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["余家本住在天台，雲路煙深絕客來。","千仞巖巒深可遯，萬重谿澗石樓臺。","樺巾木屐沿流步，布裘藜杖繞山迴。","自覺浮生幻化事，逍遙快樂實善哉。"]', '["余家本住在天台，云路煙深絕客来。","千仞巖巒深可遯，万重谿澗石楼台。","樺巾木屐沿流步，布裘藜杖繞山迴。","自覺浮生幻化事，逍遙快乐實善哉。"]', '诗', 'shi', '', NULL, '詩三百三首 二百五 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b2d9de4-b5a2-4901-84fe-65ce5b390ddc', '詩三百三首 二百六', '诗三百三首 二百六', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["憐底衆生病，餐嘗畧不厭。","蒸豚揾蒜醬，炙鴨點椒鹽。","去骨鮮魚膾，兼皮熟肉臉。","不知他命苦，只取自家甜。"]', '["怜底衆生病，餐嘗畧不厭。","蒸豚揾蒜醬，炙鴨点椒鹽。","去骨鲜鱼膾，兼皮熟肉臉。","不知他命苦，只取自家甜。"]', '诗', 'shi', '', NULL, '詩三百三首 二百六 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f4b581d2-0a07-4b7c-ad25-cfbc7ec71726', '詩三百三首 二百七', '诗三百三首 二百七', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["讀書豈免死，讀書豈免貧。","何以好識字，識字勝他人。","丈夫不識字，無處可安身。","黃連揾蒜醬，忘計是苦辛。"]', '["读书豈免死，读书豈免貧。","何以好識字，識字勝他人。","丈夫不識字，無处可安身。","黄連揾蒜醬，忘計是苦辛。"]', '诗', 'shi', '', NULL, '詩三百三首 二百七 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('81c46f0a-28e2-44be-809a-0820f11611a0', '詩三百三首 二百八', '诗三百三首 二百八', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["我見瞞人漢，如籃盛水走。","一氣將歸家，籃裏何曾有。","我見被人瞞，一似園中韭。","日日被刀傷，天生還自有。"]', '["我见瞞人漢，如籃盛水走。","一氣將归家，籃裏何曾有。","我见被人瞞，一似园中韭。","日日被刀傷，天生還自有。"]', '诗', 'shi', '', NULL, '詩三百三首 二百八 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c16d82a0-d05f-4d85-bb4c-656364165734', '詩三百三首 二百九', '诗三百三首 二百九', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["不見朝垂露，日爍自消除。","人身亦如此，閻浮是寄居。","切莫因循過，且令三毒袪。","菩提即煩惱，盡令無有餘。"]', '["不见朝垂露，日爍自消除。","人身亦如此，閻浮是寄居。","切莫因循過，且令三毒袪。","菩提即煩惱，尽令無有餘。"]', '诗', 'shi', '', NULL, '詩三百三首 二百九 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a45dd1f6-6e06-4abd-b7e8-5dfa4184f102', '詩三百三首 二百一十', '诗三百三首 二百一十', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["水清澄澄瑩，徹底自然見。","心中無一事，水清衆獸現。","心若不妄起，永劫無改變。","若能如是知，是知無背面。"]', '["水清澄澄瑩，徹底自然见。","心中無一事，水清衆獸現。","心若不妄起，永劫無改变。","若能如是知，是知無背面。"]', '诗', 'shi', '', NULL, '詩三百三首 二百一十 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f810eb3-632d-4cff-a039-c29e93e49295', '詩三百三首 二一一', '诗三百三首 二一一', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["自從到此天台境，經今早度幾冬春。","山水不移人自老，見却多少後生人。"]', '["自從到此天台境，經今早度幾冬春。","山水不移人自老，见却多少後生人。"]', '诗', 'shi', '', NULL, '詩三百三首 二一一 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('34c53120-4e70-4f64-96ea-d8b16fb707e7', '詩三百三首 二一二', '诗三百三首 二一二', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["說食終不飽，說衣不免寒。","飽喫須是飯，著衣方免寒。","不解審思量，只道求佛難。","迴心即是佛，莫向外頭看。"]', '["说食終不飽，说衣不免寒。","飽喫須是飯，著衣方免寒。","不解審思量，只道求佛难。","迴心即是佛，莫向外头看。"]', '诗', 'shi', '', NULL, '詩三百三首 二一二 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c83aaa31-e1a1-46b7-b745-ccff1b60785c', '詩三百三首 二一三', '诗三百三首 二一三', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["可畏輪迴苦，往復似翻塵。","蟻巡環未息，六道亂紛紛。","改頭換面孔，不離舊時人。","速了黑暗獄，無令心性昏。"]', '["可畏輪迴苦，往复似翻塵。","蟻巡环未息，六道亂紛紛。","改头換面孔，不離旧时人。","速了黑暗獄，無令心性昏。"]', '诗', 'shi', '', NULL, '詩三百三首 二一三 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b4427f46-2853-423c-b600-77e3795697b9', '詩三百三首 二一四', '诗三百三首 二一四', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["可畏三界輪，念念未曾息。","纔始似出頭，又却遭沈溺。","假使非非想，蓋緣多福力。","爭似識真源，一得即永得。"]', '["可畏三界輪，念念未曾息。","纔始似出头，又却遭沈溺。","假使非非想，蓋緣多福力。","爭似識真源，一得即永得。"]', '诗', 'shi', '', NULL, '詩三百三首 二一四 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb8065f3-8542-4e6f-b314-222af19574ef', '詩三百三首 二一五', '诗三百三首 二一五', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["昨日遊峰頂，下窺千尺崖。","臨危一株樹，風擺兩枝開。","雨漂即零落，日曬作塵埃。","嗟見此茂秀，今爲一聚灰。"]', '["昨日游峰頂，下窺千尺崖。","臨危一株樹，风擺兩枝开。","雨漂即零落，日曬作塵埃。","嗟见此茂秀，今爲一聚灰。"]', '诗', 'shi', '', NULL, '詩三百三首 二一五 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('22e890da-53fd-4cb3-ac92-10eb66330522', '詩三百三首 二一六', '诗三百三首 二一六', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["自古多少聖，叮嚀教自信。","人根性不等，高下有利鈍。","真佛不肯認，置功枉受困。","不知清淨心，便是法王印。"]', '["自古多少聖，叮嚀教自信。","人根性不等，高下有利鈍。","真佛不肯認，置功枉受困。","不知清淨心，便是法王印。"]', '诗', 'shi', '', NULL, '詩三百三首 二一六 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('228ecb1f-1d2f-4677-b7a8-0ae031638199', '詩三百三首 二一七', '诗三百三首 二一七', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["我聞天台山，山中有琪樹。","永言欲攀之，莫曉石橋路。","緣此生悲歎，幸居將已慕。","今日觀鏡中，颯颯鬢垂素。"]', '["我闻天台山，山中有琪樹。","永言欲攀之，莫晓石橋路。","緣此生悲歎，幸居將已慕。","今日观镜中，颯颯鬢垂素。"]', '诗', 'shi', '', NULL, '詩三百三首 二一七 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e9fb3d44-d48a-4783-b083-1c3d5106164a', '詩三百三首 二一八', '诗三百三首 二一八', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["養子不經師，不及都亭鼠。","何曾見好人，豈聞長者語。","爲染在薰蕕，應須擇朋侶。","五月販鮮魚，莫教人笑汝。"]', '["養子不經師，不及都亭鼠。","何曾见好人，豈闻长者語。","爲染在薰蕕，應須擇朋侶。","五月販鲜鱼，莫教人笑汝。"]', '诗', 'shi', '', NULL, '詩三百三首 二一八 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f6c0921d-9ecb-4332-a8ef-4c6134097a8e', '詩三百三首 二一九', '诗三百三首 二一九', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["徒閉蓬門坐，頻經石火遷。","唯聞人作鬼，不見鶴成仙。","念此那堪說，隨緣須自憐。","迴瞻郊郭外，古墓犂爲田。"]', '["徒閉蓬门坐，頻經石火遷。","唯闻人作鬼，不见鹤成仙。","念此那堪说，隨緣須自怜。","迴瞻郊郭外，古墓犂爲田。"]', '诗', 'shi', '', NULL, '詩三百三首 二一九 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('57dd1e4c-4267-46c5-aa64-d0cfafdd13e7', '詩三百三首 二百二十', '诗三百三首 二百二十', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["時人見寒山，各謂是風顛。","貌不起人目，身唯布裘纏。","我語他不會，他語我不言。","爲報往來者，可來向寒山。"]', '["时人见寒山，各謂是风顛。","貌不起人目，身唯布裘纏。","我語他不會，他語我不言。","爲報往来者，可来向寒山。"]', '诗', 'shi', '', NULL, '詩三百三首 二百二十 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bdd48842-bf95-424b-b0d9-e690c7d6f95b', '詩三百三首 二二一', '诗三百三首 二二一', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["自在白雲閑，從來非買山。","下危須策杖，上險捉藤攀。","澗底松常翠，谿邊石自斑。","友朋雖阻絕，春至鳥𠴨𠴨。"]', '["自在白云闲，從来非買山。","下危須策杖，上險捉藤攀。","澗底松常翠，谿邊石自斑。","友朋雖阻絕，春至鸟𠴨𠴨。"]', '诗', 'shi', '', NULL, '詩三百三首 二二一 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('320757b4-0d72-4d05-bf58-e6060bbcf6ab', '詩三百三首 二二二', '诗三百三首 二二二', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["我在村中住，衆推無比方。","昨日到城下，却被狗形相。","或嫌袴太窄，或說衫少長。","攣却鷂子眼，雀兒舞堂堂。"]', '["我在村中住，衆推無比方。","昨日到城下，却被狗形相。","或嫌袴太窄，或说衫少长。","攣却鷂子眼，雀兒舞堂堂。"]', '诗', 'shi', '', NULL, '詩三百三首 二二二 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d341282a-c5a0-4625-90ae-28f19d575380', '詩三百三首 二二三', '诗三百三首 二二三', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["生死元有命，富貴本由天。","此是古人語，吾今非謬傳。","聰明好短命，癡騃却長年。","鈍物豐財寶，醒醒漢無錢。"]', '["生死元有命，富貴本由天。","此是古人語，吾今非謬傳。","聰明好短命，癡騃却长年。","鈍物豐財寶，醒醒漢無錢。"]', '诗', 'shi', '', NULL, '詩三百三首 二二三 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('658fc0f9-5ed6-4a69-bb81-4533687da31b', '詩三百三首 二二四', '诗三百三首 二二四', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["國以人爲本，猶如樹因地。","地厚樹扶疎，地薄樹憔悴。","不得露其根，枝枯子先墜。","決陂以取魚，是取一期利。"]', '["国以人爲本，猶如樹因地。","地厚樹扶疎，地薄樹憔悴。","不得露其根，枝枯子先墜。","決陂以取鱼，是取一期利。"]', '诗', 'shi', '', NULL, '詩三百三首 二二四 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5b35d877-2f45-4331-ae41-824e554c9311', '詩三百三首 二二五', '诗三百三首 二二五', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["衆生不可說，何意許顛邪。","面上兩惡鳥，心中三毒虵。","是渠作障礙，使你事煩拏。","舉手高彈指，南無佛陀耶。"]', '["衆生不可说，何意許顛邪。","面上兩惡鸟，心中三毒虵。","是渠作障礙，使你事煩拏。","舉手高彈指，南無佛陀耶。"]', '诗', 'shi', '', NULL, '詩三百三首 二二五 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('93ab6f05-a0ad-4645-ad6e-5f54d24836bc', '詩三百三首 二二六', '诗三百三首 二二六', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["自樂平生道，煙蘿石洞間。","野情多放曠，長伴白雲閑。","有路不通世，無心孰可攀。","石牀孤夜坐，圓月上寒山。"]', '["自乐平生道，煙蘿石洞间。","野情多放曠，长伴白云闲。","有路不通世，無心孰可攀。","石牀孤夜坐，圓月上寒山。"]', '诗', 'shi', '', NULL, '詩三百三首 二二六 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f482216-fa3f-433a-add1-9789ee93416a', '詩三百三首 二二七', '诗三百三首 二二七', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["大海水無邊，魚龍萬萬千。","遞互相食噉，冗冗癡肉團。","爲心不了絕，妄想起如煙。","性月澄澄朗，廓爾照無邊。"]', '["大海水無邊，鱼龙万万千。","遞互相食噉，冗冗癡肉團。","爲心不了絕，妄想起如煙。","性月澄澄朗，廓爾照無邊。"]', '诗', 'shi', '', NULL, '詩三百三首 二二七 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0ce5b1fe-896d-4725-b184-6d5c4b02fc1d', '詩三百三首 二二八', '诗三百三首 二二八', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["自見天台頂，孤高出衆羣。","風搖松竹韻，月現海潮頻。","下望青山際，談玄有白雲。","野情便山水，本志慕道倫。"]', '["自见天台頂，孤高出衆羣。","风搖松竹韻，月現海潮頻。","下望青山際，談玄有白云。","野情便山水，本志慕道倫。"]', '诗', 'shi', '', NULL, '詩三百三首 二二八 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('88042b8b-cb78-4cc6-8939-fa445387bea2', '詩三百三首 二二九', '诗三百三首 二二九', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["三五癡後生，作事不真實。","未讀十卷書，強把雌黃筆。","將他儒行篇，喚作賊盜律。","脫體似蟫蟲，齩破他書帙。"]', '["三五癡後生，作事不真實。","未读十卷书，強把雌黄笔。","將他儒行篇，喚作賊盜律。","脫體似蟫蟲，齩破他书帙。"]', '诗', 'shi', '', NULL, '詩三百三首 二二九 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d3aeb762-f963-46cb-95c4-b40cd0f7ac4d', '詩三百三首 二百三十', '诗三百三首 二百三十', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["心高如山嶽，人我不伏人。","解講圍陀典，能談三教文。","心中無慚媿，破戒違律文。","自言上人法，稱爲第一人。","愚者皆讚歎，智者撫掌笑。","陽燄虛空花，豈得免生老。","不如百不解，靜坐絕憂惱。"]', '["心高如山嶽，人我不伏人。","解講圍陀典，能談三教文。","心中無慚媿，破戒違律文。","自言上人法，稱爲第一人。","愚者皆讚歎，智者撫掌笑。","陽燄虛空花，豈得免生老。","不如百不解，静坐絕憂惱。"]', '诗', 'shi', '', NULL, '詩三百三首 二百三十 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ccf09eef-faa8-4f02-84c6-b2527488bd62', '詩三百三首 二三一', '诗三百三首 二三一', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["如許多寶貝，海中乘壞舸。","前頭失却桅，後頭又無柁。","宛轉任風吹，高低隨浪簸。","如何得到岸，努力莫端坐。"]', '["如許多寶貝，海中乘壞舸。","前头失却桅，後头又無柁。","宛轉任风吹，高低隨浪簸。","如何得到岸，努力莫端坐。"]', '诗', 'shi', '', NULL, '詩三百三首 二三一 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ffde9fa3-46b2-4d02-b725-02b57c6070eb', '詩三百三首 二三二', '诗三百三首 二三二', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["我見凡愚人，多畜資財穀。","飲酒食生命，謂言我富足。","莫知地獄深，唯求上天福。","罪業如毘富，豈得免災毒。","財主忽然死，爭共當頭哭。","供僧讀文疏，空是鬼神祿。","福田一箇無，虛設一羣禿。","不如早覺悟，莫作黑暗獄。","狂風不動樹，心真無罪福。","寄語冗冗人，叮嚀再三讀。"]', '["我见凡愚人，多畜資財穀。","饮酒食生命，謂言我富足。","莫知地獄深，唯求上天福。","罪業如毘富，豈得免災毒。","財主忽然死，爭共當头哭。","供僧读文疏，空是鬼神祿。","福田一箇無，虛設一羣禿。","不如早覺悟，莫作黑暗獄。","狂风不动樹，心真無罪福。","寄語冗冗人，叮嚀再三读。"]', '诗', 'shi', '', NULL, '詩三百三首 二三二 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f7d50bd8-2b23-46d7-950e-da663b3151fb', '詩三百三首 二三三', '诗三百三首 二三三', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["勸你三界子，莫作勿道理。","理短被他欺，理長不奈你。","世間濁濫人，恰似黍黏子。","不見無事人，獨脫無能比。","早須返本源，三界任緣起。","清淨入如流，莫飲無明水。"]', '["勸你三界子，莫作勿道理。","理短被他欺，理长不奈你。","世间濁濫人，恰似黍黏子。","不见無事人，独脫無能比。","早須返本源，三界任緣起。","清淨入如流，莫饮無明水。"]', '诗', 'shi', '', NULL, '詩三百三首 二三三 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5f1e89ed-57ca-4c94-8989-161d94afe229', '詩三百三首 二三四', '诗三百三首 二三四', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["三界人蠢蠢，六道人茫茫。","貪財愛婬欲，心惡若豺狼。","地獄如箭射，極苦若爲當。","兀兀過朝夕，都不別賢良。","好惡總不識，猶如豬及羊。","共語如木石，嫉妒似顛狂。","不自見己過，如豬在圈臥。","不知自償債，却笑牛牽磨。"]', '["三界人蠢蠢，六道人茫茫。","貪財愛婬欲，心惡若豺狼。","地獄如箭射，極苦若爲當。","兀兀過朝夕，都不別賢良。","好惡總不識，猶如豬及羊。","共語如木石，嫉妒似顛狂。","不自见己過，如豬在圈臥。","不知自償債，却笑牛牽磨。"]', '诗', 'shi', '', NULL, '詩三百三首 二三四 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('15147644-a707-48b7-b4fa-775c678708c3', '詩三百三首 二三五', '诗三百三首 二三五', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["人生在塵蒙，恰似盆中蟲。","終日行遶遶，不離其盆中。","神仙不可得，煩惱計無窮。","歲月如流水，須臾作老翁。"]', '["人生在塵蒙，恰似盆中蟲。","終日行遶遶，不離其盆中。","神仙不可得，煩惱計無窮。","歲月如流水，須臾作老翁。"]', '诗', 'shi', '', NULL, '詩三百三首 二三五 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('20fd37a4-c0ba-46c8-a793-520538fdab55', '詩三百三首 二三六', '诗三百三首 二三六', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["寒山出此語，復似顛狂漢。","有事對面說，所以足人怨。","心真出語直，直心無背面。","臨死度奈河，誰是嘍囉漢。","冥冥泉臺路，被業相拘絆。"]', '["寒山出此語，复似顛狂漢。","有事对面说，所以足人怨。","心真出語直，直心無背面。","臨死度奈河，誰是嘍囉漢。","冥冥泉台路，被業相拘絆。"]', '诗', 'shi', '', NULL, '詩三百三首 二三六 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b5407ed4-4ac0-4f9b-a24f-04252b38fbfa', '詩三百三首 二三七', '诗三百三首 二三七', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["我見多知漢，終日用心神。","岐路逞嘍囉，欺謾一切人。","唯作地獄滓，不修正直因。","忽然無常至，定知亂紛紛。"]', '["我见多知漢，終日用心神。","岐路逞嘍囉，欺謾一切人。","唯作地獄滓，不修正直因。","忽然無常至，定知亂紛紛。"]', '诗', 'shi', '', NULL, '詩三百三首 二三七 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d3393c51-2615-402c-8cd0-328128f8b878', '詩三百三首 二三八', '诗三百三首 二三八', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["寄語諸仁者，復以何爲懷。","達道見自性，自性即如來。","天真元具足，修證轉差迴。","棄本却逐末，只守一場獃。"]', '["寄語諸仁者，复以何爲懷。","達道见自性，自性即如来。","天真元具足，修證轉差迴。","棄本却逐末，只守一場獃。"]', '诗', 'shi', '', NULL, '詩三百三首 二三八 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('06692d14-200c-4e87-a4c4-9eeaf09a551f', '詩三百三首 二三九', '诗三百三首 二三九', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["世有一般人，不惡又不善。","不識主人公，隨客處處轉。","因循過時光，渾是癡肉臠。","雖有一靈臺，如同客作漢。"]', '["世有一般人，不惡又不善。","不識主人公，隨客处处轉。","因循過时光，渾是癡肉臠。","雖有一靈台，如同客作漢。"]', '诗', 'shi', '', NULL, '詩三百三首 二三九 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b32d044-0a85-4b9a-bded-d809abdfe3c0', '詩三百三首 二百四十', '诗三百三首 二百四十', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["常聞釋迦佛，先受然燈記。","然燈與釋迦，只論前後智。","前後體非殊，異中無有異。","一佛一切佛，心是如來地。"]', '["常闻釋迦佛，先受然灯記。","然灯與釋迦，只論前後智。","前後體非殊，異中無有異。","一佛一切佛，心是如来地。"]', '诗', 'shi', '', NULL, '詩三百三首 二百四十 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d6bbaead-6ce1-440f-8dcd-e67b837fee8d', '詩三百三首 二四一', '诗三百三首 二四一', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["常聞國大臣，朱紫簪纓祿。","富貴百千般，貪榮不知辱。","奴馬滿宅舍，金銀盈帑屋。","癡福暫時扶，埋頭作地獄。","忽死萬事休，男女當頭哭。","不知有禍殃，前路何疾速。","家破冷颼颼，食無一粒粟。","凍餓苦悽悽，良由不覺觸。"]', '["常闻国大臣，朱紫簪纓祿。","富貴百千般，貪榮不知辱。","奴马满宅舍，金銀盈帑屋。","癡福暫时扶，埋头作地獄。","忽死万事休，男女當头哭。","不知有禍殃，前路何疾速。","家破冷颼颼，食無一粒粟。","凍餓苦悽悽，良由不覺觸。"]', '诗', 'shi', '', NULL, '詩三百三首 二四一 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('24f293ef-8d04-464b-8b76-888cce196aa7', '詩三百三首 二四二', '诗三百三首 二四二', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["上人心猛利，一聞便知妙。","中流心清淨，審思云甚要。","下士鈍暗癡，頑皮最難裂。","直待血淋頭，始知自摧滅。","看取開眼賊，鬧市集人決。","死屍棄如塵，此時向誰說。","男兒大丈夫，一刀兩段截。","人面禽獸心，造作何時歇。"]', '["上人心猛利，一闻便知妙。","中流心清淨，審思云甚要。","下士鈍暗癡，頑皮最难裂。","直待血淋头，始知自摧滅。","看取开眼賊，鬧市集人決。","死屍棄如塵，此时向誰说。","男兒大丈夫，一刀兩段截。","人面禽獸心，造作何时歇。"]', '诗', 'shi', '', NULL, '詩三百三首 二四二 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('280b4f7a-961a-4dd6-822b-9019b34a6b9c', '詩三百三首 二四三', '诗三百三首 二四三', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["我有六兄弟，就中一箇惡。","打伊又不得，駡伊又不著。","處處無奈何，耽財好淫殺。","見好埋頭愛，貪心過羅剎。","阿爺惡見伊，阿孃嫌不悅。","昨被我捉得，惡駡恣情掣。","趂向無人處，一一向伊說。","汝今須改行，覆車須改轍。","若也不信受，共汝惡合殺。","汝受我調伏，我共汝覓活。","從此盡和同，如今過菩薩。","學業攻鑪冶，鍊盡三山鐵。","至今靜恬恬，衆人皆讚說。"]', '["我有六兄弟，就中一箇惡。","打伊又不得，駡伊又不著。","处处無奈何，耽財好淫殺。","见好埋头愛，貪心過羅剎。","阿爺惡见伊，阿孃嫌不悅。","昨被我捉得，惡駡恣情掣。","趂向無人处，一一向伊说。","汝今須改行，覆车須改轍。","若也不信受，共汝惡合殺。","汝受我調伏，我共汝覓活。","從此尽和同，如今過菩薩。","学業攻鑪冶，鍊尽三山鐵。","至今静恬恬，衆人皆讚说。"]', '诗', 'shi', '', NULL, '詩三百三首 二四三 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5d49a1c0-cd02-4fe8-909d-69bec2e03b92', '詩三百三首 二四四', '诗三百三首 二四四', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["昔日極貧苦，夜夜數他寶。","今日審思量，自家須營造。","掘得一寶藏，純是水精珠。","大有碧眼胡，密擬買將去。","余即報渠言，此珠無價數。"]', '["昔日極貧苦，夜夜數他寶。","今日審思量，自家須營造。","掘得一寶藏，純是水精珠。","大有碧眼胡，密擬買將去。","余即報渠言，此珠無價數。"]', '诗', 'shi', '', NULL, '詩三百三首 二四四 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ec25c0f9-b2ab-4894-968e-e8b2c8c486c7', '詩三百三首 二四五', '诗三百三首 二四五', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["一生慵嬾作，憎重只便輕。","他家學事業，余持一卷經。","無心裝褾軸，來去省人擎。","應病則說藥，方便度衆生。"]', '["一生慵嬾作，憎重只便轻。","他家学事業，余持一卷經。","無心裝褾軸，来去省人擎。","應病則说藥，方便度衆生。"]', '诗', 'shi', '', NULL, '詩三百三首 二四五 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('69f56e1e-e39b-46fa-8fc1-dadbbfb9e787', '詩三百三首 二四六', '诗三百三首 二四六', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["我見出家人，不入出家學。","欲知真出家，心淨無繩索。","澄澄孤玄妙，如如無倚託。","三界任縱橫，四生不可泊。","無爲無事人，逍遙實快樂。"]', '["我见出家人，不入出家学。","欲知真出家，心淨無繩索。","澄澄孤玄妙，如如無倚託。","三界任縱橫，四生不可泊。","無爲無事人，逍遙實快乐。"]', '诗', 'shi', '', NULL, '詩三百三首 二四六 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('55c3e225-3e53-42bd-876d-f4b935084988', '詩三百三首 二四七', '诗三百三首 二四七', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["昨到雲霞觀，忽見仙尊士。","星冠月帔橫，盡云居山水。","餘問神仙術，云道若爲比。","謂言靈無上，妙藥心神祕。","守死待鶴來，皆道乘魚去。","余乃返窮之，推尋勿道理。","但看箭射空，須臾還墜地。","饒你得仙人，恰似守屍鬼。","心月自精明，萬象何能比。","欲知仙丹術，身內元神是。","莫學黃巾公，握愚自守擬。"]', '["昨到云霞观，忽见仙尊士。","星冠月帔橫，尽云居山水。","餘问神仙術，云道若爲比。","謂言靈無上，妙藥心神祕。","守死待鹤来，皆道乘鱼去。","余乃返窮之，推尋勿道理。","但看箭射空，須臾還墜地。","饒你得仙人，恰似守屍鬼。","心月自精明，万象何能比。","欲知仙丹術，身內元神是。","莫学黄巾公，握愚自守擬。"]', '诗', 'shi', '', NULL, '詩三百三首 二四七 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9351af6b-84bf-48ff-acf4-fc25db758e7f', '詩三百三首 二四八', '诗三百三首 二四八', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["余家有一宅，其宅無正主。","地生一寸草，水垂一滴露。","火燒六箇賊，風吹黑雲雨。","子細尋本人，布裹真珠爾。"]', '["余家有一宅，其宅無正主。","地生一寸草，水垂一滴露。","火燒六箇賊，风吹黑云雨。","子細尋本人，布裹真珠爾。"]', '诗', 'shi', '', NULL, '詩三百三首 二四八 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7e537342-de76-47c3-b495-69e6f7b0fab3', '詩三百三首 二四九', '诗三百三首 二四九', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["傳語諸公子，聽說石齊奴。","僮僕八百人，水碓三十區。","舍下養魚鳥，樓上吹笙竽。","伸頭臨白刃，癡心爲綠珠。"]', '["傳語諸公子，听说石齊奴。","僮僕八百人，水碓三十區。","舍下養鱼鸟，楼上吹笙竽。","伸头臨白刃，癡心爲綠珠。"]', '诗', 'shi', '', NULL, '詩三百三首 二四九 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bddb9528-e5b3-4078-bb3a-30977081c917', '詩三百三首 二百五十', '诗三百三首 二百五十', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["何以長惆悵，人生似朝菌。","那堪數十年，親舊凋落盡。","以此思自哀，哀情不可忍。","奈何當奈何，託體歸山隱。"]', '["何以长惆悵，人生似朝菌。","那堪數十年，親旧凋落尽。","以此思自哀，哀情不可忍。","奈何當奈何，託體归山隐。"]', '诗', 'shi', '', NULL, '詩三百三首 二百五十 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('20f96259-9cf9-422e-8a29-8644238a206c', '詩三百三首 二五一', '诗三百三首 二五一', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["繿縷關前業，莫訶今日身。","若言由冢墓，箇是極癡人。","到頭君作鬼，豈令男女貧。","皎然易解事，作麽無精神。"]', '["繿縷关前業，莫訶今日身。","若言由冢墓，箇是極癡人。","到头君作鬼，豈令男女貧。","皎然易解事，作麽無精神。"]', '诗', 'shi', '', NULL, '詩三百三首 二五一 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('138e5c00-5aa7-4b9a-b7db-21adb705d0db', '詩三百三首 二五二', '诗三百三首 二五二', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["我見黃河水，凡經幾度清。","水流如急箭，人世若浮萍。","癡屬根本業，無明煩惱阬。","輪迴幾許劫，只爲造迷盲。"]', '["我见黄河水，凡經幾度清。","水流如急箭，人世若浮萍。","癡屬根本業，無明煩惱阬。","輪迴幾許劫，只爲造迷盲。"]', '诗', 'shi', '', NULL, '詩三百三首 二五二 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('317f1dd3-3dd3-4f21-ba8e-506d3255f521', '詩三百三首 二五三', '诗三百三首 二五三', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["二儀既開闢，人乃居其中。","迷汝即吐霧，醒汝即吹風。","惜汝即富貴，奪汝即貧窮。","碌碌羣漢子，萬事由天公。"]', '["二儀既开闢，人乃居其中。","迷汝即吐霧，醒汝即吹风。","惜汝即富貴，奪汝即貧窮。","碌碌羣漢子，万事由天公。"]', '诗', 'shi', '', NULL, '詩三百三首 二五三 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5224de87-2ab2-4dda-93e2-21e8ad163f52', '詩三百三首 二五四', '诗三百三首 二五四', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["余勸諸稚子，急離火宅中。","三車在門外，載你免飄蓬。","露地四衢坐，當天萬事空。","十方無上下，來去任西東。","若得箇中意，縱橫處處通。"]', '["余勸諸稚子，急離火宅中。","三车在门外，載你免飄蓬。","露地四衢坐，當天万事空。","十方無上下，来去任西东。","若得箇中意，縱橫处处通。"]', '诗', 'shi', '', NULL, '詩三百三首 二五四 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('319edec3-7ad7-4fca-a017-2db75c3489d1', '詩三百三首 二五五', '诗三百三首 二五五', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["可歎浮生人，悠悠何日了。","朝朝無閑時，年年不覺老。","總爲求衣食，令心生煩惱。","擾擾百千年，去來三惡道。"]', '["可歎浮生人，悠悠何日了。","朝朝無闲时，年年不覺老。","總爲求衣食，令心生煩惱。","擾擾百千年，去来三惡道。"]', '诗', 'shi', '', NULL, '詩三百三首 二五五 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0759f649-5498-4bb2-bdb6-dd8a6897d475', '詩三百三首 二五六', '诗三百三首 二五六', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["時人尋雲路，雲路杳無蹤。","山高多險峻，澗闊少玲瓏。","碧嶂前兼後，白雲西復東。","欲知雲路處，雲路在虛空。"]', '["时人尋云路，云路杳無蹤。","山高多險峻，澗闊少玲瓏。","碧嶂前兼後，白云西复东。","欲知云路处，云路在虛空。"]', '诗', 'shi', '', NULL, '詩三百三首 二五六 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('991596c4-0098-4123-afa2-d6b30f2bb3d3', '詩三百三首 二五七', '诗三百三首 二五七', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["寒山棲隱處，絕得雜人過。","時逢林內鳥，相共唱山歌。","瑞草聯谿谷，老松枕嵯峨。","可觀無事客，憩歇在巖阿。"]', '["寒山棲隐处，絕得杂人過。","时逢林內鸟，相共唱山歌。","瑞草聯谿谷，老松枕嵯峨。","可观無事客，憩歇在巖阿。"]', '诗', 'shi', '', NULL, '詩三百三首 二五七 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a2efa29f-f61e-4da9-a1a1-2838b6d2fe07', '詩三百三首 二五八', '诗三百三首 二五八', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["五嶽俱成粉，須彌一寸山。","大海一滴水，吸入在心田。","生長菩提子，徧蓋天中天。","語汝慕道者，慎莫繞十纏。"]', '["五嶽俱成粉，須彌一寸山。","大海一滴水，吸入在心田。","生长菩提子，徧蓋天中天。","語汝慕道者，慎莫繞十纏。"]', '诗', 'shi', '', NULL, '詩三百三首 二五八 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c918c83a-c2fd-4e62-b71a-c49c16676164', '詩三百三首 二五九', '诗三百三首 二五九', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["無衣自訪覓，莫共狐謀裘。","無食自采取，莫共羊謀羞。","借皮兼借肉，懷歎復懷愁。","皆緣義失所，衣食常不周。"]', '["無衣自訪覓，莫共狐謀裘。","無食自采取，莫共羊謀羞。","借皮兼借肉，懷歎复懷愁。","皆緣義失所，衣食常不周。"]', '诗', 'shi', '', NULL, '詩三百三首 二五九 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e01bc4c0-533e-4936-a052-11b278f954d6', '詩三百三首 二百六十', '诗三百三首 二百六十', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["自羨山間樂，逍遙無倚託。","逐日食殘軀，閑思無所作。","時披古佛書，往往登石閣。","下窺千尺崖，上有雲盤泊。","寒月冷颼颼，身似孤飛鶴。"]', '["自羨山间乐，逍遙無倚託。","逐日食殘軀，闲思無所作。","时披古佛书，往往登石閣。","下窺千尺崖，上有云盤泊。","寒月冷颼颼，身似孤飞鹤。"]', '诗', 'shi', '', NULL, '詩三百三首 二百六十 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('622fcd46-08c6-4e5b-866d-ff0ce32c4018', '詩三百三首 二六一', '诗三百三首 二六一', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["我見轉輪王，千子常圍繞。","十善化四天，莊嚴多七寶。","七寶鎮隨身，莊嚴甚妙好。","一朝福報盡，猶若棲蘆鳥。","還作牛領蟲，六趣受業道。","況復諸凡夫，無常豈長保。","生死如旋火，輪迴似麻稻。","不解早覺悟，爲人枉虛老。"]', '["我见轉輪王，千子常圍繞。","十善化四天，莊嚴多七寶。","七寶鎮隨身，莊嚴甚妙好。","一朝福報尽，猶若棲蘆鸟。","還作牛領蟲，六趣受業道。","況复諸凡夫，無常豈长保。","生死如旋火，輪迴似麻稻。","不解早覺悟，爲人枉虛老。"]', '诗', 'shi', '', NULL, '詩三百三首 二六一 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2497d4be-cebc-4f59-b7e5-6adc96bf591d', '詩三百三首 二六二', '诗三百三首 二六二', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["平野水寬闊，丹丘連四明。","仙都最高秀，羣峰聳翠屏。","遠遠望何極，矹矹勢相迎。","獨標海隅外，處處播嘉名。"]', '["平野水寬闊，丹丘連四明。","仙都最高秀，羣峰聳翠屏。","远远望何極，矹矹勢相迎。","独標海隅外，处处播嘉名。"]', '诗', 'shi', '', NULL, '詩三百三首 二六二 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dfa1d04f-e432-484b-830a-9e57737dd0ea', '詩三百三首 二六三', '诗三百三首 二六三', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["可貴一名山，七寶何能比。","松月颼颼冷，雲霞片片起。","匼匝幾重山，迴還多少里。","谿澗靜澄澄，快活無窮已。"]', '["可貴一名山，七寶何能比。","松月颼颼冷，云霞片片起。","匼匝幾重山，迴還多少里。","谿澗静澄澄，快活無窮已。"]', '诗', 'shi', '', NULL, '詩三百三首 二六三 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('89c04fe6-7c9e-42c3-abf0-376a077f845a', '詩三百三首 二六四', '诗三百三首 二六四', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["我見世間人，生而還復死。","昨朝猶二八，壯氣胸襟士。","如今七十過，力困形憔悴。","恰似春日花，朝開夜落爾。"]', '["我见世间人，生而還复死。","昨朝猶二八，壯氣胸襟士。","如今七十過，力困形憔悴。","恰似春日花，朝开夜落爾。"]', '诗', 'shi', '', NULL, '詩三百三首 二六四 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('50be911e-f92a-477e-9bcd-d7547bf723fb', '詩三百三首 二六五', '诗三百三首 二六五', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["迴聳霄漢外，雲裏路岧嶢。","瀑布千丈流，如鋪練一條。","下有棲心窟，橫安定命橋。","雄雄鎮世界，天台名獨超。"]', '["迴聳霄漢外，云裏路岧嶢。","瀑布千丈流，如鋪練一條。","下有棲心窟，橫安定命橋。","雄雄鎮世界，天台名独超。"]', '诗', 'shi', '', NULL, '詩三百三首 二六五 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cd5e00ba-d16b-42d8-a33a-5392ca583720', '詩三百三首 二六六', '诗三百三首 二六六', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["盤陀石上坐，谿澗冷淒淒。","靜翫偏嘉麗，虛巖蒙霧迷。","怡然憩歇處，日斜樹影低。","我自觀心地，蓮花出淤泥。"]', '["盤陀石上坐，谿澗冷淒淒。","静翫偏嘉丽，虛巖蒙霧迷。","怡然憩歇处，日斜樹影低。","我自观心地，蓮花出淤泥。"]', '诗', 'shi', '', NULL, '詩三百三首 二六六 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d90dd753-4752-49e0-9cc6-4b15d861d5a1', '詩三百三首 二六七', '诗三百三首 二六七', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["隱士遁人間，多向山中眠。","青蘿疎麓麓，碧澗響聯聯。","騰騰且安樂，悠悠自清閑。","免有染世事，心靜如白蓮。"]', '["隐士遁人间，多向山中眠。","青蘿疎麓麓，碧澗响聯聯。","腾腾且安乐，悠悠自清闲。","免有染世事，心静如白蓮。"]', '诗', 'shi', '', NULL, '詩三百三首 二六七 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e0003917-cdba-4e06-9457-f3f463153dd5', '詩三百三首 二六八', '诗三百三首 二六八', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["寄語食肉漢，食時無逗遛。","今生過去種，未來今日修。","只取今日美，不畏來生憂。","老鼠入飯甕，雖飽難出頭。"]', '["寄語食肉漢，食时無逗遛。","今生過去種，未来今日修。","只取今日美，不畏来生憂。","老鼠入飯甕，雖飽难出头。"]', '诗', 'shi', '', NULL, '詩三百三首 二六八 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3b20d872-eca7-42f9-9480-511efba0c9ba', '詩三百三首 二六九', '诗三百三首 二六九', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["自從出家後，漸得養生趣。","伸縮四肢全，勤聽六根具。","褐衣隨春冬，糲食供朝暮。","今日懇懇修，願與佛相遇。"]', '["自從出家後，漸得養生趣。","伸縮四肢全，勤听六根具。","褐衣隨春冬，糲食供朝暮。","今日懇懇修，願與佛相遇。"]', '诗', 'shi', '', NULL, '詩三百三首 二六九 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7b4a1ad1-b238-4057-a9fc-be7f04134f15', '詩三百三首 二百七十', '诗三百三首 二百七十', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["五言五百篇，七字七十九。","三字二十一，都來六百首。","一例書巖石，自誇云好手。","若能會我詩，真是如來母。"]', '["五言五百篇，七字七十九。","三字二十一，都来六百首。","一例书巖石，自誇云好手。","若能會我诗，真是如来母。"]', '诗', 'shi', '', NULL, '詩三百三首 二百七十 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0ced3b7a-133f-4201-84e8-1b90f50ca9cc', '詩三百三首 二七一', '诗三百三首 二七一', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["世事繞悠悠，貪生早晚休。","研盡大地石，何時得歇頭。","四時周變易，八節急如流。","爲報火宅主，露地騎白牛。"]', '["世事繞悠悠，貪生早晚休。","研尽大地石，何时得歇头。","四时周变易，八節急如流。","爲報火宅主，露地騎白牛。"]', '诗', 'shi', '', NULL, '詩三百三首 二七一 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bfd3c4a9-901f-4e5a-b16e-b033ee011783', '詩三百三首 二七二', '诗三百三首 二七二', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["可笑五陰窟，四虵共同居。","黑暗無明燭，三毒遞相驅。","伴黨六箇賊，劫掠法財珠。","斬却魔軍輩，安泰湛如蘇。"]', '["可笑五陰窟，四虵共同居。","黑暗無明燭，三毒遞相驱。","伴黨六箇賊，劫掠法財珠。","斬却魔軍輩，安泰湛如蘇。"]', '诗', 'shi', '', NULL, '詩三百三首 二七二 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('df5916a1-8ebe-4324-bd0f-712c592e51a7', '詩三百三首 二七三', '诗三百三首 二七三', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["常聞漢武帝，爰及秦始皇。","俱好神仙術，延年竟不長。","金臺既摧折，沙丘遂滅亡。","茂陵與驪嶽，今日草茫茫。"]', '["常闻漢武帝，爰及秦始皇。","俱好神仙術，延年竟不长。","金台既摧折，沙丘遂滅亡。","茂陵與驪嶽，今日草茫茫。"]', '诗', 'shi', '', NULL, '詩三百三首 二七三 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c90b74ec-9b0b-4b39-a824-8e2529fa7228', '詩三百三首 二七四', '诗三百三首 二七四', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["憶得二十年，徐步國清歸。","國清寺中人，盡道寒山癡。","癡人何用疑，疑不解尋思。","我尚自不識，是伊爭得知。","低頭不用問，問得復何爲。","有人來駡我，分明了了知。","雖然不應對，却是得便宜。"]', '["憶得二十年，徐步国清归。","国清寺中人，尽道寒山癡。","癡人何用疑，疑不解尋思。","我尚自不識，是伊爭得知。","低头不用问，问得复何爲。","有人来駡我，分明了了知。","雖然不應对，却是得便宜。"]', '诗', 'shi', '', NULL, '詩三百三首 二七四 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('91f07eff-a48c-4faa-99c2-d92324f2a27c', '詩三百三首 二七五', '诗三百三首 二七五', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["語你出家輩，何名爲出家。","奢華求養活，繼綴族姓家。","美舌甜脣觜，諂曲心鉤加。","終日禮道場，持經置功課。","鑪燒神佛香，打鐘高聲和。","六時學客舂，晝夜不得臥。","只爲愛錢財，心中不脫灑。","見他高道人，却嫌誹謗駡。","驢屎比麝香，苦哉佛陀耶。","又見出家兒，有力及無力。","上上高節者，鬼神欽道德。","君王分輦坐，諸侯拜迎逆。","堪爲世福田，世人須保惜。","下下低愚者，詐現多求覓。","濁濫即可知，愚癡愛財色。","著却福田衣，種田討衣食。","作債稅牛犂，爲事不忠直。","朝朝行弊惡，往往痛臀脊。","不解善思量，地獄苦無極。","一朝著病纏，三年臥牀席。","亦有真佛性，翻作無明賊。","南無佛陀耶，遠遠求彌勒。"]', '["語你出家輩，何名爲出家。","奢华求養活，繼綴族姓家。","美舌甜脣觜，諂曲心鉤加。","終日禮道場，持經置功課。","鑪燒神佛香，打鐘高声和。","六时学客舂，晝夜不得臥。","只爲愛錢財，心中不脫灑。","见他高道人，却嫌誹謗駡。","驢屎比麝香，苦哉佛陀耶。","又见出家兒，有力及無力。","上上高節者，鬼神欽道德。","君王分輦坐，諸侯拜迎逆。","堪爲世福田，世人須保惜。","下下低愚者，詐現多求覓。","濁濫即可知，愚癡愛財色。","著却福田衣，種田討衣食。","作債稅牛犂，爲事不忠直。","朝朝行弊惡，往往痛臀脊。","不解善思量，地獄苦無極。","一朝著病纏，三年臥牀席。","亦有真佛性，翻作無明賊。","南無佛陀耶，远远求彌勒。"]', '诗', 'shi', '', NULL, '詩三百三首 二七五 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('538b6b5c-cfff-4e2a-8eb6-7d0c66c94758', '詩三百三首 二七六', '诗三百三首 二七六', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["寒巖深更好，無人行此道。","白雲高岫閑，青嶂孤猨嘯。","我更何所親，暢志自宜老。","形容寒暑遷，心珠甚可保。"]', '["寒巖深更好，無人行此道。","白云高岫闲，青嶂孤猨嘯。","我更何所親，暢志自宜老。","形容寒暑遷，心珠甚可保。"]', '诗', 'shi', '', NULL, '詩三百三首 二七六 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('10dc504b-7c32-40bd-8b66-9b6facbf28cb', '詩三百三首 二七七', '诗三百三首 二七七', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["巖前獨靜坐，圓月當天耀。","萬象影現中，一輪本無照。","廓然神自清，含虛洞玄妙。","因指見其月，月是心樞要。"]', '["巖前独静坐，圓月當天耀。","万象影現中，一輪本無照。","廓然神自清，含虛洞玄妙。","因指见其月，月是心樞要。"]', '诗', 'shi', '', NULL, '詩三百三首 二七七 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('77e8660e-f7c3-4627-9ce6-0f1fd0674b42', '詩三百三首 二七八', '诗三百三首 二七八', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["本志慕道倫，道倫常獲親。","時逢杜源客，每接話禪賓。","談玄月明夜，探理日臨晨。","萬機俱泯迹，方識本來人。"]', '["本志慕道倫，道倫常獲親。","时逢杜源客，每接話禪賓。","談玄月明夜，探理日臨晨。","万機俱泯迹，方識本来人。"]', '诗', 'shi', '', NULL, '詩三百三首 二七八 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1173eb0f-19cd-48e1-af97-d35dbd836a5a', '詩三百三首 二七九', '诗三百三首 二七九', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["元非隱逸士，自號山林人。","仕魯蒙幘帛，且愛裹疎巾。","道有巢許操，恥爲堯舜臣。","獼猴罩帽子，學人避風塵。"]', '["元非隐逸士，自號山林人。","仕魯蒙幘帛，且愛裹疎巾。","道有巢許操，恥爲堯舜臣。","獼猴罩帽子，学人避风塵。"]', '诗', 'shi', '', NULL, '詩三百三首 二七九 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1143abb6-7d2a-43bb-9667-2850fc256546', '詩三百三首 二百八十', '诗三百三首 二百八十', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["自古諸哲人，不見有長存。","生而還復死，盡變作灰塵。","積骨如毘富，別淚成海津。","唯有空名在，豈免生死輪。"]', '["自古諸哲人，不见有长存。","生而還复死，尽变作灰塵。","積骨如毘富，別泪成海津。","唯有空名在，豈免生死輪。"]', '诗', 'shi', '', NULL, '詩三百三首 二百八十 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0af27f99-afc3-4e02-9897-6bb2b13f1ab4', '詩三百三首 二八一', '诗三百三首 二八一', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["今日巖前坐，坐久煙雲收。","一道清谿冷，千尋碧嶂頭。","白雲朝影靜，明月夜光浮。","身上無塵垢，心中那更憂。"]', '["今日巖前坐，坐久煙云收。","一道清谿冷，千尋碧嶂头。","白云朝影静，明月夜光浮。","身上無塵垢，心中那更憂。"]', '诗', 'shi', '', NULL, '詩三百三首 二八一 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d3ba7932-0f66-463a-ac6b-0860a7800656', '詩三百三首 二八二', '诗三百三首 二八二', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["千雲萬水間，中有一閑士。","白日遊青山，夜歸巖下睡。","倐爾過春秋，寂然無塵累。","快哉何所依，靜若秋江水。"]', '["千云万水间，中有一闲士。","白日游青山，夜归巖下睡。","倐爾過春秋，寂然無塵累。","快哉何所依，静若秋江水。"]', '诗', 'shi', '', NULL, '詩三百三首 二八二 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6562fdf2-2b7b-496d-9289-eb39abe1689e', '詩三百三首 二八三', '诗三百三首 二八三', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["勸你休去來，莫惱他閻老。","失脚入三途，粉骨遭千擣。","長爲地獄人，永隔今生道。","勉你信余言，識取衣中寶。"]', '["勸你休去来，莫惱他閻老。","失脚入三途，粉骨遭千擣。","长爲地獄人，永隔今生道。","勉你信余言，識取衣中寶。"]', '诗', 'shi', '', NULL, '詩三百三首 二八三 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1207a8ad-eacc-4211-9a45-1a75498a1ab3', '詩三百三首 二八四', '诗三百三首 二八四', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["世間一等流，誠堪與人笑。","出家弊己身，誑俗將爲道。","雖著離塵衣，衣中多養蚤。","不如歸去來，識取心王好。"]', '["世间一等流，誠堪與人笑。","出家弊己身，誑俗將爲道。","雖著離塵衣，衣中多養蚤。","不如归去来，識取心王好。"]', '诗', 'shi', '', NULL, '詩三百三首 二八四 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fb2d1e01-96e7-4fdd-b063-448e59f1f812', '詩三百三首 二八五', '诗三百三首 二八五', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["高高峰頂上，四顧極無邊。","獨坐無人知，孤月照寒泉。","泉中且無月，月自在青天。","吟此一曲歌，歌終不是禪。"]', '["高高峰頂上，四顧極無邊。","独坐無人知，孤月照寒泉。","泉中且無月，月自在青天。","吟此一曲歌，歌終不是禪。"]', '诗', 'shi', '', NULL, '詩三百三首 二八五 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f39bfe8b-aca3-4314-bf98-906050cad29b', '詩三百三首 二八六', '诗三百三首 二八六', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["有箇王秀才，笑我詩多失。","云不識蜂腰，仍不會鶴膝。","平側不解壓，凡言取次出。","我笑你作詩，如盲徒詠日。"]', '["有箇王秀才，笑我诗多失。","云不識蜂腰，仍不會鹤膝。","平側不解壓，凡言取次出。","我笑你作诗，如盲徒詠日。"]', '诗', 'shi', '', NULL, '詩三百三首 二八六 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b4fbdb3-3752-4218-80b1-3ccad0773062', '詩三百三首 二八七', '诗三百三首 二八七', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["我住在村鄉，無爺亦無娘。","無名無姓第，人喚作張王。","並無人教我，貧賤也尋常。","自憐心的實，堅固等金剛。"]', '["我住在村乡，無爺亦無娘。","無名無姓第，人喚作張王。","並無人教我，貧賤也尋常。","自怜心的實，堅固等金剛。"]', '诗', 'shi', '', NULL, '詩三百三首 二八七 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0b4d7f69-137f-4cba-9f64-11bf035b7d97', '詩三百三首 二八八', '诗三百三首 二八八', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["寒山出此語，此語無人信。","蜜甜足人嘗，黃蘖苦難近。","順情生喜悅，逆意多瞋恨。","但看木傀儡，弄了一場困。"]', '["寒山出此語，此語無人信。","蜜甜足人嘗，黄蘖苦难近。","順情生喜悅，逆意多瞋恨。","但看木傀儡，弄了一場困。"]', '诗', 'shi', '', NULL, '詩三百三首 二八八 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('017f4e49-0d22-46df-b78b-3b3c24da8479', '詩三百三首 二八九', '诗三百三首 二八九', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["我見人轉經，依他言語會。","口轉心不轉，心口相違背。","心真無委曲，不作諸纏蓋。","但且自省躬，莫覓他替代。","可中作得主，是知無內外。"]', '["我见人轉經，依他言語會。","口轉心不轉，心口相違背。","心真無委曲，不作諸纏蓋。","但且自省躬，莫覓他替代。","可中作得主，是知無內外。"]', '诗', 'shi', '', NULL, '詩三百三首 二八九 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba5b163e-3410-462d-8b09-d6786f14afe4', '詩三百三首 二百九十', '诗三百三首 二百九十', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["寒山唯白雲，寂寂絕埃塵。","草座山家有，孤燈明月輪。","石牀臨碧沼，虎鹿每爲鄰。","自羨幽居樂，長爲象外人。"]', '["寒山唯白云，寂寂絕埃塵。","草座山家有，孤灯明月輪。","石牀臨碧沼，虎鹿每爲鄰。","自羨幽居乐，长爲象外人。"]', '诗', 'shi', '', NULL, '詩三百三首 二百九十 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('89e33d58-330e-4ef9-8ee0-140fa2e7fdde', '詩三百三首 二九一', '诗三百三首 二九一', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["鹿生深林中，飲水而食草。","伸脚樹下眠，可憐無煩惱。","繫之在華堂，餚饍極肥好。","終日不肯嘗，形容轉枯槁。"]', '["鹿生深林中，饮水而食草。","伸脚樹下眠，可怜無煩惱。","繫之在华堂，餚饍極肥好。","終日不肯嘗，形容轉枯槁。"]', '诗', 'shi', '', NULL, '詩三百三首 二九一 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7560f136-682a-4587-b784-ef14ea6da691', '詩三百三首 二九二', '诗三百三首 二九二', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["花上黃鶯子，𠴨𠴨聲可憐。","美人顏似玉，對此弄鳴弦。","翫之能不足，眷戀在齠年。","花飛鳥亦散，灑淚秋風前。"]', '["花上黄鶯子，𠴨𠴨声可怜。","美人顏似玉，对此弄鳴弦。","翫之能不足，眷戀在齠年。","花飞鸟亦散，灑泪秋风前。"]', '诗', 'shi', '', NULL, '詩三百三首 二九二 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a1a884a3-a38d-4a20-a6c6-a429787b7b96', '詩三百三首 二九三', '诗三百三首 二九三', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["棲遲寒巖下，偏訝最幽奇。","攜籃采山茹，挈籠摘果歸。","䔫齋敷茅坐，啜啄食紫芝。","清沼濯瓢鉢，雜和煮稠稀。","當陽擁裘坐，閑讀古人詩。"]', '["棲遲寒巖下，偏訝最幽奇。","携籃采山茹，挈籠摘果归。","䔫斋敷茅坐，啜啄食紫芝。","清沼濯瓢鉢，杂和煮稠稀。","當陽擁裘坐，闲读古人诗。"]', '诗', 'shi', '', NULL, '詩三百三首 二九三 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('40f40f5a-de46-4638-a01b-87baaf42eac1', '詩三百三首 二九四', '诗三百三首 二九四', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["昔日經行處，今復七十年。","故人無來往，埋在古冢間。","余今頭已白，猶守片雲山。","爲報後來子，何不讀古言。"]', '["昔日經行处，今复七十年。","故人無来往，埋在古冢间。","余今头已白，猶守片云山。","爲報後来子，何不读古言。"]', '诗', 'shi', '', NULL, '詩三百三首 二九四 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('159deba0-65ce-4469-b8c3-dc229d511fe4', '詩三百三首 二九五', '诗三百三首 二九五', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["欲向東巖去，于今無量年。","昨來攀葛上，半路困風煙。","徑窄衣難進，苔黏履不全。","住茲丹桂下，且枕白雲眠。"]', '["欲向东巖去，于今無量年。","昨来攀葛上，半路困风煙。","徑窄衣难進，苔黏履不全。","住茲丹桂下，且枕白云眠。"]', '诗', 'shi', '', NULL, '詩三百三首 二九五 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a06b50e-f53a-4611-9e2a-ea91d3845032', '詩三百三首 二九六', '诗三百三首 二九六', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["我見利智人，觀者便知意。","不假尋文字，直入如來地。","心不逐諸緣，意根不妄起。","心意不生時，內外無餘事。"]', '["我见利智人，观者便知意。","不假尋文字，直入如来地。","心不逐諸緣，意根不妄起。","心意不生时，內外無餘事。"]', '诗', 'shi', '', NULL, '詩三百三首 二九六 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('12a5d604-f4e5-4df8-bb81-94f9bdedb60e', '詩三百三首 二九七', '诗三百三首 二九七', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["身著空花衣，足躡龜毛履。","手把兔角弓，擬射無明鬼。"]', '["身著空花衣，足躡龟毛履。","手把兔角弓，擬射無明鬼。"]', '诗', 'shi', '', NULL, '詩三百三首 二九七 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f81690db-a5e7-4c6b-b648-9138aea108e4', '詩三百三首 二九八', '诗三百三首 二九八', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["君看葉裏花，能得幾時好。","今日畏人攀，明朝待誰埽。","可憐嬌豔情，年多轉成老。","將世比於花，紅顏豈長保。"]', '["君看葉裏花，能得幾时好。","今日畏人攀，明朝待誰埽。","可怜嬌豔情，年多轉成老。","將世比於花，紅顏豈长保。"]', '诗', 'shi', '', NULL, '詩三百三首 二九八 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('659ae405-233a-424d-9741-389c871f5a55', '詩三百三首 二九九', '诗三百三首 二九九', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["畫棟非吾宅，松林是我家。","一生俄爾過，萬事莫言賒。","濟渡不造筏，漂淪爲采花。","善根今未種，何日見生芽。"]', '["畫棟非吾宅，松林是我家。","一生俄爾過，万事莫言賒。","濟渡不造筏，漂淪爲采花。","善根今未種，何日见生芽。"]', '诗', 'shi', '', NULL, '詩三百三首 二九九 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1870cbee-d3f0-4cae-a93f-7d323eaa8cb3', '詩三百三首 三百', '诗三百三首 三百', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["出生三十年，當遊千萬里。","行江青草合，入塞紅塵起。","鍊藥空求仙，讀書兼詠史。","今日歸寒山，枕流兼洗耳。"]', '["出生三十年，當游千万里。","行江青草合，入塞紅塵起。","鍊藥空求仙，读书兼詠史。","今日归寒山，枕流兼洗耳。"]', '诗', 'shi', '', NULL, '詩三百三首 三百 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('55254dda-b67a-4fd7-ad18-7ef3770d0ad7', '詩三百三首 三百一', '诗三百三首 三百一', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["寒山無漏巖，其巖甚濟要。","八風吹不動，萬古人傳妙。","寂寂好安居，空空離譏誚。","孤月夜長明，圓日常來照。","虎丘兼虎谿，不用相呼召。","世間有王傅，莫把同周邵。","我自遯寒巖，快活長歌笑。"]', '["寒山無漏巖，其巖甚濟要。","八风吹不动，万古人傳妙。","寂寂好安居，空空離譏誚。","孤月夜长明，圓日常来照。","虎丘兼虎谿，不用相呼召。","世间有王傅，莫把同周邵。","我自遯寒巖，快活长歌笑。"]', '诗', 'shi', '', NULL, '詩三百三首 三百一 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f20a6c1c-2231-4176-8942-345adbcb87d7', '詩三百三首 三百二', '诗三百三首 三百二', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["沙門不持戒，道士不服藥。","自古多少賢，盡在青山脚。"]', '["沙门不持戒，道士不服藥。","自古多少賢，尽在青山脚。"]', '诗', 'shi', '', NULL, '詩三百三首 三百二 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('99ac6989-56ed-471d-a852-18587221d33d', '詩三百三首 三百三', '诗三百三首 三百三', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["有人笑我詩，我詩合典雅。","不煩鄭氏箋，豈用毛公解。","不恨會人稀，只爲知音寡。","若遣趁宮商，余病莫能罷。","忽遇明眼人，即自流天下。"]', '["有人笑我诗，我诗合典雅。","不煩鄭氏箋，豈用毛公解。","不恨會人稀，只爲知音寡。","若遣趁宮商，余病莫能罷。","忽遇明眼人，即自流天下。"]', '诗', 'shi', '', NULL, '詩三百三首 三百三 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('184470e1-61f8-4207-88c2-842a0f1eda68', '三字詩六首 一', '三字诗六首 一', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["寒山道，無人到。","若能行，稱十號。","有蟬鳴，無鴉噪。","黃葉落，白雲掃。","石磊磊，山隩隩。","我獨居，名善導。","子細看，何相好。"]', '["寒山道，無人到。","若能行，稱十號。","有蟬鳴，無鴉噪。","黄葉落，白云掃。","石磊磊，山隩隩。","我独居，名善導。","子細看，何相好。"]', '诗', 'shi', '', NULL, '三字詩六首 一 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c6de9a95-a9d4-4f8e-a0a2-00f7956aca73', '三字詩六首 二', '三字诗六首 二', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["寒山寒，冰鎖石。","藏山青，現雪白。","日出照，一時釋。","從茲暖，養老客。"]', '["寒山寒，冰鎖石。","藏山青，現雪白。","日出照，一时釋。","從茲暖，養老客。"]', '诗', 'shi', '', NULL, '三字詩六首 二 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('47ce7bc3-15c4-4047-89b5-1cf084bfbdc2', '三字詩六首 三', '三字诗六首 三', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["我居山，勿人識。","白雲中，常寂寂。"]', '["我居山，勿人識。","白云中，常寂寂。"]', '诗', 'shi', '', NULL, '三字詩六首 三 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('005dc730-afdf-4827-9c1b-af507d164bdd', '三字詩六首 四', '三字诗六首 四', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["寒山深，稱我心。","純白石，勿黃金。","泉聲響，撫伯琴。","有子期，辨此音。"]', '["寒山深，稱我心。","純白石，勿黄金。","泉声响，撫伯琴。","有子期，辨此音。"]', '诗', 'shi', '', NULL, '三字詩六首 四 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9d8d4672-ae46-4a04-a0d1-caa2c1d94d89', '三字詩六首 五', '三字诗六首 五', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["重巖中，足清風。","扇不搖，涼冷通。","明月照，白雲籠。","獨自坐，一老翁。"]', '["重巖中，足清风。","扇不搖，涼冷通。","明月照，白云籠。","独自坐，一老翁。"]', '诗', 'shi', '', NULL, '三字詩六首 五 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9db32987-bc33-4d8a-9571-b822940a56dd', '三字詩六首 六', '三字诗六首 六', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["寒山子，長如是。","獨自居，不生死。"]', '["寒山子，长如是。","独自居，不生死。"]', '诗', 'shi', '', NULL, '三字詩六首 六 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ddd47e2-07ed-4874-8226-35e67daa6222', '拾遺二首新添 一', '拾遺二首新添 一', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["我見世間人，箇箇爭意氣。","一朝忽然死，只得一片地。","闊四尺，長丈二。","汝若會出來爭意氣，我與汝立碑記。"]', '["我见世间人，箇箇爭意氣。","一朝忽然死，只得一片地。","闊四尺，长丈二。","汝若會出来爭意氣，我與汝立碑記。"]', '诗', 'shi', '', NULL, '拾遺二首新添 一 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('09342d24-38a0-4a9d-b857-e9b0c56e30f7', '拾遺二首新添 二', '拾遺二首新添 二', 'ed74d121-b676-4e2c-bc3a-a7caa9a6b678', '唐', '["家有寒山詩，勝汝看經卷。","書放屏風上，時時看一徧。"]', '["家有寒山诗，勝汝看經卷。","书放屏风上，时时看一徧。"]', '诗', 'shi', '', NULL, '拾遺二首新添 二 寒山 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('aac347ef-a941-4d60-a4dc-653708ba6d3f', '詩 一', '诗 一', '869aadce-f094-4a70-aa24-0ff143c2877b', '唐', '["諸佛留藏經，只爲人難化。","不唯賢與愚，箇箇心搆架。","造業大如山，豈解懷憂怕。","那肯細尋思，日夜懷姦詐。"]', '["諸佛留藏經，只爲人难化。","不唯賢與愚，箇箇心搆架。","造業大如山，豈解懷憂怕。","那肯細尋思，日夜懷姦詐。"]', '诗', 'shi', '', NULL, '詩 一 拾得 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('48d8112f-856e-43f7-8a0c-d7a9f4a169be', '詩 二', '诗 二', '869aadce-f094-4a70-aa24-0ff143c2877b', '唐', '["嗟見世間人，箇箇愛喫肉。","椀楪不曾乾，長時道不足。","昨日設箇齋，今朝宰六畜。","都緣業使牽，非干情所欲。","一度造天堂，百度造地獄。","閻羅使來追，合家盡啼哭。","鑪子邊向火，鑊子裏澡浴。","更得出頭時，換却汝衣服。"]', '["嗟见世间人，箇箇愛喫肉。","椀楪不曾乾，长时道不足。","昨日設箇斋，今朝宰六畜。","都緣業使牽，非干情所欲。","一度造天堂，百度造地獄。","閻羅使来追，合家尽啼哭。","鑪子邊向火，鑊子裏澡浴。","更得出头时，換却汝衣服。"]', '诗', 'shi', '', NULL, '詩 二 拾得 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26e830ef-d5ae-48fe-9f41-401d7d504aff', '詩 三', '诗 三', '869aadce-f094-4a70-aa24-0ff143c2877b', '唐', '["出家要清閑，清閑即爲貴。","如何塵外人，却入塵埃裏。","一向迷本心，終朝役名利。","名利得到身，形容已顦顇。","況復不遂者，虛用平生志。","可憐無事人，未能笑得爾。"]', '["出家要清闲，清闲即爲貴。","如何塵外人，却入塵埃裏。","一向迷本心，終朝役名利。","名利得到身，形容已顦顇。","況复不遂者，虛用平生志。","可怜無事人，未能笑得爾。"]', '诗', 'shi', '', NULL, '詩 三 拾得 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8abf04eb-d610-41d1-aeb9-31880fef84a4', '詩 四', '诗 四', '869aadce-f094-4a70-aa24-0ff143c2877b', '唐', '["養兒與娶妻，養女求媒娉。","重重皆是業，更殺衆生命。","聚集會親情，總來看盤飣。","目下雖稱心，罪簿先注定。"]', '["養兒與娶妻，養女求媒娉。","重重皆是業，更殺衆生命。","聚集會親情，總来看盤飣。","目下雖稱心，罪簿先注定。"]', '诗', 'shi', '', NULL, '詩 四 拾得 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('974100ce-dfec-4ca0-a07c-2ca96d504855', '詩 五', '诗 五', '869aadce-f094-4a70-aa24-0ff143c2877b', '唐', '["得此分叚身，可笑好形質。","面貌似銀盤，心中黑如漆。","烹豬又宰羊，誇道甜如蜜。","死後受波吒，更莫稱冤屈。"]', '["得此分叚身，可笑好形質。","面貌似銀盤，心中黑如漆。","烹豬又宰羊，誇道甜如蜜。","死後受波吒，更莫稱冤屈。"]', '诗', 'shi', '', NULL, '詩 五 拾得 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1352915a-1e91-4610-9e46-33321b4da70e', '詩 六', '诗 六', '869aadce-f094-4a70-aa24-0ff143c2877b', '唐', '["佛哀三界子，總是親男女。","恐沈黑暗阬，示儀垂化度。","盡登無上道，俱證菩提路。","教汝癡衆生，慧心勤覺悟。"]', '["佛哀三界子，總是親男女。","恐沈黑暗阬，示儀垂化度。","尽登無上道，俱證菩提路。","教汝癡衆生，慧心勤覺悟。"]', '诗', 'shi', '', NULL, '詩 六 拾得 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('85baf4c4-d265-41bf-9ec2-30f72cae1c6c', '詩 七', '诗 七', '869aadce-f094-4a70-aa24-0ff143c2877b', '唐', '["佛拾尊榮樂，爲愍諸癡子。","早願悟無生，辦集無上事。","後來出家者，多緣無業次。","不能得衣食，頭鑽入於寺。"]', '["佛拾尊榮乐，爲愍諸癡子。","早願悟無生，辦集無上事。","後来出家者，多緣無業次。","不能得衣食，头鑽入於寺。"]', '诗', 'shi', '', NULL, '詩 七 拾得 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4af6305e-3d2f-4b6e-847f-ed8358ab4cd7', '詩 八', '诗 八', '869aadce-f094-4a70-aa24-0ff143c2877b', '唐', '["嗟見世間人，永劫在迷津。","不省這箇意，修行徒苦辛。"]', '["嗟见世间人，永劫在迷津。","不省這箇意，修行徒苦辛。"]', '诗', 'shi', '', NULL, '詩 八 拾得 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26727de8-2e48-4266-929e-523e4d4b376f', '詩 九', '诗 九', '869aadce-f094-4a70-aa24-0ff143c2877b', '唐', '["我詩也是詩，有人喚作偈。","詩偈總一般，讀時須子細。","緩緩細披尋，不得生容易。","依此學修行，大有可笑事。"]', '["我诗也是诗，有人喚作偈。","诗偈總一般，读时須子細。","緩緩細披尋，不得生容易。","依此学修行，大有可笑事。"]', '诗', 'shi', '', NULL, '詩 九 拾得 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e43b50da-c190-467b-8e83-e74ee259088f', '詩 十', '诗 十', '869aadce-f094-4a70-aa24-0ff143c2877b', '唐', '["有偈有千萬，卒急述應難。","若要相知者，但入天台山。","巖中深處坐，說理及談玄。","共我不相見，對面似千山。"]', '["有偈有千万，卒急述應难。","若要相知者，但入天台山。","巖中深处坐，说理及談玄。","共我不相见，对面似千山。"]', '诗', 'shi', '', NULL, '詩 十 拾得 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3013fc18-8df3-47de-9f1a-f4589a058aa2', '詩 十一', '诗 十一', '869aadce-f094-4a70-aa24-0ff143c2877b', '唐', '["世間億萬人，面孔不相似。","借問何因緣，致令遣如此。","各執一般見，互說非兼是。","但自修己身，不要言他已。"]', '["世间億万人，面孔不相似。","借问何因緣，致令遣如此。","各執一般见，互说非兼是。","但自修己身，不要言他已。"]', '诗', 'shi', '', NULL, '詩 十一 拾得 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e9c31969-18b8-4b3b-9474-53fe5556babb', '詩 十二', '诗 十二', '869aadce-f094-4a70-aa24-0ff143c2877b', '唐', '["男女爲婚嫁，俗務是常儀。","自量其事力，何用廣張施。","取債誇人我，論情入骨癡。","殺他雞犬命，身死墮阿鼻。"]', '["男女爲婚嫁，俗務是常儀。","自量其事力，何用廣張施。","取債誇人我，論情入骨癡。","殺他雞犬命，身死墮阿鼻。"]', '诗', 'shi', '', NULL, '詩 十二 拾得 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('56077cce-5478-41a7-8738-9b11e683c7ab', '詩 十三', '诗 十三', '869aadce-f094-4a70-aa24-0ff143c2877b', '唐', '["世上一種人，出性常多事。","終日傍街衢，不離諸酒肆。","爲他作保見，替他說道理。","一朝有乖張，過咎全歸你。"]', '["世上一種人，出性常多事。","終日傍街衢，不離諸酒肆。","爲他作保见，替他说道理。","一朝有乖張，過咎全归你。"]', '诗', 'shi', '', NULL, '詩 十三 拾得 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d9002e68-7b4c-4c5a-afb9-46228f2889ff', '詩 十四', '诗 十四', '869aadce-f094-4a70-aa24-0ff143c2877b', '唐', '["我勸出家輩，須知教法深。","專心求出離，輒莫染貪淫。","大有俗中士，知非不愛金。","故知君子志，任運聽浮沈。"]', '["我勸出家輩，須知教法深。","專心求出離，輒莫染貪淫。","大有俗中士，知非不愛金。","故知君子志，任運听浮沈。"]', '诗', 'shi', '', NULL, '詩 十四 拾得 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7bc81ce2-0e1b-4043-83fc-fdeb4312f369', '詩 十五', '诗 十五', '869aadce-f094-4a70-aa24-0ff143c2877b', '唐', '["寒山住寒山，拾得自拾得。","凡愚豈見知，豐干却相識。","見時不可見，覓時何處覓。","借問有何緣，却道無爲力。"]', '["寒山住寒山，拾得自拾得。","凡愚豈见知，豐干却相識。","见时不可见，覓时何处覓。","借问有何緣，却道無爲力。"]', '诗', 'shi', '', NULL, '詩 十五 拾得 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c9d855d9-d87f-45af-974e-cb6c86c75bda', '詩 十六', '诗 十六', '869aadce-f094-4a70-aa24-0ff143c2877b', '唐', '["從來是拾得，不是偶然稱。","別無親眷屬，寒山是我兄。","兩人心相似，誰能徇俗情。","若問年多少，黃河幾度清。"]', '["從来是拾得，不是偶然稱。","別無親眷屬，寒山是我兄。","兩人心相似，誰能徇俗情。","若问年多少，黄河幾度清。"]', '诗', 'shi', '', NULL, '詩 十六 拾得 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2ddc907a-c1b3-4669-b4ed-18690160b8e2', '詩 十七', '诗 十七', '869aadce-f094-4a70-aa24-0ff143c2877b', '唐', '["若解捉老鼠，不在五白猫。","若能悟理性，那由錦繡包。","真珠入席袋，佛性止蓬茅。","一羣取相漢，用意總無交。"]', '["若解捉老鼠，不在五白猫。","若能悟理性，那由錦繡包。","真珠入席袋，佛性止蓬茅。","一羣取相漢，用意總無交。"]', '诗', 'shi', '', NULL, '詩 十七 拾得 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3956c666-98cd-499d-9301-b972d231e3b1', '詩 十八', '诗 十八', '869aadce-f094-4a70-aa24-0ff143c2877b', '唐', '["運心常寬廣，此則名爲布。","輟己惠於人，方可名爲施。","後來人不知，焉能會此義。","未設一庸僧，早擬望富貴。"]', '["運心常寬廣，此則名爲布。","輟己惠於人，方可名爲施。","後来人不知，焉能會此義。","未設一庸僧，早擬望富貴。"]', '诗', 'shi', '', NULL, '詩 十八 拾得 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('53f2dc02-4b4b-48e3-b593-7e52befc7a68', '詩 十九', '诗 十九', '869aadce-f094-4a70-aa24-0ff143c2877b', '唐', '["獼猴尚教得，人何不憤發。","前車即落阬，後車須改轍。","若也不知此，恐君惡合殺。","此來是夜叉，變即成菩薩。"]', '["獼猴尚教得，人何不憤發。","前车即落阬，後车須改轍。","若也不知此，恐君惡合殺。","此来是夜叉，变即成菩薩。"]', '诗', 'shi', '', NULL, '詩 十九 拾得 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b52f4213-2e90-43b3-86fc-f1d5a928e3b0', '詩 二十', '诗 二十', '869aadce-f094-4a70-aa24-0ff143c2877b', '唐', '["自從到此天台寺，經今早已幾冬春。","山水不移人自老，見却多少後生人。"]', '["自從到此天台寺，經今早已幾冬春。","山水不移人自老，见却多少後生人。"]', '诗', 'shi', '', NULL, '詩 二十 拾得 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b6f92f3d-a91e-4c75-a133-54ea28d96d31', '詩 二十一', '诗 二十一', '869aadce-f094-4a70-aa24-0ff143c2877b', '唐', '["君不見三界之中紛擾擾，只爲無明不了絕。","一念不生心澄然，無去無來不生滅。"]', '["君不见三界之中紛擾擾，只爲無明不了絕。","一念不生心澄然，無去無来不生滅。"]', '诗', 'shi', '', NULL, '詩 二十一 拾得 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('72822367-bfd2-42b7-b3cb-9adf6ddc1356', '詩 二十二', '诗 二十二', '869aadce-f094-4a70-aa24-0ff143c2877b', '唐', '["故林又斬新，剡源谿上人。","天姥峽關嶺，通同次海津。","灣深曲島間，淼淼水雲雲。","借問松禪客，日輪何處暾。"]', '["故林又斬新，剡源谿上人。","天姥峽关嶺，通同次海津。","灣深曲島间，淼淼水云云。","借问松禪客，日輪何处暾。"]', '诗', 'shi', '', NULL, '詩 二十二 拾得 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e02aeec7-88d3-4ff0-8520-6bce8a01895a', '詩 二十三', '诗 二十三', '869aadce-f094-4a70-aa24-0ff143c2877b', '唐', '["自笑老夫筋力敗，偏戀松巖愛獨遊。","可歎往年至今日，任運還同不繫舟。"]', '["自笑老夫筋力敗，偏戀松巖愛独游。","可歎往年至今日，任運還同不繫舟。"]', '诗', 'shi', '', NULL, '詩 二十三 拾得 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('56ecf12c-72e9-46d8-a372-33ecb101c9a0', '詩 二十四', '诗 二十四', '869aadce-f094-4a70-aa24-0ff143c2877b', '唐', '["一入雙谿不計春，鍊暴黃精幾許斤。","鑪竈石鍋頻煮沸，土甑久烝氣味珍。","誰來幽谷餐仙食，獨向雲泉更勿人。","延齡壽盡招手石，此棲終不出山門。"]', '["一入雙谿不計春，鍊暴黄精幾許斤。","鑪竈石鍋頻煮沸，土甑久烝氣味珍。","誰来幽谷餐仙食，独向云泉更勿人。","延齡壽尽招手石，此棲終不出山门。"]', '诗', 'shi', '', NULL, '詩 二十四 拾得 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('beef07d9-a266-494a-bbda-b99d7aa4544a', '詩 二十五', '诗 二十五', '869aadce-f094-4a70-aa24-0ff143c2877b', '唐', '["躑躅一羣羊，沿山又入谷。","看人貪竹塞，且遭豺狼逐。","元不出孳生，便將充口腹。","從頭喫至尾，𩚛𩚛無餘肉。"]', '["躑躅一羣羊，沿山又入谷。","看人貪竹塞，且遭豺狼逐。","元不出孳生，便將充口腹。","從头喫至尾，𩚛𩚛無餘肉。"]', '诗', 'shi', '', NULL, '詩 二十五 拾得 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c7863b2-4f3c-4f51-8a99-4d1ead6f4618', '詩 二十六', '诗 二十六', '869aadce-f094-4a70-aa24-0ff143c2877b', '唐', '["銀星釘稱衡，綠絲作稱紐。","買人推向前，賣人推向後。","不顧他心怨，唯言我好手。","死去見閻王，背後插掃箒。"]', '["銀星釘稱衡，綠絲作稱紐。","買人推向前，賣人推向後。","不顧他心怨，唯言我好手。","死去见閻王，背後插掃箒。"]', '诗', 'shi', '', NULL, '詩 二十六 拾得 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b2e5087d-abf9-4653-8e07-74cff95dcf01', '詩 二十七', '诗 二十七', '869aadce-f094-4a70-aa24-0ff143c2877b', '唐', '["閉門私造罪，準擬免災殃。","被他惡部童，抄得報閻王。","縱不入鑊湯，亦須臥鐵牀。","不許雇人替，自作自身當。"]', '["閉门私造罪，準擬免災殃。","被他惡部童，抄得報閻王。","縱不入鑊湯，亦須臥鐵牀。","不許雇人替，自作自身當。"]', '诗', 'shi', '', NULL, '詩 二十七 拾得 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b3be1672-0ade-4d31-9126-c782aa300564', '詩 二十八', '诗 二十八', '869aadce-f094-4a70-aa24-0ff143c2877b', '唐', '["悠悠塵裏人，常道塵中樂。","我見塵中人，心生多慜顧。","何哉慜此流，念彼塵中苦。"]', '["悠悠塵裏人，常道塵中乐。","我见塵中人，心生多慜顧。","何哉慜此流，念彼塵中苦。"]', '诗', 'shi', '', NULL, '詩 二十八 拾得 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e5ba6574-18be-4192-ab2f-7888f924db31', '詩 二十九', '诗 二十九', '869aadce-f094-4a70-aa24-0ff143c2877b', '唐', '["無去無來本湛然，不居內外及中間。","一顆水精絕瑕翳，光明透滿出人天。"]', '["無去無来本湛然，不居內外及中间。","一顆水精絕瑕翳，光明透满出人天。"]', '诗', 'shi', '', NULL, '詩 二十九 拾得 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('27779fe9-3492-4af0-a98f-51c106f4f2e8', '詩 三十', '诗 三十', '869aadce-f094-4a70-aa24-0ff143c2877b', '唐', '["少年學書劒，叱馭到荆州。","聞伐匈奴盡，婆娑無處遊。","歸來翠巖下，席草翫清流。","壯士志未騁，獼猴騎土牛。"]', '["少年学书劒，叱馭到荆州。","闻伐匈奴尽，婆娑無处游。","归来翠巖下，席草翫清流。","壯士志未騁，獼猴騎土牛。"]', '诗', 'shi', '', NULL, '詩 三十 拾得 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('94af3e39-cd84-4d8a-9db4-fb3201ea6b9c', '詩 三十一', '诗 三十一', '869aadce-f094-4a70-aa24-0ff143c2877b', '唐', '["三界如轉輪，浮生若流水。","蠢蠢諸品類，貪生不覺死。","汝看朝垂露，能得幾時子。"]', '["三界如轉輪，浮生若流水。","蠢蠢諸品類，貪生不覺死。","汝看朝垂露，能得幾时子。"]', '诗', 'shi', '', NULL, '詩 三十一 拾得 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('25e4460e-33bd-4fda-8590-7e1d5829dc4d', '詩 三十二', '诗 三十二', '869aadce-f094-4a70-aa24-0ff143c2877b', '唐', '["閑入天台洞，訪人人不知。","寒山爲伴侶，松下噉靈芝。","每談今古事，嗟見世愚癡。","箇箇入地獄，早晚出頭時。"]', '["闲入天台洞，訪人人不知。","寒山爲伴侶，松下噉靈芝。","每談今古事，嗟见世愚癡。","箇箇入地獄，早晚出头时。"]', '诗', 'shi', '', NULL, '詩 三十二 拾得 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ef4ff31-d4c4-4651-89ed-c80b17dfd906', '詩 三十三', '诗 三十三', '869aadce-f094-4a70-aa24-0ff143c2877b', '唐', '["古佛路淒淒，愚人到却迷。","只緣前業重，所以不能知。","欲識無爲理，心中不挂絲。","生生勤苦學，必定覩天師。"]', '["古佛路淒淒，愚人到却迷。","只緣前業重，所以不能知。","欲識無爲理，心中不挂絲。","生生勤苦学，必定覩天師。"]', '诗', 'shi', '', NULL, '詩 三十三 拾得 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('82b8f42d-f230-4199-8df0-8c70eacee5c8', '詩 三十四', '诗 三十四', '869aadce-f094-4a70-aa24-0ff143c2877b', '唐', '["各有天真佛，號之爲寶王。","珠光日夜照，玄妙卒難量。","盲人常兀兀，那肯怕災殃。","唯貪淫泆業，此輩實堪傷。"]', '["各有天真佛，號之爲寶王。","珠光日夜照，玄妙卒难量。","盲人常兀兀，那肯怕災殃。","唯貪淫泆業，此輩實堪傷。"]', '诗', 'shi', '', NULL, '詩 三十四 拾得 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('28f4edea-260a-4ab3-aa5f-dd35b4619900', '詩 三十五', '诗 三十五', '869aadce-f094-4a70-aa24-0ff143c2877b', '唐', '["出家求出離，哀念苦衆生。","助佛爲揚化，令教選路行。","何曾解救苦，恣意亂縱橫。","一時同受溺，俱落大深阬。"]', '["出家求出離，哀念苦衆生。","助佛爲揚化，令教選路行。","何曾解救苦，恣意亂縱橫。","一时同受溺，俱落大深阬。"]', '诗', 'shi', '', NULL, '詩 三十五 拾得 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('476e4733-9bc0-423e-8d77-9e4733a943cb', '詩 三十六', '诗 三十六', '869aadce-f094-4a70-aa24-0ff143c2877b', '唐', '["常飲三毒酒，昏昏都不知。","將錢作夢事，夢事成鐵圍。","以苦欲捨苦，捨苦無出期。","應須早覺悟，覺悟自歸依。"]', '["常饮三毒酒，昏昏都不知。","將錢作梦事，梦事成鐵圍。","以苦欲捨苦，捨苦無出期。","應須早覺悟，覺悟自归依。"]', '诗', 'shi', '', NULL, '詩 三十六 拾得 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a00d070-3f27-44a0-95dd-b157b1f79da7', '詩 三十七', '诗 三十七', '869aadce-f094-4a70-aa24-0ff143c2877b', '唐', '["雲山疊疊幾千重，幽谷路深絕人蹤。","碧澗清流多勝境，時來鳥語合人心。"]', '["云山叠叠幾千重，幽谷路深絕人蹤。","碧澗清流多勝境，时来鸟語合人心。"]', '诗', 'shi', '', NULL, '詩 三十七 拾得 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4cbd9de0-47ba-4c95-8575-d9ae3a1d51c4', '詩 三十八', '诗 三十八', '869aadce-f094-4a70-aa24-0ff143c2877b', '唐', '["後來出家子，論情入骨癡。","本來求解脫，却見受驅馳。","終朝遊俗舍，禮念作威儀。","博錢沽酒喫，翻成客作兒。"]', '["後来出家子，論情入骨癡。","本来求解脫，却见受驱驰。","終朝游俗舍，禮念作威儀。","博錢沽酒喫，翻成客作兒。"]', '诗', 'shi', '', NULL, '詩 三十八 拾得 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f222d508-d85d-4ec8-b76a-25c762d67b68', '詩 三十九', '诗 三十九', '869aadce-f094-4a70-aa24-0ff143c2877b', '唐', '["若論常快活，唯有隱居人。","林花長似錦，四季色常新。","或向巖間坐，旋瞻見桂輪。","雖然身暢逸，却念世間人。"]', '["若論常快活，唯有隐居人。","林花长似錦，四季色常新。","或向巖间坐，旋瞻见桂輪。","雖然身暢逸，却念世间人。"]', '诗', 'shi', '', NULL, '詩 三十九 拾得 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('68dd6a7e-cab2-4a46-b198-273d5f443603', '詩 四十', '诗 四十', '869aadce-f094-4a70-aa24-0ff143c2877b', '唐', '["我見出家人，總愛喫酒肉。","此合上天堂，却沈歸地獄。","念得兩卷經，欺他道鄽俗。","豈知鄽俗士，大有根性熟。"]', '["我见出家人，總愛喫酒肉。","此合上天堂，却沈归地獄。","念得兩卷經，欺他道鄽俗。","豈知鄽俗士，大有根性熟。"]', '诗', 'shi', '', NULL, '詩 四十 拾得 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('19d4d542-43b7-40b5-a5d4-40326cb6643e', '詩 四十一', '诗 四十一', '869aadce-f094-4a70-aa24-0ff143c2877b', '唐', '["我見頑鈍人，燈心柱須彌。","蟻子齧大樹，焉知氣力微。","學咬兩莖菜，言與祖師齊。","火急求懺悔，從今輒莫迷。"]', '["我见頑鈍人，灯心柱須彌。","蟻子齧大樹，焉知氣力微。","学咬兩莖菜，言與祖師齊。","火急求懺悔，從今輒莫迷。"]', '诗', 'shi', '', NULL, '詩 四十一 拾得 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d3534362-2ba7-44a5-99a2-2fa00d15abcd', '詩 四十二', '诗 四十二', '869aadce-f094-4a70-aa24-0ff143c2877b', '唐', '["若見月光明，照燭四天下。","圓暉掛太虛，瑩淨能蕭灑。","人道有虧盈，我見無衰謝。","狀似摩尼珠，光明無晝夜。"]', '["若见月光明，照燭四天下。","圓暉掛太虛，瑩淨能蕭灑。","人道有虧盈，我见無衰謝。","狀似摩尼珠，光明無晝夜。"]', '诗', 'shi', '', NULL, '詩 四十二 拾得 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('be5875f5-41bc-4a80-8f59-5d1dc64e0f54', '詩 四十三', '诗 四十三', '869aadce-f094-4a70-aa24-0ff143c2877b', '唐', '["余住無方所，盤泊無爲理。","時陟湼盤山，或翫香林寺。","尋常只是閑，言不干名利。","東海變桑田，我心誰管你。"]', '["余住無方所，盤泊無爲理。","时陟湼盤山，或翫香林寺。","尋常只是闲，言不干名利。","东海变桑田，我心誰管你。"]', '诗', 'shi', '', NULL, '詩 四十三 拾得 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('57dff727-acb6-4cef-9d36-2ac3c6f0a8c5', '詩 四十四', '诗 四十四', '869aadce-f094-4a70-aa24-0ff143c2877b', '唐', '["左手握驪珠，右手執慧劒。","先破無明賊，神珠自吐燄。","傷嗟愚癡人，貪愛那生厭。","一墮三途間，始覺前程險。"]', '["左手握驪珠，右手執慧劒。","先破無明賊，神珠自吐燄。","傷嗟愚癡人，貪愛那生厭。","一墮三途间，始覺前程險。"]', '诗', 'shi', '', NULL, '詩 四十四 拾得 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5bfab23f-e3d7-4fa6-86ed-637bf86009c0', '詩 四十五', '诗 四十五', '869aadce-f094-4a70-aa24-0ff143c2877b', '唐', '["般若酒泠泠，飲多人易醒。","余住天台山，凡愚那見形。","常遊深谷洞，終不逐時情。","無思亦無慮，無辱也無榮。"]', '["般若酒泠泠，饮多人易醒。","余住天台山，凡愚那见形。","常游深谷洞，終不逐时情。","無思亦無慮，無辱也無榮。"]', '诗', 'shi', '', NULL, '詩 四十五 拾得 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f95d04b0-ca1f-4629-b14a-89c9bd872af3', '詩 四十六', '诗 四十六', '869aadce-f094-4a70-aa24-0ff143c2877b', '唐', '["平生何所憂，此世隨緣過。","日月如逝波，光陰石中火。","任他天地移，我暢巖中坐。"]', '["平生何所憂，此世隨緣過。","日月如逝波，光陰石中火。","任他天地移，我暢巖中坐。"]', '诗', 'shi', '', NULL, '詩 四十六 拾得 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dc0be9dd-32f7-4f59-9abb-16a991a7f781', '詩 四十七', '诗 四十七', '869aadce-f094-4a70-aa24-0ff143c2877b', '唐', '["嗟見多知漢，終日枉用心。","岐路逞嘍囉，欺謾一切人。","唯作地獄滓，不修來世因。","忽爾無常到，定知亂紛紛。"]', '["嗟见多知漢，終日枉用心。","岐路逞嘍囉，欺謾一切人。","唯作地獄滓，不修来世因。","忽爾無常到，定知亂紛紛。"]', '诗', 'shi', '', NULL, '詩 四十七 拾得 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('56b3fd0c-6363-40e7-8924-6c6278df7e1d', '詩 四十八', '诗 四十八', '869aadce-f094-4a70-aa24-0ff143c2877b', '唐', '["迢迢山徑峻，萬仞險隘危。","石橋莓苔綠，時見白雲飛。","瀑布懸如練，月影落潭暉。","更登華頂上，猶待孤鶴期。"]', '["迢迢山徑峻，万仞險隘危。","石橋莓苔綠，时见白云飞。","瀑布懸如練，月影落潭暉。","更登华頂上，猶待孤鹤期。"]', '诗', 'shi', '', NULL, '詩 四十八 拾得 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4d1b9841-e1cd-43cf-8609-bd88633c6b5d', '詩 四十九', '诗 四十九', '869aadce-f094-4a70-aa24-0ff143c2877b', '唐', '["松月冷颼颼，片片雲霞起。","匼匝幾重山，縱目千萬里。","谿潭水澄澄，徹底鏡相似。","可貴靈臺物，七寶莫能比。"]', '["松月冷颼颼，片片云霞起。","匼匝幾重山，縱目千万里。","谿潭水澄澄，徹底镜相似。","可貴靈台物，七寶莫能比。"]', '诗', 'shi', '', NULL, '詩 四十九 拾得 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('059da24b-a5f3-40ec-ba62-97fd741f4b42', '詩 五十', '诗 五十', '869aadce-f094-4a70-aa24-0ff143c2877b', '唐', '["世有多解人，愚癡學閑文。","不憂當來果，唯知造惡因。","見佛不解禮，覩僧倍生瞋。","五逆十惡輩，三毒以爲鄰。","死去入地獄，未有出頭辰。"]', '["世有多解人，愚癡学闲文。","不憂當来果，唯知造惡因。","见佛不解禮，覩僧倍生瞋。","五逆十惡輩，三毒以爲鄰。","死去入地獄，未有出头辰。"]', '诗', 'shi', '', NULL, '詩 五十 拾得 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6d7bc69f-dbfb-4b1c-baef-4b22d024942d', '詩 五十一', '诗 五十一', '869aadce-f094-4a70-aa24-0ff143c2877b', '唐', '["人生浮世中，箇箇願富貴。","高堂車馬多，一呼百諾至。","吞併田地宅，準擬承後嗣。","未逾七十秋，冰消瓦解去。"]', '["人生浮世中，箇箇願富貴。","高堂车马多，一呼百諾至。","吞併田地宅，準擬承後嗣。","未逾七十秋，冰消瓦解去。"]', '诗', 'shi', '', NULL, '詩 五十一 拾得 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('88316a3c-a123-47ae-9c7d-444057f9626d', '詩 五十二', '诗 五十二', '869aadce-f094-4a70-aa24-0ff143c2877b', '唐', '["水浸泥彈丸，思量無道理。","浮漚夢幻身，百年能幾幾。","不解細思惟，將言長不死。","誅剝壘千金，留將與妻子。"]', '["水浸泥彈丸，思量無道理。","浮漚梦幻身，百年能幾幾。","不解細思惟，將言长不死。","誅剝壘千金，留將與妻子。"]', '诗', 'shi', '', NULL, '詩 五十二 拾得 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b2f2c688-0945-45f8-a110-5ba34a93a30d', '詩 五十三', '诗 五十三', '869aadce-f094-4a70-aa24-0ff143c2877b', '唐', '["雲林最幽棲，傍澗枕月谿。","松拂盤陀石，甘泉涌淒淒。","靜坐偏佳麗，虛巖曚霧迷。","怡然居憩地，日。"]', '["云林最幽棲，傍澗枕月谿。","松拂盤陀石，甘泉涌淒淒。","静坐偏佳丽，虛巖曚霧迷。","怡然居憩地，日。"]', '诗', 'shi', '', NULL, '詩 五十三 拾得 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('064bae26-29b2-4b4b-b48f-93ad4e9d16e0', '詩 五十四', '诗 五十四', '869aadce-f094-4a70-aa24-0ff143c2877b', '唐', '["可笑是林泉，數里少人煙。","雲從巖嶂起，瀑布水潺潺。","猨啼唱道曲，虎嘯出人間。","松風清颯颯，鳥語聲關關。","獨步繞石澗，孤陟上峰巒。","時坐盤陀石，偃仰攀蘿沿。","遙望城隍處，惟聞鬧喧喧。"]', '["可笑是林泉，數里少人煙。","云從巖嶂起，瀑布水潺潺。","猨啼唱道曲，虎嘯出人间。","松风清颯颯，鸟語声关关。","独步繞石澗，孤陟上峰巒。","时坐盤陀石，偃仰攀蘿沿。","遙望城隍处，惟闻鬧喧喧。"]', '诗', 'shi', '', NULL, '詩 五十四 拾得 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ff51f414-8c2e-4658-ba6a-7ffb65d37790', '壁上詩二首 一', '壁上诗二首 一', 'a0a8bc12-abf4-4ce9-aae2-acaadc58a624', '唐', '["余自來天台，凡經幾萬迴。","一身如雲水，悠悠任去來。","逍遙絕無鬧，忘機隆佛道。","世途岐路心，衆生多煩惱。","兀兀沈浪海，漂漂輪三界。","可惜一靈物，無始被境埋。","電光瞥然起，生死紛塵埃。","寒山特相訪，拾得常往來。","論心話明月，太虛廓無礙。","法界即無邊，一法普徧該。"]', '["余自来天台，凡經幾万迴。","一身如云水，悠悠任去来。","逍遙絕無鬧，忘機隆佛道。","世途岐路心，衆生多煩惱。","兀兀沈浪海，漂漂輪三界。","可惜一靈物，無始被境埋。","電光瞥然起，生死紛塵埃。","寒山特相訪，拾得常往来。","論心話明月，太虛廓無礙。","法界即無邊，一法普徧該。"]', '诗', 'shi', '', NULL, '壁上詩二首 一 豐干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('24f48460-fe3a-417b-98ab-5ac1c2bbb611', '壁上詩二首 二', '壁上诗二首 二', 'a0a8bc12-abf4-4ce9-aae2-acaadc58a624', '唐', '["本來無一物，亦無塵可拂。","若能了達此，不用坐兀兀。"]', '["本来無一物，亦無塵可拂。","若能了達此，不用坐兀兀。"]', '诗', 'shi', '', NULL, '壁上詩二首 二 豐干 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('399ca2c4-7687-4fc5-ae6a-567a0d23c58b', '奉和竇使君同恭法師詠高僧二首 竺佛圖澄', '奉和竇使君同恭法師詠高僧二首 竺佛圖澄', 'eab9c782-b27b-4021-a449-80a4be8d5523', '唐', '["大誓憫塗炭，乘機入生死。","中州法既弘，葛陂暴亦止。","乳孔光一室，掌鏡徹千里。","道盛咒蓮華，災生吟棘子。","埋石緣雖謝，流沙化方始。"]', '["大誓憫塗炭，乘機入生死。","中州法既弘，葛陂暴亦止。","乳孔光一室，掌镜徹千里。","道盛咒蓮华，災生吟棘子。","埋石緣雖謝，流沙化方始。"]', '诗', 'shi', '', NULL, '奉和竇使君同恭法師詠高僧二首 竺佛圖澄 慧宣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7a0db264-19d2-48c6-8b61-ddc5523b82c2', '奉和竇使君同恭法師詠高僧二首 釋僧肇', '奉和竇使君同恭法師詠高僧二首 釋僧肇', 'eab9c782-b27b-4021-a449-80a4be8d5523', '唐', '["般若唯絕鑿，湼槃固無名。","先賢未始覺，之子唱希聲。","秦王嗟理詣，童壽揖詞清。","徽音聞廬岳，精難動中京。","適驗方袍裏，奇才復挺生。"]', '["般若唯絕鑿，湼槃固無名。","先賢未始覺，之子唱希声。","秦王嗟理詣，童壽揖词清。","徽音闻廬岳，精难动中京。","適驗方袍裏，奇才复挺生。"]', '诗', 'shi', '', NULL, '奉和竇使君同恭法師詠高僧二首 釋僧肇 慧宣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1d5ab856-44a2-431a-9aed-7ab42730d3c2', '秋日遊東山寺尋殊曇二法師', '秋日游东山寺尋殊曇二法師', 'eab9c782-b27b-4021-a449-80a4be8d5523', '唐', '["木落樹蕭槮，水清流㵳寂。","屬此悲哉氣，復茲羈旅慼。","奚用寫煩憂，山泉恣遊歷。","萬丈窺深澗，千尋仰絕壁。","傍嶺竹參差，緣崖藤冪{罓/歷}。","行行極幽邃，去去逾空寂。","果值息心侶，喬枝方挂錫。","圍遶悉栴檀，純良豈沙礫。","妙法誠無比，深經解怨敵。","心歡即頂禮，道存仍目擊。","慧刀幸已逢，疑網於焉析。","豈直却煩惱，方期拯沈溺。"]', '["木落樹蕭槮，水清流㵳寂。","屬此悲哉氣，复茲羈旅慼。","奚用寫煩憂，山泉恣游歷。","万丈窺深澗，千尋仰絕壁。","傍嶺竹參差，緣崖藤冪{罓/歷}。","行行極幽邃，去去逾空寂。","果值息心侶，喬枝方挂錫。","圍遶悉栴檀，純良豈沙礫。","妙法誠無比，深經解怨敵。","心歡即頂禮，道存仍目擊。","慧刀幸已逢，疑網於焉析。","豈直却煩惱，方期拯沈溺。"]', '诗', 'shi', '', NULL, '秋日遊東山寺尋殊曇二法師 慧宣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a8c45d99-98d7-4b49-b296-5eb2f7d642eb', '句', '句', 'eab9c782-b27b-4021-a449-80a4be8d5523', '唐', '["如蒙一被服，方堪稱福田。"]', '["如蒙一被服，方堪稱福田。"]', '诗', 'shi', '', NULL, '句 慧宣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('85441a30-562e-440f-8220-2ba2cf8e545c', '愛妾換馬', '愛妾換马', 'a845b4de-98db-4a33-9710-e02d51d75a41', '唐', '["朱鬣飾金鑣，紅妝束素腰。","似雲來躞蹀，如雪去飄颻。","桃花含淺汗，柳葉帶餘嬌。","騁光將獨立，雙絕不俱標。"]', '["朱鬣飾金鑣，紅妝束素腰。","似云来躞蹀，如雪去飄颻。","桃花含淺汗，柳葉带餘嬌。","騁光將独立，雙絕不俱標。"]', '诗', 'shi', '', NULL, '愛妾換馬 法宣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('87721262-872d-4e31-9e9e-f778b6066857', '和趙王觀妓', '和趙王观妓', 'a845b4de-98db-4a33-9710-e02d51d75a41', '唐', '["桂山留上客，蘭室命妖饒。","城中畫廣黛，宮裏束纖腰。","舞袖風前舉，歌聲扇後嬌。","周郎不須顧，今日管弦調。"]', '["桂山留上客，蘭室命妖饒。","城中畫廣黛，宮裏束纖腰。","舞袖风前舉，歌声扇後嬌。","周郎不須顧，今日管弦調。"]', '诗', 'shi', '', NULL, '和趙王觀妓 法宣 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('815938ea-8ede-48c7-b9de-0e72a80335b9', '聽獨杵搗衣', '听独杵捣衣', 'd01c4756-79c0-459a-bdb5-87cf6e446837', '唐', '["非是無人助，意欲自鳴砧。","向月憐孤影，承風送迥音。","疑擣雙絲練，似奏一弦琴。","令君聞獨杵，知妾有專心。"]', '["非是無人助，意欲自鳴砧。","向月怜孤影，承风送迥音。","疑擣雙絲練，似奏一弦琴。","令君闻独杵，知妾有專心。"]', '诗', 'shi', '', NULL, '聽獨杵搗衣 慧偘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d3f3de62-f789-4e6f-bac3-36b4534739ef', '聞侯方兒來寇', '闻侯方兒来寇', 'd01c4756-79c0-459a-bdb5-87cf6e446837', '唐', '["羊皮贖去士，馬革歛還尸。","天下方無事，孝廉非哭時。"]', '["羊皮贖去士，马革歛還尸。","天下方無事，孝廉非哭时。"]', '诗', 'shi', '', NULL, '聞侯方兒來寇 慧偘 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e8f9421-bd0c-481d-953d-991eb81af2ec', '和琳法師初春法集之作', '和琳法師初春法集之作', '20fcd008-fe45-47fa-8b42-1acd6122e6c1', '唐', '["鷲嶺光前選，祇園表昔恭。","哲人崇踵武，弘道會羣龍。","高座登蓮葉，麈尾振霜松。","塵飛揚雅梵，風度引疎鐘。","靜言澄義海，發論上詞鋒。","心虛道易合，跡廣席難重。","和風動淑氣，麗日啓時雍。","高才掞雅什，顧己濫朋從。","因茲仰積善，靈華庶可逢。"]', '["鷲嶺光前選，祇园表昔恭。","哲人崇踵武，弘道會羣龙。","高座登蓮葉，麈尾振霜松。","塵飞揚雅梵，风度引疎鐘。","静言澄義海，發論上词鋒。","心虛道易合，跡廣席难重。","和风动淑氣，丽日啓时雍。","高才掞雅什，顧己濫朋從。","因茲仰積善，靈华庶可逢。"]', '诗', 'shi', '', NULL, '和琳法師初春法集之作 慧淨 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('62955f72-a945-4ff8-84df-c93c73b4c803', '與英才言聚賦得昇天行', '與英才言聚賦得昇天行', '20fcd008-fe45-47fa-8b42-1acd6122e6c1', '唐', '["馭風過閬苑，控鶴下瀛洲。","欲採三芝秀，先從千仞遊。","駕鳳吟虛管，乘槎泛淺流。","頹齡一已駐，方驗大椿秋。"]', '["馭风過閬苑，控鹤下瀛洲。","欲採三芝秀，先從千仞游。","駕鳳吟虛管，乘槎泛淺流。","頹齡一已駐，方驗大椿秋。"]', '诗', 'shi', '', NULL, '與英才言聚賦得昇天行 慧淨 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3205a2f2-b86f-4f86-9003-dc338f8f839d', '和盧贊府遊紀國道場', '和盧贊府游紀国道場', '20fcd008-fe45-47fa-8b42-1acd6122e6c1', '唐', '["日光通漢室，星彩晦周朝。","法城從此構，香閣本岧嶢。","株盤仰承露，剎鳳俯摩霄。","落照侵虛牖，長虹拖跨橋。","高才暫騁目，雲藻隨飄颻。","欲追千里驥，終是謝連鑣。"]', '["日光通漢室，星彩晦周朝。","法城從此構，香閣本岧嶢。","株盤仰承露，剎鳳俯摩霄。","落照侵虛牖，长虹拖跨橋。","高才暫騁目，云藻隨飄颻。","欲追千里驥，終是謝連鑣。"]', '诗', 'shi', '', NULL, '和盧贊府遊紀國道場 慧淨 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b0b15cef-b06c-47a2-bf3a-99575ce1310c', '冬日普光寺臥疾值雪簡諸舊遊', '冬日普光寺臥疾值雪簡諸旧游', '20fcd008-fe45-47fa-8b42-1acd6122e6c1', '唐', '["臥疴苦留滯，闢戶望遙天。","寒雲舒復卷，落雪斷還連。","凝華照書閣，飛素涴琴弦。","迴飄洛神賦，皎映齊紈篇。","縈階如鶴舞，拂樹似花鮮。","徒賞豐年瑞，沈憂終自憐。"]', '["臥疴苦留滯，闢戶望遙天。","寒云舒复卷，落雪斷還連。","凝华照书閣，飞素涴琴弦。","迴飄洛神賦，皎映齊紈篇。","縈階如鹤舞，拂樹似花鲜。","徒賞豐年瑞，沈憂終自怜。"]', '诗', 'shi', '', NULL, '冬日普光寺臥疾值雪簡諸舊遊 慧淨 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6ac5494d-4d47-47e0-bd5d-7ee0073040a3', '雜言', '杂言', '20fcd008-fe45-47fa-8b42-1acd6122e6c1', '唐', '["觀化祇山頂，流睇古王城。","萬載池猶潔，千年苑尚清。","髣髴影堅路，摧殘廣脇楹。","七寶仙臺亡舊迹，四彩天花絕雨聲。","聲華日以遠，自恨生何晚。","既傷火宅眩中門，還嗟寶渚迷長坂。","步陟平郊望，心遊七海上。","擾擾三界溺邪津，渾渾萬品忘真匠。","唯有能仁獨圓悟，廓塵靜浪開玄路。","創逢肌命棄身城，更爲求人崩意樹。","持囊畢契戒珠淨，被甲要心忍衣固。","三祇不倦陵二車，一足忘勞超九數。","定瀲江清沐久結，智劍霜凝斬新霧。","無邊大劫無不修，六時愍生遵六度。","度有流光功德收，金河示滅歸常住。","鶴林權唱演功周，聖德佳音傳餘響。","龍宮秘典海中探，石室真言山處仰。","流教在茲辰，傳芳代有人。","沙河雪嶺迷朝徑，巨海鴻崖亂夜津。","入萬死，求一生。","投針偶穴非同喻，束馬懸車豈等程。","不徇今身樂，無祈後代榮。","誓舍危軀追勝義，咸希畢契傳燈情。","勞歌勿復陳，延眺且周巡。","東睇女巒留二迹，西施鹿苑去三輪。","北睨舍城池尚在，南睎尊嶺穴猶存。","五峰秀，百池分。","粲粲鮮花明四曜，輝輝道樹鏡三春。","揚錫指山阿，攜步上祇陀。","既覩如來疊衣石，復觀天授迸餘峨。","佇靈鎮梵嶽，凝思遍生河。","金花逸掌儀前奉，芳蓋陵虛殿後過。","旋遶經行砌，目想如神契。","迴斯少福澗生津，共會龍華捨塵翳。"]', '["观化祇山頂，流睇古王城。","万載池猶潔，千年苑尚清。","髣髴影堅路，摧殘廣脇楹。","七寶仙台亡旧迹，四彩天花絕雨声。","声华日以远，自恨生何晚。","既傷火宅眩中门，還嗟寶渚迷长坂。","步陟平郊望，心游七海上。","擾擾三界溺邪津，渾渾万品忘真匠。","唯有能仁独圓悟，廓塵静浪开玄路。","創逢肌命棄身城，更爲求人崩意樹。","持囊畢契戒珠淨，被甲要心忍衣固。","三祇不倦陵二车，一足忘勞超九數。","定瀲江清沐久結，智劍霜凝斬新霧。","無邊大劫無不修，六时愍生遵六度。","度有流光功德收，金河示滅归常住。","鹤林權唱演功周，聖德佳音傳餘响。","龙宮秘典海中探，石室真言山处仰。","流教在茲辰，傳芳代有人。","沙河雪嶺迷朝徑，巨海鴻崖亂夜津。","入万死，求一生。","投針偶穴非同喻，束马懸车豈等程。","不徇今身乐，無祈後代榮。","誓舍危軀追勝義，咸希畢契傳灯情。","勞歌勿复陳，延眺且周巡。","东睇女巒留二迹，西施鹿苑去三輪。","北睨舍城池尚在，南睎尊嶺穴猶存。","五峰秀，百池分。","粲粲鲜花明四曜，輝輝道樹镜三春。","揚錫指山阿，携步上祇陀。","既覩如来叠衣石，复观天授迸餘峨。","佇靈鎮梵嶽，凝思遍生河。","金花逸掌儀前奉，芳蓋陵虛殿後過。","旋遶經行砌，目想如神契。","迴斯少福澗生津，共會龙华捨塵翳。"]', '诗', 'shi', '', NULL, '雜言 慧淨 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4ccdc8ef-6a4c-4198-b119-8a1359612bfb', '三不爲篇 一', '三不爲篇 一', '4c741b20-096b-45e7-b793-b65ed12f45c3', '唐', '["我欲偃文修武，身死名存。","斫石通道，祈井流泉。","君肝在內，我身處邊。","荆軻拔劍，毛遂捧盤。","不爲則已，爲則不然。","將恐兩虎共鬬，勢不俱全。","永□今好，長絕來怨。","是以返跡荒徑，息影柴門。"]', '["我欲偃文修武，身死名存。","斫石通道，祈井流泉。","君肝在內，我身处邊。","荆軻拔劍，毛遂捧盤。","不爲則已，爲則不然。","將恐兩虎共鬬，勢不俱全。","永□今好，长絕来怨。","是以返跡荒徑，息影柴门。"]', '诗', 'shi', '', NULL, '三不爲篇 一 海順 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cb6bdf47-c48d-46d1-aa15-c571908207eb', '三不爲篇 二', '三不爲篇 二', '4c741b20-096b-45e7-b793-b65ed12f45c3', '唐', '["我欲刺股錐刃，懸頭屋梁。","書臨雪彩，牒映螢光。","一朝鵬舉，萬里鸞翔。","縱任才辯，遊說君王。","高車反邑，衣錦還鄉。","將恐鳥殘以羽，蘭折由芳。","籠餐詎貴，鉤餌難嘗。","是以高巢林藪，深穴池塘。"]', '["我欲刺股錐刃，懸头屋梁。","书臨雪彩，牒映螢光。","一朝鵬舉，万里鸾翔。","縱任才辯，游说君王。","高车反邑，衣錦還乡。","將恐鸟殘以羽，蘭折由芳。","籠餐詎貴，鉤餌难嘗。","是以高巢林藪，深穴池塘。"]', '诗', 'shi', '', NULL, '三不爲篇 二 海順 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('43a5f281-b2df-4c0c-a889-1eea06884407', '三不爲篇 三', '三不爲篇 三', '4c741b20-096b-45e7-b793-b65ed12f45c3', '唐', '["我欲衒才鬻德，入市趨朝。","四衆瞻仰，三槐附交。","標形引勢，身達名超。","箱盈綺服，廚富甘肴。","諷揚弦管，詠美歌謠。","將恐塵栖弱草，露宿危條。","無過日旦，靡越風朝。","是以還傷樂淺，非惟苦遙。"]', '["我欲衒才鬻德，入市趨朝。","四衆瞻仰，三槐附交。","標形引勢，身達名超。","箱盈綺服，廚富甘肴。","諷揚弦管，詠美歌謠。","將恐塵栖弱草，露宿危條。","無過日旦，靡越风朝。","是以還傷乐淺，非惟苦遙。"]', '诗', 'shi', '', NULL, '三不爲篇 三 海順 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd712ed8-c1c9-4b03-96f5-15a8240ec9a0', '出賜玄奘衲袈裟衣應制', '出賜玄奘衲袈裟衣應制', '94383d02-86c7-48c0-917f-006de78f71f4', '唐', '["福田資象德，聖種理幽薰。","不持金作縷，還用綵成文。","朱青自掩映，翠綺相氤氳。","獨有離離葉，恒向稻畦分。"]', '["福田資象德，聖種理幽薰。","不持金作縷，還用綵成文。","朱青自掩映，翠綺相氤氳。","独有離離葉，恒向稻畦分。"]', '诗', 'shi', '', NULL, '出賜玄奘衲袈裟衣應制 道恭 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab142b51-8147-42f3-bb61-382dd0e765b4', '設缸面酒欵蕭翼探得來字', '設缸面酒欵蕭翼探得来字', 'c712938f-f2b8-4907-b041-1f2c85c2f1ac', '唐', '["初醞一缸開，新知萬里來。","披雲同落寞，步月共裴回。","夜久孤琴思，風長旅鴈哀。","非君有秘術，誰照不然灰。"]', '["初醞一缸开，新知万里来。","披云同落寞，步月共裴回。","夜久孤琴思，风长旅鴈哀。","非君有秘術，誰照不然灰。"]', '诗', 'shi', '', NULL, '設缸面酒欵蕭翼探得來字 辨才 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('88188de0-57ed-4879-aef1-08a6066d7a5f', '書遺文後', '书遺文後', '13c1664d-a737-4b31-8e8a-94799b051d47', '唐', '["苦哉黑闇女，樂矣功德天。","智者俱不受，愚夫納二邊。","我奉能仁教，歸依彌勒前。","願闡摩訶衍，成就那羅延。"]', '["苦哉黑闇女，乐矣功德天。","智者俱不受，愚夫納二邊。","我奉能仁教，归依彌勒前。","願闡摩訶衍，成就那羅延。"]', '诗', 'shi', '', NULL, '書遺文後 僧鳳 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('668f092a-f60d-429c-8f46-688c310869c5', '譏韋玎吟以韋字爲韻', '譏韋玎吟以韋字爲韻', '59c6d3ea-2359-4288-ba54-307406d3fca8', '唐', '["我之佛法是無爲，何故今朝得有爲。","無韋始得三數載，不知此復是何韋。"]', '["我之佛法是無爲，何故今朝得有爲。","無韋始得三數載，不知此复是何韋。"]', '诗', 'shi', '', NULL, '譏韋玎吟以韋字爲韻 利涉 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('859cf103-303f-4452-94d8-178d22c6fa44', '別三輔諸僧', '別三輔諸僧', '7745006b-4cdb-4e25-b135-617e5f4cd267', '唐', '["去住俱爲客，分悲損性情。","共作無期別，誰能訪死生。"]', '["去住俱爲客，分悲損性情。","共作無期別，誰能訪死生。"]', '诗', 'shi', '', NULL, '別三輔諸僧 道會 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('066d1bb6-9b8c-4a8b-9443-fcaab86af01b', '贈王仙柯', '贈王仙柯', '5ca1dda3-864d-4fca-8088-314bd76aeff9', '唐', '["瞻思不及望仙兄，早晚昇霞入太清。","手種一株松未老，爐燒九轉藥新成。","心中已得黃庭術，頭上應無白髮生。","異日却歸華表語，待教凡俗普聞名。"]', '["瞻思不及望仙兄，早晚昇霞入太清。","手種一株松未老，爐燒九轉藥新成。","心中已得黄庭術，头上應無白髮生。","異日却归华表語，待教凡俗普闻名。"]', '诗', 'shi', '', NULL, '贈王仙柯 中寤 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b2ccc56c-ce16-4308-8bc7-25f602fc4ea0', '在西國懷王舍城', '在西国懷王舍城', '2cbb7577-d83b-44ee-ba3e-54a1a0b52cec', '唐', '["遊，愁。","赤縣遠，丹思抽。","鷲嶺寒風駛，龍河激水流。","既喜朝聞日復日，不覺頹年秋更秋。","已畢耆山本願城難遇，終望持經振錫住神州。"]', '["游，愁。","赤縣远，丹思抽。","鷲嶺寒风駛，龙河激水流。","既喜朝闻日复日，不覺頹年秋更秋。","已畢耆山本願城难遇，終望持經振錫住神州。"]', '诗', 'shi', '', NULL, '在西國懷王舍城 義淨 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2acb6abe-c974-4d64-9742-b54d7fa2b25a', '與無行禪師同遊鷲嶺瞻奉既訖遐眺鄉關無任殷憂聊述所懷爲雜言詩', '與無行禪師同游鷲嶺瞻奉既訖遐眺乡关無任殷憂聊述所懷爲杂言诗', '2cbb7577-d83b-44ee-ba3e-54a1a0b52cec', '唐', '["觀化祇山頂，流睇古王城。","萬載池猶潔，千年苑尚清。","髣髴影堅路，摧殘廣脇𡺡。","七寶仙臺亡舊跡，四彩天花絕雨聲。","聲華日以遠，自恨生何晚。","既傷火宅眩中門，還嗟寶渚迷長坂。","步陟平郊望，心遊七海上。","擾擾三界溺邪津，渾渾萬品亡真匠。","唯有能仁獨圓悟，廓塵靜浪開玄路。","創逢肌命棄身城，更爲求人崩意樹。","持囊畢契戒珠淨，被甲要心忍衣固。","三祇不倦陵二車，一足忘勞超九數。","定瀲江清沐久結，智劍霜凝斬新霧。","無邊大劫無不脩，六時愍生遵六度。","度有流光功德收，金河示滅歸常住。","鶴林權唱演功周，聖徒往昔傳餘響。","龍宮秘典海中探，石室真言山處仰。","流教在茲辰，傳芳代有人。","沙河雪嶺迷朝徑，巨海鴻崖亂夜津。","入萬死，求一生。","投針偶穴非同喻，束馬懸車豈等程。","不徇今身樂，無祈後代榮。","誓捨危軀追勝義，咸希畢契傳燈情。","勞歌勿復陳，延眺且周巡。","東睇女巒留二迹，西馳鹿苑去三輪。","北睨舍城池尚在，南睎尊嶺穴猶存。","五峰秀，百池分。","粲粲鮮花明四曜，輝輝道樹鏡三春。","揚錫指山阿，攜步上祇陀。","既覩如來疊衣石，復觀天授迸餘峨。","佇靈鎮梵嶽，凝思遍生河。","金花逸掌儀前奉，芳蓋陵虛殿後過。","旋遶經行砌，目想如神契。","迴斯少福澗生津，共會龍華捨塵翳。"]', '["观化祇山頂，流睇古王城。","万載池猶潔，千年苑尚清。","髣髴影堅路，摧殘廣脇𡺡。","七寶仙台亡旧跡，四彩天花絕雨声。","声华日以远，自恨生何晚。","既傷火宅眩中门，還嗟寶渚迷长坂。","步陟平郊望，心游七海上。","擾擾三界溺邪津，渾渾万品亡真匠。","唯有能仁独圓悟，廓塵静浪开玄路。","創逢肌命棄身城，更爲求人崩意樹。","持囊畢契戒珠淨，被甲要心忍衣固。","三祇不倦陵二车，一足忘勞超九數。","定瀲江清沐久結，智劍霜凝斬新霧。","無邊大劫無不脩，六时愍生遵六度。","度有流光功德收，金河示滅归常住。","鹤林權唱演功周，聖徒往昔傳餘响。","龙宮秘典海中探，石室真言山处仰。","流教在茲辰，傳芳代有人。","沙河雪嶺迷朝徑，巨海鴻崖亂夜津。","入万死，求一生。","投針偶穴非同喻，束马懸车豈等程。","不徇今身乐，無祈後代榮。","誓捨危軀追勝義，咸希畢契傳灯情。","勞歌勿复陳，延眺且周巡。","东睇女巒留二迹，西驰鹿苑去三輪。","北睨舍城池尚在，南睎尊嶺穴猶存。","五峰秀，百池分。","粲粲鲜花明四曜，輝輝道樹镜三春。","揚錫指山阿，携步上祇陀。","既覩如来叠衣石，复观天授迸餘峨。","佇靈鎮梵嶽，凝思遍生河。","金花逸掌儀前奉，芳蓋陵虛殿後過。","旋遶經行砌，目想如神契。","迴斯少福澗生津，共會龙华捨塵翳。"]', '诗', 'shi', '', NULL, '與無行禪師同遊鷲嶺瞻奉既訖遐眺鄉關無任殷憂聊述所懷爲雜言詩 義淨 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c30ebf0-782f-4834-bae4-5d7ac875d3bf', '玄逵律師言離廣府還望桂林去留愴然自述贈懷', '玄逵律師言離廣府還望桂林去留愴然自述贈懷', '2cbb7577-d83b-44ee-ba3e-54a1a0b52cec', '唐', '["標心之梵宇，運想入仙洲。","嬰痼乖同好，沈情阻若抽。","葉落乍難聚，情離不可收。","何日乘杯至，詳觀演法流。"]', '["標心之梵宇，運想入仙洲。","嬰痼乖同好，沈情阻若抽。","葉落乍难聚，情離不可收。","何日乘杯至，詳观演法流。"]', '诗', 'shi', '', NULL, '玄逵律師言離廣府還望桂林去留愴然自述贈懷 義淨 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2da439ef-f602-417e-ac12-2139edb7a6d0', '余以咸亨元年在西京尋聽于時與幷部處一法師萊州弘禕論師更有三二諸德同契鷲嶺標心覺樹然而一公屬母親之年老遂懷戀於幷州禕師遇玄瞻於江寧乃敘情於安養玄逵既到廣府復阻先期唯與晉州小僧善行同去神州故友索爾分飛印度新知冥焉未會此時躑躅難以爲懷戲擬四愁聊題兩絕 一', '余以咸亨元年在西京尋听于时與幷部处一法師萊州弘禕論師更有三二諸德同契鷲嶺標心覺樹然而一公屬母親之年老遂懷戀於幷州禕師遇玄瞻於江寧乃敘情於安養玄逵既到廣府复阻先期唯與晉州小僧善行同去神州故友索爾分飞印度新知冥焉未會此时躑躅难以爲懷戲擬四愁聊題兩絕 一', '2cbb7577-d83b-44ee-ba3e-54a1a0b52cec', '唐', '["我行之數萬，愁緒百重思。","那教六尺影，獨步五天陲。"]', '["我行之數万，愁緒百重思。","那教六尺影，独步五天陲。"]', '诗', 'shi', '', NULL, '余以咸亨元年在西京尋聽于時與幷部處一法師萊州弘禕論師更有三二諸德同契鷲嶺標心覺樹然而一公屬母親之年老遂懷戀於幷州禕師遇玄瞻於江寧乃敘情於安養玄逵既到廣府復阻先期唯與晉州小僧善行同去神州故友索爾分飛印度新知冥焉未會此時躑躅難以爲懷戲擬四愁聊題兩絕 一 義淨 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4278df7c-9e03-49ed-b222-ff79c952a6ec', '余以咸亨元年在西京尋聽于時與幷部處一法師萊州弘禕論師更有三二諸德同契鷲嶺標心覺樹然而一公屬母親之年老遂懷戀於幷州禕師遇玄瞻於江寧乃敘情於安養玄逵既到廣府復阻先期唯與晉州小僧善行同去神州故友索爾分飛印度新知冥焉未會此時躑躅難以爲懷戲擬四愁聊題兩絕 二', '余以咸亨元年在西京尋听于时與幷部处一法師萊州弘禕論師更有三二諸德同契鷲嶺標心覺樹然而一公屬母親之年老遂懷戀於幷州禕師遇玄瞻於江寧乃敘情於安養玄逵既到廣府复阻先期唯與晉州小僧善行同去神州故友索爾分飞印度新知冥焉未會此时躑躅难以爲懷戲擬四愁聊題兩絕 二', '2cbb7577-d83b-44ee-ba3e-54a1a0b52cec', '唐', '["上將可陵師，匹士志難移。","如論惜短命，何得滿長祇。"]', '["上將可陵師，匹士志难移。","如論惜短命，何得满长祇。"]', '诗', 'shi', '', NULL, '余以咸亨元年在西京尋聽于時與幷部處一法師萊州弘禕論師更有三二諸德同契鷲嶺標心覺樹然而一公屬母親之年老遂懷戀於幷州禕師遇玄瞻於江寧乃敘情於安養玄逵既到廣府復阻先期唯與晉州小僧善行同去神州故友索爾分飛印度新知冥焉未會此時躑躅難以爲懷戲擬四愁聊題兩絕 二 義淨 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f40ae313-b455-4baf-af9b-459dd7ebd019', '西域寺', '西域寺', '2cbb7577-d83b-44ee-ba3e-54a1a0b52cec', '唐', '["衆美仍羅列，羣英已古今。","也知生死分，那得不傷心。"]', '["衆美仍羅列，羣英已古今。","也知生死分，那得不傷心。"]', '诗', 'shi', '', NULL, '西域寺 義淨 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eaa8fe9b-4ec4-422d-ba0b-f6de9adbceb7', '道希法師求法西域終於菴摩羅跋國後因巡禮希公住房傷其不幸聊題一絕', '道希法師求法西域終於菴摩羅跋国後因巡禮希公住房傷其不幸聊題一絕', '2cbb7577-d83b-44ee-ba3e-54a1a0b52cec', '唐', '["百苦忘勞獨進影，四恩在念契流通。","如何未盡傳燈志，溘然于此遇途窮。"]', '["百苦忘勞独進影，四恩在念契流通。","如何未尽傳灯志，溘然于此遇途窮。"]', '诗', 'shi', '', NULL, '道希法師求法西域終於菴摩羅跋國後因巡禮希公住房傷其不幸聊題一絕 義淨 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('de94891c-6ce5-4e0e-87a1-9b5b6c6fd005', '行路難', '行路难', '12830470-7895-44ab-9956-1d7ea1518fae', '唐', '["君不見孤鴈關外發，酸嘶度楊越。","空城客子心腸斷，幽閨思婦氣欲絕。","凝霜夜下拂羅衣，浮雲中斷開明月。","夜夜遙遙徒相思，年年望望情不歇。","取我匣中青銅鏡，情人爲我除白髮。","行路難，行路難。","夜聞南城漢使度，使我流淚憶長安。"]', '["君不见孤鴈关外發，酸嘶度楊越。","空城客子心腸斷，幽閨思婦氣欲絕。","凝霜夜下拂羅衣，浮云中斷开明月。","夜夜遙遙徒相思，年年望望情不歇。","取我匣中青銅镜，情人爲我除白髮。","行路难，行路难。","夜闻南城漢使度，使我流泪憶长安。"]', '诗', 'shi', '', NULL, '行路難 寶月 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d2b70446-b236-4bf1-a586-7931f512f6cb', '老僧', '老僧', 'b5d2091f-dbf2-4e68-a332-cd826906d072', '唐', '["日照西山雪，老僧門始開。","凍瓶粘柱礎，宿火陷爐灰。","童子病歸去，鹿麑寒入來。","齋鐘知漸近，枝鳥下生臺。"]', '["日照西山雪，老僧门始开。","凍瓶粘柱礎，宿火陷爐灰。","童子病归去，鹿麑寒入来。","斋鐘知漸近，枝鸟下生台。"]', '诗', 'shi', '', NULL, '老僧 景雲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4b8f99cb-824b-491d-8720-ecf99d17879c', '谿叟', '谿叟', 'b5d2091f-dbf2-4e68-a332-cd826906d072', '唐', '["谿翁居處靜，谿鳥入門飛。","早起釣魚去，夜深乘月歸。","露香菰米熟，煙煖荇絲肥。","瀟灑塵埃外，扁舟一草衣。"]', '["谿翁居处静，谿鸟入门飞。","早起釣鱼去，夜深乘月归。","露香菰米熟，煙煖荇絲肥。","瀟灑塵埃外，扁舟一草衣。"]', '诗', 'shi', '', NULL, '谿叟 景雲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ae3c3c7-7e29-4302-9d84-b7039f73fc9c', '畫松', '畫松', 'b5d2091f-dbf2-4e68-a332-cd826906d072', '唐', '["畫松一似真松樹，且待尋思記得無。","曾在天台山上見，石橋南畔第三株。"]', '["畫松一似真松樹，且待尋思記得無。","曾在天台山上见，石橋南畔第三株。"]', '诗', 'shi', '', NULL, '畫松 景雲 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a254b5a9-0c34-42f8-99b0-92cf33bae131', '送戴三徵君還谷口舊居', '送戴三徵君還谷口旧居', 'a1957acb-effc-4132-8343-af99df7abc2b', '唐', '["巖穴多遺秀，弓車屢遠招。","周王尊渭叟，潁客傲唐堯。","出處天波洽，關河地勢遙。","瞻星吳郡夜，作霧華山朝。","清論虛重席，閑居挂一瓢。","漁歌思坐酌，宸渥寵行軺。","春爲荷裳煖，霜因葛履消。","層崖懸瀑溜，萬壑振清飆。","谷鳥猶遷木，場駒正食苗。","謝安何日起，台鼎佇君調。"]', '["巖穴多遺秀，弓车屢远招。","周王尊渭叟，潁客傲唐堯。","出处天波洽，关河地勢遙。","瞻星吳郡夜，作霧华山朝。","清論虛重席，闲居挂一瓢。","漁歌思坐酌，宸渥寵行軺。","春爲荷裳煖，霜因葛履消。","層崖懸瀑溜，万壑振清飆。","谷鸟猶遷木，場駒正食苗。","謝安何日起，台鼎佇君調。"]', '诗', 'shi', '', NULL, '送戴三徵君還谷口舊居 理瑩 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('07589265-3a3f-4820-9d77-ccbd10c013b4', '送童子下山', '送童子下山', '22eaa0bc-7fc6-46db-821c-a7d6ed987c79', '唐', '["空門寂寞汝思家，禮別雲房下九華。","愛向竹欄騎竹馬，懶於金地聚金沙。","添瓶澗底休招月，烹茗甌中罷弄花。","好去不須頻下淚，老僧相伴有煙霞。"]', '["空门寂寞汝思家，禮別云房下九华。","愛向竹欄騎竹马，懶於金地聚金沙。","添瓶澗底休招月，烹茗甌中罷弄花。","好去不須頻下泪，老僧相伴有煙霞。"]', '诗', 'shi', '', NULL, '送童子下山 金地藏 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('92079c52-ad70-4ab7-9ca9-bb921fd87199', '題張僧繇醉僧圖', '題張僧繇醉僧圖', '56dfa9ec-715c-4f18-bc5f-fa0f11c2dc13', '唐', '["人人送酒不曾沽，終日松間挂一壺。","草聖欲成狂便發，真堪畫入醉僧圖。"]', '["人人送酒不曾沽，終日松间挂一壺。","草聖欲成狂便發，真堪畫入醉僧圖。"]', '诗', 'shi', '', NULL, '題張僧繇醉僧圖 懷素 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('150641ec-fdac-4c4b-b45d-7c8ddadf5e98', '寄衡嶽僧', '寄衡嶽僧', '56dfa9ec-715c-4f18-bc5f-fa0f11c2dc13', '唐', '["祝融高座對寒峰，雲水昭丘幾萬重。","五月衲衣猶近火，起來白鶴冷青松。"]', '["祝融高座对寒峰，云水昭丘幾万重。","五月衲衣猶近火，起来白鹤冷青松。"]', '诗', 'shi', '', NULL, '寄衡嶽僧 懷素 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6cadba7f-f388-457c-b615-f7397796da0f', '酬皇甫冉西陵見寄', '酬皇甫冉西陵见寄', 'da4f5f43-774c-45b0-8e4f-10b11cfae4f7', '唐', '["西陵潮信滿，島嶼沒中流。","越客依風水，相思南渡頭。","寒光生極浦，落日映滄洲。","何事揚帆去，空驚海上鷗。"]', '["西陵潮信满，島嶼沒中流。","越客依风水，相思南渡头。","寒光生極浦，落日映滄洲。","何事揚帆去，空驚海上鷗。"]', '诗', 'shi', '', NULL, '酬皇甫冉西陵見寄 靈一 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad51183f-d0f6-4e7e-8aa2-cce71c4dfd70', '溪行即事', '溪行即事', 'da4f5f43-774c-45b0-8e4f-10b11cfae4f7', '唐', '["近夜山更碧，入林溪轉清。","不知伏牛事，潭洞何從橫。","野岸煙初合，平湖月未生。","孤舟屢失道，但聽秋泉聲。"]', '["近夜山更碧，入林溪轉清。","不知伏牛事，潭洞何從橫。","野岸煙初合，平湖月未生。","孤舟屢失道，但听秋泉声。"]', '诗', 'shi', '', NULL, '溪行即事 靈一 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2efc0d5b-e5cc-4a72-a6c8-edb76195778c', '棲霞山夜坐', '棲霞山夜坐', 'da4f5f43-774c-45b0-8e4f-10b11cfae4f7', '唐', '["山頭戒壇路，幽映雪岩側。","四面青石牀，一峰苔蘚色。","松風靜復起，月影開還黑。","何獨乘夜來，殊非晝所得。"]', '["山头戒壇路，幽映雪岩側。","四面青石牀，一峰苔蘚色。","松风静复起，月影开還黑。","何独乘夜来，殊非晝所得。"]', '诗', 'shi', '', NULL, '棲霞山夜坐 靈一 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cbbbc1cb-9e28-4758-a8d8-50d360249c3d', '宿天柱觀', '宿天柱观', 'da4f5f43-774c-45b0-8e4f-10b11cfae4f7', '唐', '["石室初投宿，仙翁喜暫容。","花源隔水見，洞府過山逢。","泉湧堦前地，雲生戶外峰。","中宵自入定，非是欲降龍。"]', '["石室初投宿，仙翁喜暫容。","花源隔水见，洞府過山逢。","泉湧堦前地，云生戶外峰。","中宵自入定，非是欲降龙。"]', '诗', 'shi', '', NULL, '宿天柱觀 靈一 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a37d754c-e93f-461c-9c91-c92308277ac1', '酬皇甫冉將赴無錫於雲門寺贈別', '酬皇甫冉將赴無錫於云门寺贈別', 'da4f5f43-774c-45b0-8e4f-10b11cfae4f7', '唐', '["湖南通古寺，來往意無涯。","欲識雲門路，千峰到若耶。","春山子敬宅，古木謝敷家。","自可長偕隱，那言相去賒。"]', '["湖南通古寺，来往意無涯。","欲識云门路，千峰到若耶。","春山子敬宅，古木謝敷家。","自可长偕隐，那言相去賒。"]', '诗', 'shi', '', NULL, '酬皇甫冉將赴無錫於雲門寺贈別 靈一 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5cba3f40-7528-4901-b67a-3069257b7b68', '宜豐新泉', '宜豐新泉', 'da4f5f43-774c-45b0-8e4f-10b11cfae4f7', '唐', '["泉源新湧出，洞澈映纖雲。","稍落芙蓉沼，初淹苔蘚文。","素將空意合，淨與衆流分。","每到清宵月，泠泠夢裏聞。"]', '["泉源新湧出，洞澈映纖云。","稍落芙蓉沼，初淹苔蘚文。","素將空意合，淨與衆流分。","每到清宵月，泠泠梦裏闻。"]', '诗', 'shi', '', NULL, '宜豐新泉 靈一 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bfa5282c-bdac-4770-9660-3212c5ed1d88', '靜林精舍', '静林精舍', 'da4f5f43-774c-45b0-8e4f-10b11cfae4f7', '唐', '["靜林溪路遠，蕭帝有遺蹤。","水擊羅浮磬，山鳴于闐鐘。","燈傳三世火，樹老萬株松。","無數煙霞色，空聞昔臥龍。"]', '["静林溪路远，蕭帝有遺蹤。","水擊羅浮磬，山鳴于闐鐘。","灯傳三世火，樹老万株松。","無數煙霞色，空闻昔臥龙。"]', '诗', 'shi', '', NULL, '靜林精舍 靈一 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6c55455c-6682-4f82-af61-b122c047b1ce', '江行寄張舍人', '江行寄張舍人', 'da4f5f43-774c-45b0-8e4f-10b11cfae4f7', '唐', '["客程終日風塵苦，蓬轉還家未有期。","林色曉分殘雪後，角聲寒奏落帆時。","月高星使東看遠，雲破霜鴻北度遲。","流蕩此心難共說，千峰澄霽隔瓊枝。"]', '["客程終日风塵苦，蓬轉還家未有期。","林色晓分殘雪後，角声寒奏落帆时。","月高星使东看远，云破霜鴻北度遲。","流蕩此心难共说，千峰澄霽隔瓊枝。"]', '诗', 'shi', '', NULL, '江行寄張舍人 靈一 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('36ea9a24-b6ae-41b6-a9e1-8c65bd05a30a', '送王穎悟歸左綿', '送王穎悟归左綿', 'da4f5f43-774c-45b0-8e4f-10b11cfae4f7', '唐', '["客意天南興已闌，不堪言別向仙官。","夢搖玉珮隨旄節，心到金華憶杏壇。","荒郊極望歸雲盡，瘦馬空嘶落日殘。","想得故山青靄裏，泉聲入夜獨潺潺。"]', '["客意天南兴已闌，不堪言別向仙官。","梦搖玉珮隨旄節，心到金华憶杏壇。","荒郊極望归云尽，瘦马空嘶落日殘。","想得故山青靄裏，泉声入夜独潺潺。"]', '诗', 'shi', '', NULL, '送王穎悟歸左綿 靈一 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b086fb1-24ae-44ff-8483-57392b349f9a', '安公', '安公', 'da4f5f43-774c-45b0-8e4f-10b11cfae4f7', '唐', '["彌天稱聖哲，象法初繄賴。","弘道識行藏，匡時知進退。","秦王輕與舉，習生重酬對。","學文古篆中，義顯心經內。","法服應華夏，金言流海岱。","西方浮雲間，更陪龍華會。"]', '["彌天稱聖哲，象法初繄賴。","弘道識行藏，匡时知進退。","秦王轻與舉，習生重酬对。","学文古篆中，義显心經內。","法服應华夏，金言流海岱。","西方浮云间，更陪龙华會。"]', '诗', 'shi', '', NULL, '安公 靈一 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d218dcc3-4b06-4df8-a786-a6da87b83343', '林公', '林公', 'da4f5f43-774c-45b0-8e4f-10b11cfae4f7', '唐', '["支公信高逸，久向山林住。","時將孫許遊，豈以形骸遇。","幸辭天子詔，復覽名臣疏。","西晉尚虛無，南朝久淪悞。","因談老莊意，乃盡逍遙趣。","誰爲竹林賢，風流相比附。"]', '["支公信高逸，久向山林住。","时將孫許游，豈以形骸遇。","幸辞天子詔，复覽名臣疏。","西晉尚虛無，南朝久淪悞。","因談老莊意，乃尽逍遙趣。","誰爲竹林賢，风流相比附。"]', '诗', 'shi', '', NULL, '林公 靈一 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2fd77559-46a5-42d2-9798-697d53fe1617', '遠公', '远公', 'da4f5f43-774c-45b0-8e4f-10b11cfae4f7', '唐', '["遠公逢道安，一朝棄儒服。","真機久消歇，世教空拘束。","誓入羅浮中，遂棲廬山曲。","禪經初纂定，佛語新名目。","鉢帽絕朝宗，簪裾翻拜伏。","東林多隱士，爲我辭榮祿。"]', '["远公逢道安，一朝棄儒服。","真機久消歇，世教空拘束。","誓入羅浮中，遂棲廬山曲。","禪經初纂定，佛語新名目。","鉢帽絕朝宗，簪裾翻拜伏。","东林多隐士，爲我辞榮祿。"]', '诗', 'shi', '', NULL, '遠公 靈一 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('496481f2-d29b-415d-bc50-be2b7828ed0f', '雨後欲尋天目山問元駱二公溪路', '雨後欲尋天目山问元駱二公溪路', 'da4f5f43-774c-45b0-8e4f-10b11cfae4f7', '唐', '["昨夜雲生天井東，春山一雨一回風。","林花併逐溪流下，欲上龍池通不通。"]', '["昨夜云生天井东，春山一雨一回风。","林花併逐溪流下，欲上龙池通不通。"]', '诗', 'shi', '', NULL, '雨後欲尋天目山問元駱二公溪路 靈一 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a259dbe2-8920-467f-a8ee-8b05c2aed4b1', '題僧院', '題僧院', 'da4f5f43-774c-45b0-8e4f-10b11cfae4f7', '唐', '["虎溪閑月引相過，帶雪松枝挂薜蘿。","無限青山行欲盡，白雲深處老僧多。"]', '["虎溪闲月引相過，带雪松枝挂薜蘿。","無限青山行欲尽，白云深处老僧多。"]', '诗', 'shi', '', NULL, '題僧院 靈一 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2f3625d5-e292-474f-8d7b-5b60a5f8bb52', '宿靜林寺', '宿静林寺', 'da4f5f43-774c-45b0-8e4f-10b11cfae4f7', '唐', '["山寺門前多古松，溪行欲到已聞鐘。","中宵引領尋高頂，月照雲峰凡幾重。"]', '["山寺门前多古松，溪行欲到已闻鐘。","中宵引領尋高頂，月照云峰凡幾重。"]', '诗', 'shi', '', NULL, '宿靜林寺 靈一 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2a4ba762-2524-4dc1-b3e4-c83755418f16', '再還宜豐寺', '再還宜豐寺', 'da4f5f43-774c-45b0-8e4f-10b11cfae4f7', '唐', '["再尋招隱地，重會息心期。","樵客問歸日，山僧記別時。","野雲陰遠甸，秋雨漲前陂。","勿謂探形勝，吾今不好奇。"]', '["再尋招隐地，重會息心期。","樵客问归日，山僧記別时。","野云陰远甸，秋雨漲前陂。","勿謂探形勝，吾今不好奇。"]', '诗', 'shi', '', NULL, '再還宜豐寺 靈一 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e6c19e01-fde5-437d-9c29-9eb5b8fe87d1', '春日山齋', '春日山斋', 'da4f5f43-774c-45b0-8e4f-10b11cfae4f7', '唐', '["野逕東風起，山扉度日開。","晴光拆紅萼，流水長青苔。","逋客殊未去，芳時已再來。","非關戀春草，自是欲裴回。"]', '["野逕东风起，山扉度日开。","晴光拆紅萼，流水长青苔。","逋客殊未去，芳时已再来。","非关戀春草，自是欲裴回。"]', '诗', 'shi', '', NULL, '春日山齋 靈一 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('99f29e16-c8cc-44c4-9986-8b78103c48aa', '留別忠州故人', '留別忠州故人', 'da4f5f43-774c-45b0-8e4f-10b11cfae4f7', '唐', '["一身無定處，萬里獨銷魂。","芳草迷歸路，春流滴淚痕。","幾時休旅食，何夜宿江村。","欲識相思苦，空山啼暮猨。"]', '["一身無定处，万里独銷魂。","芳草迷归路，春流滴泪痕。","幾时休旅食，何夜宿江村。","欲識相思苦，空山啼暮猨。"]', '诗', 'shi', '', NULL, '留別忠州故人 靈一 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1677ecc0-38c9-4ef7-8bd0-7c95de73498a', '送別', '送別', 'da4f5f43-774c-45b0-8e4f-10b11cfae4f7', '唐', '["憑高莫送遠，看欲斷歸心。","別恨啼猨苦，相思流水深。","翠雲南澗影，丹桂晚山陰。","若未來雙鵠，遼城何更尋。"]', '["憑高莫送远，看欲斷归心。","別恨啼猨苦，相思流水深。","翠云南澗影，丹桂晚山陰。","若未来雙鵠，遼城何更尋。"]', '诗', 'shi', '', NULL, '送別 靈一 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('11223579-1400-4587-8a47-15baae393c50', '送冽寺主之京迎禪和尚', '送冽寺主之京迎禪和尚', 'da4f5f43-774c-45b0-8e4f-10b11cfae4f7', '唐', '["禪門居此地，瞻望在虛空。","水國月未上，蒼生如夢中。","上人知機士，瓶錫慰樊籠。","彼土諸梵衆，嗟君揚道風。"]', '["禪门居此地，瞻望在虛空。","水国月未上，蒼生如梦中。","上人知機士，瓶錫慰樊籠。","彼土諸梵衆，嗟君揚道风。"]', '诗', 'shi', '', NULL, '送冽寺主之京迎禪和尚 靈一 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1d2d3a7c-4f70-4194-b13b-89956213a605', '送王法師之西川', '送王法師之西川', 'da4f5f43-774c-45b0-8e4f-10b11cfae4f7', '唐', '["旅遊無近遠，要自別魂銷。","官柳鄉愁亂，春山客路遙。","伴行芳草遠，緣興野花飄。","計日功成後，還將輔聖朝。"]', '["旅游無近远，要自別魂銷。","官柳乡愁亂，春山客路遙。","伴行芳草远，緣兴野花飄。","計日功成後，還將輔聖朝。"]', '诗', 'shi', '', NULL, '送王法師之西川 靈一 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('10d43809-955c-42c1-b1a5-595ab73c3292', '送範律師往果州', '送範律師往果州', 'da4f5f43-774c-45b0-8e4f-10b11cfae4f7', '唐', '["終南千古後，獨爾繼卿名。","離障非今日，脩因是幾生。","亂峰寒影暮，深澗野流清。","遠客歸心苦，難爲此別情。"]', '["終南千古後，独爾繼卿名。","離障非今日，脩因是幾生。","亂峰寒影暮，深澗野流清。","远客归心苦，难爲此別情。"]', '诗', 'shi', '', NULL, '送範律師往果州 靈一 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('10fd5f1a-f4b0-44de-a2fe-fe0ea9ec0452', '送明素上人歸楚覲省', '送明素上人归楚覲省', 'da4f5f43-774c-45b0-8e4f-10b11cfae4f7', '唐', '["能將疎懶背時人，不厭孤萍任此身。","江上昔年同出處，天涯今日共風塵。","平湖舊隱應殘雪，芳草歸心未隔春。","前路倍憐多勝事，到家知慶綵衣新。"]', '["能將疎懶背时人，不厭孤萍任此身。","江上昔年同出处，天涯今日共风塵。","平湖旧隐應殘雪，芳草归心未隔春。","前路倍怜多勝事，到家知慶綵衣新。"]', '诗', 'shi', '', NULL, '送明素上人歸楚覲省 靈一 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('12c4c59c-1731-4a08-8451-b6196514c7fb', '項王廟', '項王廟', 'da4f5f43-774c-45b0-8e4f-10b11cfae4f7', '唐', '["緬想咸陽事可嗟，楚歌哀怨思無涯。","八千子弟歸何處，萬里鴻溝屬漢家。","弓斷陣前爭日月，血流垓下定龍蛇。","拔山力盡烏江水，今日悠悠空浪花。"]', '["緬想咸陽事可嗟，楚歌哀怨思無涯。","八千子弟归何处，万里鴻溝屬漢家。","弓斷陣前爭日月，血流垓下定龙蛇。","拔山力尽烏江水，今日悠悠空浪花。"]', '诗', 'shi', '', NULL, '項王廟 靈一 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('687672f5-42e2-44b3-b628-4945e3e13967', '酬陳明府舟中見贈', '酬陳明府舟中见贈', 'da4f5f43-774c-45b0-8e4f-10b11cfae4f7', '唐', '["長溪通夜靜，素舸與人閑。","月影沈秋水，風聲落暮山。","稻花千頃外，蓮葉兩河間。","陶令多真意，相思一解顏。"]', '["长溪通夜静，素舸與人闲。","月影沈秋水，风声落暮山。","稻花千頃外，蓮葉兩河间。","陶令多真意，相思一解顏。"]', '诗', 'shi', '', NULL, '酬陳明府舟中見贈 靈一 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3dabe898-2356-4429-8e68-e6d63793a231', '題東蘭若', '題东蘭若', 'da4f5f43-774c-45b0-8e4f-10b11cfae4f7', '唐', '["上入禪室路裴回，萬木清陰向日開。","寒竹影侵行逕石，秋風聲入誦經臺。","閑雲不繫從舒卷，狎鳥無機任往來。","更惜片陽談妙理，歸時莫待暝鐘催。"]', '["上入禪室路裴回，万木清陰向日开。","寒竹影侵行逕石，秋风声入誦經台。","闲云不繫從舒卷，狎鸟無機任往来。","更惜片陽談妙理，归时莫待暝鐘催。"]', '诗', 'shi', '', NULL, '題東蘭若 靈一 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('55f12ad3-7e94-457d-a19b-17d57fbe3a8b', '送朱放', '送朱放', 'da4f5f43-774c-45b0-8e4f-10b11cfae4f7', '唐', '["苦見人間世，思歸洞裏天。","縱令山鳥語，不廢野人眠。"]', '["苦见人间世，思归洞裏天。","縱令山鸟語，不廢野人眠。"]', '诗', 'shi', '', NULL, '送朱放 靈一 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('99a54334-fe8d-4855-9778-00d5932e37c7', '歸岑山過惟審上人別業', '归岑山過惟審上人別業', 'da4f5f43-774c-45b0-8e4f-10b11cfae4f7', '唐', '["禪客無心憶薜蘿，自然行徑向山多。","知君欲問人間事，始與浮雲共一過。"]', '["禪客無心憶薜蘿，自然行徑向山多。","知君欲问人间事，始與浮云共一過。"]', '诗', 'shi', '', NULL, '歸岑山過惟審上人別業 靈一 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0be3b57d-e63b-4c99-815d-d431059df121', '於潛道中呈元八處士', '於潛道中呈元八处士', 'da4f5f43-774c-45b0-8e4f-10b11cfae4f7', '唐', '["苕水灘行淺，潛州路漸深。","參差遠岫色，迢遞野人心。","凍澗冰難釋，秋山日易陰。"]', '["苕水灘行淺，潛州路漸深。","參差远岫色，迢遞野人心。","凍澗冰难釋，秋山日易陰。"]', '诗', 'shi', '', NULL, '於潛道中呈元八處士 靈一 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2453d4ef-e09d-4430-8a90-baaa296fb18a', '送殷判官歸上都', '送殷判官归上都', 'da4f5f43-774c-45b0-8e4f-10b11cfae4f7', '唐', '["漾舟雲路客，來過夕陽時。","向背堪遺恨，逢迎宿未期。","水容愁暮急，花影動春遲。","別後王孫草，青青入夢思。"]', '["漾舟云路客，来過夕陽时。","向背堪遺恨，逢迎宿未期。","水容愁暮急，花影动春遲。","別後王孫草，青青入梦思。"]', '诗', 'shi', '', NULL, '送殷判官歸上都 靈一 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c35fd6f-e6d5-4e80-988d-c8e49214b0c9', '贈別皇甫曾', '贈別皇甫曾', 'da4f5f43-774c-45b0-8e4f-10b11cfae4f7', '唐', '["幽人從遠岳，過客愛春山。","高駕能相送，孤遊且未還。","紫苔封井石，綠竹掩柴關。","若到雲峰外，齊心去住間。"]', '["幽人從远岳，過客愛春山。","高駕能相送，孤游且未還。","紫苔封井石，綠竹掩柴关。","若到云峰外，齊心去住间。"]', '诗', 'shi', '', NULL, '贈別皇甫曾 靈一 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf3f8a1c-6ec7-4128-9f03-9f75d8f4f34c', '送陳允初卜居麻園', '送陳允初卜居麻园', 'da4f5f43-774c-45b0-8e4f-10b11cfae4f7', '唐', '["欲向麻源隱，能尋謝客蹤。","空山幾千里，幽谷第三重。","茅宇寧須葺，荷衣不待縫。","因君見往事，爲我謝喬松。"]', '["欲向麻源隐，能尋謝客蹤。","空山幾千里，幽谷第三重。","茅宇寧須葺，荷衣不待縫。","因君见往事，爲我謝喬松。"]', '诗', 'shi', '', NULL, '送陳允初卜居麻園 靈一 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2825aaf0-0489-43a1-ae1a-2056f12e428f', '秋題劉逸人林泉', '秋題劉逸人林泉', 'da4f5f43-774c-45b0-8e4f-10b11cfae4f7', '唐', '["涼飆亂黃葉，遲客橘陰清。","蘿徑封行跡，雲門閉野情。","零林秋露響，穿竹暮煙輕。","莫戀幽棲地，懷安却敗名。"]', '["涼飆亂黄葉，遲客橘陰清。","蘿徑封行跡，云门閉野情。","零林秋露响，穿竹暮煙轻。","莫戀幽棲地，懷安却敗名。"]', '诗', 'shi', '', NULL, '秋題劉逸人林泉 靈一 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f57f07a2-433b-47cc-9c85-dae1683d1043', '自大林與韓明府歸郭中精舍', '自大林與韓明府归郭中精舍', 'da4f5f43-774c-45b0-8e4f-10b11cfae4f7', '唐', '["野客同舟楫，相攜復一歸。","孤煙生暮景，遠岫帶春暉。","不道還山是，誰云向郭非。","禪門有通隱，喧寂共忘機。"]', '["野客同舟楫，相携复一归。","孤煙生暮景，远岫带春暉。","不道還山是，誰云向郭非。","禪门有通隐，喧寂共忘機。"]', '诗', 'shi', '', NULL, '自大林與韓明府歸郭中精舍 靈一 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b786421e-8065-4df8-bcf9-8eb9e9dfe544', '同使君宿大梁驛', '同使君宿大梁驛', 'da4f5f43-774c-45b0-8e4f-10b11cfae4f7', '唐', '["旌旗江上出，花外捲簾空。","夜色臨城月，春寒度水風。","雖然行李別，且喜語音同。","若問匡廬事，終身媿遠公。"]', '["旌旗江上出，花外捲簾空。","夜色臨城月，春寒度水风。","雖然行李別，且喜語音同。","若问匡廬事，終身媿远公。"]', '诗', 'shi', '', NULL, '同使君宿大梁驛 靈一 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('52c9a166-c7c9-4a7b-9fc0-40a78f7c810c', '題黃公陶翰別業', '題黄公陶翰別業', 'da4f5f43-774c-45b0-8e4f-10b11cfae4f7', '唐', '["聞說花源堪避秦，幽尋數月不逢人。","煙霞洞裏無雞犬，風雨林間有鬼神。","黃公石上三芝秀，陶令門前五柳春。","醉臥白雲閑入夢，不知何物是吾身。"]', '["闻说花源堪避秦，幽尋數月不逢人。","煙霞洞裏無雞犬，风雨林间有鬼神。","黄公石上三芝秀，陶令门前五柳春。","醉臥白云闲入梦，不知何物是吾身。"]', '诗', 'shi', '', NULL, '題黃公陶翰別業 靈一 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('11d45373-18b3-4358-a460-7238dbce4ea7', '哭衛尚書', '哭衛尚书', 'da4f5f43-774c-45b0-8e4f-10b11cfae4f7', '唐', '["畫戟重門楚水陰，天涯欲暮共傷心。","南荆雙戟痕猶在，北斗孤魂望已深。","蓮花幕下悲風起，細柳營邊曉月臨。","有路茫茫向誰問，感君空有淚霑襟。"]', '["畫戟重门楚水陰，天涯欲暮共傷心。","南荆雙戟痕猶在，北斗孤魂望已深。","蓮花幕下悲风起，細柳營邊晓月臨。","有路茫茫向誰问，感君空有泪霑襟。"]', '诗', 'shi', '', NULL, '哭衛尚書 靈一 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d3599744-2346-4d5d-861f-f70fb6c64256', '贈靈澈禪師', '贈靈澈禪師', 'da4f5f43-774c-45b0-8e4f-10b11cfae4f7', '唐', '["禪師來往翠微間，萬里千峰到剡山。","何時共到天台裏，身與浮雲處處閑。"]', '["禪師来往翠微间，万里千峰到剡山。","何时共到天台裏，身與浮云处处闲。"]', '诗', 'shi', '', NULL, '贈靈澈禪師 靈一 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f3eef5d5-716a-4604-9c5f-e43622122eb2', '將出宜豐寺留題山房', '將出宜豐寺留題山房', 'da4f5f43-774c-45b0-8e4f-10b11cfae4f7', '唐', '["池上蓮荷不自開，山中流水偶然來。","若言聚散定由我，未是回時那得回。"]', '["池上蓮荷不自开，山中流水偶然来。","若言聚散定由我，未是回时那得回。"]', '诗', 'shi', '', NULL, '將出宜豐寺留題山房 靈一 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('48c1155c-db42-4da7-9fe5-a3e5ff014f55', '妙樂觀', '妙乐观', 'da4f5f43-774c-45b0-8e4f-10b11cfae4f7', '唐', '["王喬所居空山觀，白雲至今凝不散。","壇場月路幾千年，往往吹笙下天半。","瀑布西行過石橋，黃精採根還採苗。","忽見一人檠茶碗，篸花昨夜風吹滿。","自言家處在東坡，白犬相隨邀我過。","松間石上有棊局，能使樵人爛斧柯。"]', '["王喬所居空山观，白云至今凝不散。","壇場月路幾千年，往往吹笙下天半。","瀑布西行過石橋，黄精採根還採苗。","忽见一人檠茶碗，篸花昨夜风吹满。","自言家处在东坡，白犬相隨邀我過。","松间石上有棊局，能使樵人爛斧柯。"]', '诗', 'shi', '', NULL, '妙樂觀 靈一 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c27027fb-17c5-4b5c-89de-c2ee9bccbbc8', '與元居士青山潭飲茶', '與元居士青山潭饮茶', 'da4f5f43-774c-45b0-8e4f-10b11cfae4f7', '唐', '["野泉煙火白雲間，坐飲香茶愛此山。","巖下維舟不忍去，青溪流水暮潺潺。"]', '["野泉煙火白云间，坐饮香茶愛此山。","巖下維舟不忍去，青溪流水暮潺潺。"]', '诗', 'shi', '', NULL, '與元居士青山潭飲茶 靈一 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b157fafc-0570-4363-bd58-956ab9996f19', '送人得蕩子歸倡婦', '送人得蕩子归倡婦', 'da4f5f43-774c-45b0-8e4f-10b11cfae4f7', '唐', '["垂涕憑回信，爲語柳園人。","情知獨難守，又是一陽春。"]', '["垂涕憑回信，爲語柳园人。","情知独难守，又是一陽春。"]', '诗', 'shi', '', NULL, '送人得蕩子歸倡婦 靈一 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c9d80fbd-8ad0-428b-bef1-9f80dc33859e', '句', '句', 'da4f5f43-774c-45b0-8e4f-10b11cfae4f7', '唐', '["濾泉侵月起，掃徑避蟲行。"]', '["濾泉侵月起，掃徑避蟲行。"]', '诗', 'shi', '', NULL, '句 靈一 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb3baba2-08b8-41f7-93c1-2556ccc9cd03', '聽鶯歌', '听鶯歌', 'becd2cfe-6e73-4c76-9344-10e076982e22', '唐', '["新鶯傍簷曉更悲，孤音清泠囀素枝。","口邊血出語未盡，豈是怨恨人不知。","不食枯桑葚，不銜苦李花。","偶然弄樞機，婉轉凌煙霞。","衆雛飛鳴何跼促，自覘游蜂啄枯木。","玄猨何事朝夜啼，白鷺長在汀洲宿。","黑鵰黃鶴豈不高，金籠玉鉤傷羽毛。","三江七澤去不得，風煙日暮生波濤。","飛去來，莫上高城頭，莫下空園裏。","城頭鴟鳥拾羶腥，空園燕雀爭泥滓。","願當結舌含白雲，五月六月一聲不可聞。"]', '["新鶯傍簷晓更悲，孤音清泠囀素枝。","口邊血出語未尽，豈是怨恨人不知。","不食枯桑葚，不銜苦李花。","偶然弄樞機，婉轉凌煙霞。","衆雛飞鳴何跼促，自覘游蜂啄枯木。","玄猨何事朝夜啼，白鷺长在汀洲宿。","黑鵰黄鹤豈不高，金籠玉鉤傷羽毛。","三江七澤去不得，风煙日暮生波濤。","飞去来，莫上高城头，莫下空园裏。","城头鴟鸟拾羶腥，空园燕雀爭泥滓。","願當結舌含白云，五月六月一声不可闻。"]', '诗', 'shi', '', NULL, '聽鶯歌 靈澈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d8f7faec-e05c-41d0-8274-563d67bb1ba2', '歸湖南作', '归湖南作', 'becd2cfe-6e73-4c76-9344-10e076982e22', '唐', '["山邊水邊待月明，暫向人間借路行。","如今還向山邊去，只有湖水無行路。"]', '["山邊水邊待月明，暫向人间借路行。","如今還向山邊去，只有湖水無行路。"]', '诗', 'shi', '', NULL, '歸湖南作 靈澈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('05eaa52a-410f-49fa-8b61-64993e5f99fe', '初到汀州', '初到汀州', 'becd2cfe-6e73-4c76-9344-10e076982e22', '唐', '["初放到滄洲，前心詎解愁。","舊交容不拜，臨老學梳頭。","禪室白雲去，故山明月秋。","幾年猶在此，北戶水南流。"]', '["初放到滄洲，前心詎解愁。","旧交容不拜，臨老学梳头。","禪室白云去，故山明月秋。","幾年猶在此，北戶水南流。"]', '诗', 'shi', '', NULL, '初到汀州 靈澈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5eaa230b-69e8-41d4-8799-1af8ab21e870', '九日和于使君思上京親故', '九日和于使君思上京親故', 'becd2cfe-6e73-4c76-9344-10e076982e22', '唐', '["清晨有高會，賓從出東方。","楚俗風煙古，汀洲草木涼。","山情來遠思，菊意在重陽。","心憶華池上，從容鴛鷺行。"]', '["清晨有高會，賓從出东方。","楚俗风煙古，汀洲草木涼。","山情来远思，菊意在重陽。","心憶华池上，從容鴛鷺行。"]', '诗', 'shi', '', NULL, '九日和于使君思上京親故 靈澈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f81e83bd-da8a-4732-8ccc-6598cfab1567', '送道虔上人游方', '送道虔上人游方', 'becd2cfe-6e73-4c76-9344-10e076982e22', '唐', '["律儀通外學，詩思入玄關。","煙景隨緣到，風姿與道閑。","貫花留淨室，呪水度空山。","誰識浮雲意，悠悠天地間。"]', '["律儀通外学，诗思入玄关。","煙景隨緣到，风姿與道闲。","貫花留淨室，呪水度空山。","誰識浮云意，悠悠天地间。"]', '诗', 'shi', '', NULL, '送道虔上人游方 靈澈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('182ce674-154a-4774-9155-f52eb9be7d58', '送鑒供奉歸蜀寧親', '送鑒供奉归蜀寧親', 'becd2cfe-6e73-4c76-9344-10e076982e22', '唐', '["林間出定戀庭闈，聖主恩深暫許歸。","雙樹欲辭金錫冷，四花猶向玉階飛。","梁山拂漢分清境，蜀雪和煙惹翠微。","此去不須求綵服，紫衣全勝老萊衣。"]', '["林间出定戀庭闈，聖主恩深暫許归。","雙樹欲辞金錫冷，四花猶向玉階飞。","梁山拂漢分清境，蜀雪和煙惹翠微。","此去不須求綵服，紫衣全勝老萊衣。"]', '诗', 'shi', '', NULL, '送鑒供奉歸蜀寧親 靈澈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d75d10f2-7355-4692-b8be-fb480ec5bfd4', '天姥岑望天台山', '天姥岑望天台山', 'becd2cfe-6e73-4c76-9344-10e076982e22', '唐', '["天台衆峯外，華頂當寒空。","有時半不見，崔嵬在雲中。"]', '["天台衆峯外，华頂當寒空。","有时半不见，崔嵬在云中。"]', '诗', 'shi', '', NULL, '天姥岑望天台山 靈澈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('44407cb2-b65a-4b45-9d9d-490d27103f4f', '遠公墓', '远公墓', 'becd2cfe-6e73-4c76-9344-10e076982e22', '唐', '["古墓石稜稜，寒雲晚景凝。","空悲虎溪月，不見鴈門僧。"]', '["古墓石稜稜，寒云晚景凝。","空悲虎溪月，不见鴈门僧。"]', '诗', 'shi', '', NULL, '遠公墓 靈澈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fb83d515-8c51-4424-8e60-5b8d2bda2614', '宿東林寺', '宿东林寺', 'becd2cfe-6e73-4c76-9344-10e076982e22', '唐', '["天寒猛虎叫巖雪，林下無人空有月。","千年像教今不聞，焚香獨爲鬼神說。"]', '["天寒猛虎叫巖雪，林下無人空有月。","千年像教今不闻，焚香独爲鬼神说。"]', '诗', 'shi', '', NULL, '宿東林寺 靈澈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('15636371-7eb4-4a51-b5be-ad9c30842a99', '簡寂觀', '簡寂观', 'becd2cfe-6e73-4c76-9344-10e076982e22', '唐', '["古松古柏巖壁間，猨攀鶴巢古枝折。","五月有霜六月寒，時見山翁來取雪。"]', '["古松古柏巖壁间，猨攀鹤巢古枝折。","五月有霜六月寒，时见山翁来取雪。"]', '诗', 'shi', '', NULL, '簡寂觀 靈澈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fc5ea508-8105-499e-abef-fd1aea6e6570', '元日觀郭將軍早朝', '元日观郭將軍早朝', 'becd2cfe-6e73-4c76-9344-10e076982e22', '唐', '["欲曙九衢人更多，千條香燭照星河。","今朝始見金吾貴，車馬縱橫避玉珂。"]', '["欲曙九衢人更多，千條香燭照星河。","今朝始见金吾貴，车马縱橫避玉珂。"]', '诗', 'shi', '', NULL, '元日觀郭將軍早朝 靈澈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('70df7406-953a-4775-b8b3-cb9aec4fc282', '東林寺酬韋丹刺史', '东林寺酬韋丹刺史', 'becd2cfe-6e73-4c76-9344-10e076982e22', '唐', '["年老心閑無外事，麻衣草座亦容身。","相逢盡道休官好，林下何曾見一人。"]', '["年老心闲無外事，麻衣草座亦容身。","相逢尽道休官好，林下何曾见一人。"]', '诗', 'shi', '', NULL, '東林寺酬韋丹刺史 靈澈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c9f86105-9b01-4a6e-85d7-61873c59af38', '東林寺寄包侍御', '东林寺寄包侍御', 'becd2cfe-6e73-4c76-9344-10e076982e22', '唐', '["古殿清陰山木春，池邊跂石一觀身。","誰能來此焚香坐，共作罏峯二十人。"]', '["古殿清陰山木春，池邊跂石一观身。","誰能来此焚香坐，共作罏峯二十人。"]', '诗', 'shi', '', NULL, '東林寺寄包侍御 靈澈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7dcfee10-85f3-4c5b-b2bd-82d2e9845a91', '西林寄楊公', '西林寄楊公', 'becd2cfe-6e73-4c76-9344-10e076982e22', '唐', '["日日愛山歸已遲，閑閑空度少年時。","余身定寄林中老，心與長松片石期。"]', '["日日愛山归已遲，闲闲空度少年时。","余身定寄林中老，心與长松片石期。"]', '诗', 'shi', '', NULL, '西林寄楊公 靈澈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cf42fa29-3234-4fd3-b21c-85dc95619905', '荅徐廣叔四問', '荅徐廣叔四问', 'becd2cfe-6e73-4c76-9344-10e076982e22', '唐', '["童子出家無第行，隨師乞食遣稱名。","長沙豈敢論年幾，絳老惟知甲子生。"]', '["童子出家無第行，隨師乞食遣稱名。","长沙豈敢論年幾，絳老惟知甲子生。"]', '诗', 'shi', '', NULL, '荅徐廣叔四問 靈澈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('daf40fe3-ecd8-4f43-a329-6b0f40ca8906', '聞李處士亡', '闻李处士亡', 'becd2cfe-6e73-4c76-9344-10e076982e22', '唐', '["時時聞說故人死，日日自悲隨老身。","白髮不生應不得，青山長在屬何人。"]', '["时时闻说故人死，日日自悲隨老身。","白髮不生應不得，青山长在屬何人。"]', '诗', 'shi', '', NULL, '聞李處士亡 靈澈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('859e2308-e9d5-4472-9cd9-2885252df5f0', '句', '句', 'becd2cfe-6e73-4c76-9344-10e076982e22', '唐', '["松樹有死枝，塚上唯莓苔。","石門無人入，古木花不開。","綠竹歲寒在，故人衰老多。","月色靜中見，泉聲深處聞。","古觀茅山下，諸峯欲曙時。","真人是黃子，玉堂生紫芝。","禪門至六祖，衣鉢無人得。","古墓碑表折，荒壠松柏稀。","秋深知氣正，家近覺山寒。","山僧不記重陽日，因見茱萸憶去年。","今非古獄下，莫向斗邊看。","海月生殘夜，江春入暮年。","窗風枯硯水，山雨慢琴弦。"]', '["松樹有死枝，塚上唯莓苔。","石门無人入，古木花不开。","綠竹歲寒在，故人衰老多。","月色静中见，泉声深处闻。","古观茅山下，諸峯欲曙时。","真人是黄子，玉堂生紫芝。","禪门至六祖，衣鉢無人得。","古墓碑表折，荒壠松柏稀。","秋深知氣正，家近覺山寒。","山僧不記重陽日，因见茱萸憶去年。","今非古獄下，莫向斗邊看。","海月生殘夜，江春入暮年。","窗风枯硯水，山雨慢琴弦。"]', '诗', 'shi', '', NULL, '句 靈澈 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c04861a2-67e3-42e5-9ccc-f370843238e7', '湘夫人祠', '湘夫人祠', 'c1f75c17-d5d6-49b9-b731-fc7f5350a8f3', '唐', '["靈祠古木合，波颺大江濆。","未□湘南雨，知爲何處雲。","苔痕澀珠履，草色妒羅裙。","妙鼓彤雲瑟，羈臣不可聞。"]', '["靈祠古木合，波颺大江濆。","未□湘南雨，知爲何处云。","苔痕澀珠履，草色妒羅裙。","妙鼓彤云瑟，羈臣不可闻。"]', '诗', 'shi', '', NULL, '湘夫人祠 大易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f88cbc54-e083-4145-9217-f79a7082e150', '贈司空拾遺', '贈司空拾遺', 'c1f75c17-d5d6-49b9-b731-fc7f5350a8f3', '唐', '["侍臣何事辭雲陛，江上微雲見雪花。","望閣未承丹鳳詔，掩門空對楚人家。","陳琳草奏才還在，王粲登樓興未賒。","高館更容塵外客，仍令歸路待瑤華。"]', '["侍臣何事辞云陛，江上微云见雪花。","望閣未承丹鳳詔，掩门空对楚人家。","陳琳草奏才還在，王粲登楼兴未賒。","高館更容塵外客，仍令归路待瑤华。"]', '诗', 'shi', '', NULL, '贈司空拾遺 大易 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b6ff2497-569b-4120-a582-d535fb711f40', '寄錢郎中', '寄錢郎中', 'aedc6ceb-be35-4d30-ade3-bc8a5c500d39', '唐', '["閉門深樹裏，閑足鳥來過。","五馬不復貴，一僧誰奈何。","藥苗家自有，香飯乞時多。","寄語嬋娟客，將心向薜蘿。"]', '["閉门深樹裏，闲足鸟来過。","五马不复貴，一僧誰奈何。","藥苗家自有，香飯乞时多。","寄語嬋娟客，將心向薜蘿。"]', '诗', 'shi', '', NULL, '寄錢郎中 法照 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ffb26ef1-cdd2-4992-b294-f289c5136274', '送清江上人', '送清江上人', 'aedc6ceb-be35-4d30-ade3-bc8a5c500d39', '唐', '["越人僧體古，清慮洗塵勞。","一國詩名遠，多生律行高。","見山援葛藟，避世著方袍。","早晚雲門去，儂應逐爾曹。"]', '["越人僧體古，清慮洗塵勞。","一国诗名远，多生律行高。","见山援葛藟，避世著方袍。","早晚云门去，儂應逐爾曹。"]', '诗', 'shi', '', NULL, '送清江上人 法照 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b789d346-8be8-4699-9efd-6c8eb76b8e00', '送無著禪師歸新羅', '送無著禪師归新羅', 'aedc6ceb-be35-4d30-ade3-bc8a5c500d39', '唐', '["萬里歸鄉路，隨緣不算程。","尋山百衲弊，過海一杯輕。","夜宿依雲色，晨齋就水聲。","何年持貝葉，却到漢家城。"]', '["万里归乡路，隨緣不算程。","尋山百衲弊，過海一杯轻。","夜宿依云色，晨斋就水声。","何年持貝葉，却到漢家城。"]', '诗', 'shi', '', NULL, '送無著禪師歸新羅 法照 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a3cabb82-133d-46a6-902d-91a2d1eba29e', '游元象泊', '游元象泊', '77c58ad6-4731-42fa-992e-8223ab7f3c7d', '唐', '["空水潮色淨，澹然湖上心。","舳艫輕且進，汀洲如可尋。","秋風洄泝險，落日波濤深。","寂寞武陵去，中流方至今。"]', '["空水潮色淨，澹然湖上心。","舳艫轻且進，汀洲如可尋。","秋风洄泝險，落日波濤深。","寂寞武陵去，中流方至今。"]', '诗', 'shi', '', NULL, '游元象泊 釋泚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4391c2fd-e6a8-4010-a736-2140b795702c', '北原別業', '北原別業', '77c58ad6-4731-42fa-992e-8223ab7f3c7d', '唐', '["野外車騎絕，古村桑柘陰。","流鶯出谷靜，春草閉門深。","學稼農爲業，忘情道作心。","因知上皇日，鑿井在靈林。"]', '["野外车騎絕，古村桑柘陰。","流鶯出谷静，春草閉门深。","学稼農爲業，忘情道作心。","因知上皇日，鑿井在靈林。"]', '诗', 'shi', '', NULL, '北原別業 釋泚 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd94beef-064d-4c50-87cd-7ecfe9fc1209', '雜詩 一', '杂诗 一', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["未識龍宮莫說珠，識珠言說與君殊。","空拳只是嬰兒信，豈得將來誑老夫。"]', '["未識龙宮莫说珠，識珠言说與君殊。","空拳只是嬰兒信，豈得將来誑老夫。"]', '诗', 'shi', '', NULL, '雜詩 一 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cb36e4cc-2743-4522-8bb7-4adf213bd836', '雜詩 二', '杂诗 二', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["萬法從心起，心生萬法生。","法生同日了，來去在虛行。","寄語脩道人，空生慎勿生。","如能達此理，不動出深坑。"]', '["万法從心起，心生万法生。","法生同日了，来去在虛行。","寄語脩道人，空生慎勿生。","如能達此理，不动出深坑。"]', '诗', 'shi', '', NULL, '雜詩 二 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('68f4eb4f-573e-4918-80e2-ef374211f4d6', '雜詩 三', '杂诗 三', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["極目觀前境，寂寞無一人。","迴頭看後底，影亦不隨身。"]', '["極目观前境，寂寞無一人。","迴头看後底，影亦不隨身。"]', '诗', 'shi', '', NULL, '雜詩 三 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bb25d196-f370-4bc0-a101-b339e8d94366', '雜詩 四', '杂诗 四', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["神識苟能無罣礙，廓周法界等虛空。","不假坐禪持戒律，超然解脫豈勞功。"]', '["神識苟能無罣礙，廓周法界等虛空。","不假坐禪持戒律，超然解脫豈勞功。"]', '诗', 'shi', '', NULL, '雜詩 四 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e619ce93-b8f8-4353-a176-6a9e3d2f8a18', '雜詩 五', '杂诗 五', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["日用事無別，惟吾自偶偕。","頭頭非取舍，處處勿張乖。","朱紫誰爲號，青山絕點埃。","神通幷妙用，運水及搬柴。"]', '["日用事無別，惟吾自偶偕。","头头非取舍，处处勿張乖。","朱紫誰爲號，青山絕点埃。","神通幷妙用，運水及搬柴。"]', '诗', 'shi', '', NULL, '雜詩 五 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('696f593c-3ff8-4ae6-b491-99d732219066', '雜詩 六', '杂诗 六', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["十方同聚會，個個學無爲。","此是選佛場，心空及第歸。"]', '["十方同聚會，個個学無爲。","此是選佛場，心空及第归。"]', '诗', 'shi', '', NULL, '雜詩 六 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f76bc373-d980-42d4-88d0-282f58a305cd', '雜詩 七', '杂诗 七', '0fbe3ad4-df5f-46ff-8a5c-894a5447f714', '唐', '["熖水無魚下底鉤，覓魚無處笑君愁。","可憐谷隱老禪伯，被唾如何見亦羞。"]', '["熖水無鱼下底鉤，覓鱼無处笑君愁。","可怜谷隐老禪伯，被唾如何见亦羞。"]', '诗', 'shi', '', NULL, '雜詩 七 龐藴 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('05791273-8a39-45ac-b858-dc2d370cb10f', '歸山作', '归山作', '14bc81cf-e502-41e2-b7d0-8e73b699f670', '唐', '["諠靜各有路，偶隨心所安。","縱然在朝市，終不忘林巒。","四皓將拂衣，二疏能挂冠。","窓前隱逸傳，每日三時看。","靳尚那可論，屈原亦可歎。","至今黃泉下，名及青雲端。","松牖見初月，花間禮古壇。","何處論心懷，世上空漫漫。"]', '["諠静各有路，偶隨心所安。","縱然在朝市，終不忘林巒。","四皓將拂衣，二疏能挂冠。","窓前隐逸傳，每日三时看。","靳尚那可論，屈原亦可歎。","至今黄泉下，名及青云端。","松牖见初月，花间禮古壇。","何处論心懷，世上空漫漫。"]', '诗', 'shi', '', NULL, '歸山作 護國 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d629a68c-097f-4af3-872d-c8e596bd0e48', '題醴陵玉仙觀歌', '題醴陵玉仙观歌', '14bc81cf-e502-41e2-b7d0-8e73b699f670', '唐', '["王喬一去空仙觀，白雲至今凝不散。","星垣松殿幾千秋，往往笙歌天下半。","瀑布西行過石橋，黃精採根還採苗。","路逢一人擎藥椀，松花夜雨風吹滿。","自言家住在東坡，白犬相隨邀我過。","南山石上有棊局，曾使樵夫爛斧柯。"]', '["王喬一去空仙观，白云至今凝不散。","星垣松殿幾千秋，往往笙歌天下半。","瀑布西行過石橋，黄精採根還採苗。","路逢一人擎藥椀，松花夜雨风吹满。","自言家住在东坡，白犬相隨邀我過。","南山石上有棊局，曾使樵夫爛斧柯。"]', '诗', 'shi', '', NULL, '題醴陵玉仙觀歌 護國 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9e7364d8-49f0-4e93-84ff-638d2d64d0de', '訪雲母山僧', '訪云母山僧', '14bc81cf-e502-41e2-b7d0-8e73b699f670', '唐', '["森然古巖裏，淨行一番僧。","松下濾寒水，佛前挑夜燈。","蓮花國土異，貝葉梵書能。","想到空王境，無心問愛憎。"]', '["森然古巖裏，淨行一番僧。","松下濾寒水，佛前挑夜灯。","蓮花国土異，貝葉梵书能。","想到空王境，無心问愛憎。"]', '诗', 'shi', '', NULL, '訪雲母山僧 護國 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d6b8647f-4683-4732-b077-f3c576151f73', '題王班水亭', '題王班水亭', '14bc81cf-e502-41e2-b7d0-8e73b699f670', '唐', '["湖上見秋色，曠然如爾懷。","豈惟歡隴畝，兼亦外形骸。","待月歸山寺，彈琴坐暝齋。","布衣閑自貴，何用謁天階。"]', '["湖上见秋色，曠然如爾懷。","豈惟歡隴畝，兼亦外形骸。","待月归山寺，彈琴坐暝斋。","布衣闲自貴，何用謁天階。"]', '诗', 'shi', '', NULL, '題王班水亭 護國 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ecd2cd4-c617-4a8f-a676-79c2a8997ae7', '山中寄王員外', '山中寄王員外', '14bc81cf-e502-41e2-b7d0-8e73b699f670', '唐', '["爲問幽蘭桂，空山復若何。","芬芳終有分，採折更誰過。","望在軒階近，恩霑雨露多。","移居儻得地，長願接瓊柯。"]', '["爲问幽蘭桂，空山复若何。","芬芳終有分，採折更誰過。","望在軒階近，恩霑雨露多。","移居儻得地，长願接瓊柯。"]', '诗', 'shi', '', NULL, '山中寄王員外 護國 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('398cc8c4-da35-473c-939d-61e627e91973', '許州鄭使君孩子', '許州鄭使君孩子', '14bc81cf-e502-41e2-b7d0-8e73b699f670', '唐', '["毛骨貴天生，肌膚片玉明。","見人空解笑，弄物不知名。","國器嗟猶小，門風望益清。","抱來芳樹下，時引鳳雛聲。"]', '["毛骨貴天生，肌膚片玉明。","见人空解笑，弄物不知名。","国器嗟猶小，门风望益清。","抱来芳樹下，时引鳳雛声。"]', '诗', 'shi', '', NULL, '許州鄭使君孩子 護國 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ee851c9-58ad-4870-984b-2c84a58fad04', '愴故人舊居', '愴故人旧居', '14bc81cf-e502-41e2-b7d0-8e73b699f670', '唐', '["惆悵至日暮，寒鴉啼樹林。","破階苔色厚，殘壁雨痕深。","命與時不遇，福爲禍所侵。","空餘行逕在，令我歎人吟。"]', '["惆悵至日暮，寒鴉啼樹林。","破階苔色厚，殘壁雨痕深。","命與时不遇，福爲禍所侵。","空餘行逕在，令我歎人吟。"]', '诗', 'shi', '', NULL, '愴故人舊居 護國 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e1e8c15-4626-4de5-8739-8005dba3f17e', '逢靈道士', '逢靈道士', '14bc81cf-e502-41e2-b7d0-8e73b699f670', '唐', '["浮丘山上見黃冠，松栢森森登古壇。","一莖青竹以爲杖，數顆仙桃仍未餐。","長安市裏仍賣卜，武陵溪畔每燒丹。","縮地往來無定所，花源到處路漫漫。"]', '["浮丘山上见黄冠，松栢森森登古壇。","一莖青竹以爲杖，數顆仙桃仍未餐。","长安市裏仍賣卜，武陵溪畔每燒丹。","縮地往来無定所，花源到处路漫漫。"]', '诗', 'shi', '', NULL, '逢靈道士 護國 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('29ef36ed-0890-4fd2-b73b-08339655a268', '別盛安', '別盛安', '14bc81cf-e502-41e2-b7d0-8e73b699f670', '唐', '["情人取次幾淹留，別後南州與北州。","月色爲憐今夜客，砧聲那似去年秋。","欲除豺虎論三略，莫對雲山詠四愁。","親故相逢且借問，古來無種是王侯。"]', '["情人取次幾淹留，別後南州與北州。","月色爲怜今夜客，砧声那似去年秋。","欲除豺虎論三略，莫对云山詠四愁。","親故相逢且借问，古来無種是王侯。"]', '诗', 'shi', '', NULL, '別盛安 護國 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a227f318-8a89-4199-aa8d-4e01e98aae78', '傷蔡處士', '傷蔡处士', '14bc81cf-e502-41e2-b7d0-8e73b699f670', '唐', '["篋中遺草是琅玕，對此空令灑淚看。","三徑尚餘行跡在，數螢猶是映書殘。","晨光不借泉門曉，暝色唯添隴樹寒。","欲問皇天天更遠，有才無命說應難。"]', '["篋中遺草是琅玕，对此空令灑泪看。","三徑尚餘行跡在，數螢猶是映书殘。","晨光不借泉门晓，暝色唯添隴樹寒。","欲问皇天天更远，有才無命说應难。"]', '诗', 'shi', '', NULL, '傷蔡處士 護國 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5c2bb0e0-4898-4eb6-b6c6-0df522282332', '臨川道中', '臨川道中', '14bc81cf-e502-41e2-b7d0-8e73b699f670', '唐', '["出谷入谷路回轉，秋風已至歸期晚。","舉頭何處望來蹤，萬仞千山鳥飛遠。"]', '["出谷入谷路回轉，秋风已至归期晚。","舉头何处望来蹤，万仞千山鸟飞远。"]', '诗', 'shi', '', NULL, '臨川道中 護國 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fadc3151-ead3-4a78-a688-34c4e66314f9', '贈張駙馬斑竹柱杖', '贈張駙马斑竹柱杖', '14bc81cf-e502-41e2-b7d0-8e73b699f670', '唐', '["此君與我在雲溪，勁節奇文勝杖藜。","爲有歲寒堪贈遠，玉階行處願提攜。"]', '["此君與我在云溪，勁節奇文勝杖藜。","爲有歲寒堪贈远，玉階行处願提携。"]', '诗', 'shi', '', NULL, '贈張駙馬斑竹柱杖 護國 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('970a828c-5164-46af-a661-daf6adef7c9a', '病愈寄友', '病愈寄友', 'da2e4d02-9cd9-4ef9-a4d1-76a0178585e5', '唐', '["哀樂暗成疾，臥中芳月移。","西山有清士，孤嘯不可追。","擣藥晝林靜，汲泉陰澗遲。","微蹤與麋鹿，遠謝求羊知。"]', '["哀乐暗成疾，臥中芳月移。","西山有清士，孤嘯不可追。","擣藥晝林静，汲泉陰澗遲。","微蹤與麋鹿，远謝求羊知。"]', '诗', 'shi', '', NULL, '病愈寄友 法振 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('61f1c072-a1bb-4cf2-8393-6b28b2a57636', '程評事西園之作', '程評事西园之作', 'da2e4d02-9cd9-4ef9-a4d1-76a0178585e5', '唐', '["誰向春鶯道，名園已共知。","簷前迴水影，城上出花枝。","搖拂煙雲動，登臨翰墨隨。","相招能不厭，山舍爲君移。"]', '["誰向春鶯道，名园已共知。","簷前迴水影，城上出花枝。","搖拂煙云动，登臨翰墨隨。","相招能不厭，山舍爲君移。"]', '诗', 'shi', '', NULL, '程評事西園之作 法振 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('33872d17-5603-4d5f-9d69-e190efbd8f62', '陳九溪中草堂', '陳九溪中草堂', 'da2e4d02-9cd9-4ef9-a4d1-76a0178585e5', '唐', '["溪草落濺濺，魚飛入稻田。","早寒臨洞月，輕素卷簾煙。","䪻幘題新句，蓑衣象古賢。","曙花閑秀色，三十六峰前。"]', '["溪草落濺濺，鱼飞入稻田。","早寒臨洞月，轻素卷簾煙。","䪻幘題新句，蓑衣象古賢。","曙花闲秀色，三十六峰前。"]', '诗', 'shi', '', NULL, '陳九溪中草堂 法振 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c9b08e1-29cd-4037-a859-28a49f2a16b6', '題天長阮少府湖上客歸', '題天长阮少府湖上客归', 'da2e4d02-9cd9-4ef9-a4d1-76a0178585e5', '唐', '["孤櫂移官舍，新農寄楚田。","晴林渡海日，春草長湖煙。","臥對閑鷗戲，談經稚子賢。","佳期更何許，應向嘯臺前。"]', '["孤櫂移官舍，新農寄楚田。","晴林渡海日，春草长湖煙。","臥对闲鷗戲，談經稚子賢。","佳期更何許，應向嘯台前。"]', '诗', 'shi', '', NULL, '題天長阮少府湖上客歸 法振 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2dca8305-fd75-4ef3-a86c-bdceb099759d', '題萬山許鍊師', '題万山許鍊師', 'da2e4d02-9cd9-4ef9-a4d1-76a0178585e5', '唐', '["道成人不識，流水響空山。","花暗軒窓外，雲隨坐臥間。","驗圖名已久，絕粒事長閑。","更欲崑崙去，羞看絳節還。"]', '["道成人不識，流水响空山。","花暗軒窓外，云隨坐臥间。","驗圖名已久，絕粒事长闲。","更欲崑崙去，羞看絳節還。"]', '诗', 'shi', '', NULL, '題萬山許鍊師 法振 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0d5f8fe5-e5d2-49bf-839a-9dba06c8a431', '河源破賊後贈袁將軍', '河源破賊後贈袁將軍', 'da2e4d02-9cd9-4ef9-a4d1-76a0178585e5', '唐', '["白羽三千駐，蕭蕭萬里行。","出關深漢壘，帶月破蕃營。","蔓草河原色，悲笳碎葉聲。","欲朝王母殿，前路駐高旌。"]', '["白羽三千駐，蕭蕭万里行。","出关深漢壘，带月破蕃營。","蔓草河原色，悲笳碎葉声。","欲朝王母殿，前路駐高旌。"]', '诗', 'shi', '', NULL, '河源破賊後贈袁將軍 法振 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3c1e1520-c4ea-4c7c-a4e8-a2db3113bfcd', '越中贈程先生', '越中贈程先生', 'da2e4d02-9cd9-4ef9-a4d1-76a0178585e5', '唐', '["紗帽度殘春，虛舟寄一身。","溪邊逢越女，花裏問秦人。","古塞連山靜，陰霞落海新。","有時城郭去，暗與酒家親。"]', '["紗帽度殘春，虛舟寄一身。","溪邊逢越女，花裏问秦人。","古塞連山静，陰霞落海新。","有时城郭去，暗與酒家親。"]', '诗', 'shi', '', NULL, '越中贈程先生 法振 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('58ab86f4-dbb9-4dc2-ae00-4d49233dd83c', '送常大夫赴朔方', '送常大夫赴朔方', 'da2e4d02-9cd9-4ef9-a4d1-76a0178585e5', '唐', '["關山今不掩，軍候鳥先知。","大漢嫖姚入，烏孫部曲隨。","高旌天外駐，寒角月中吹。","歸到長安第，花應再滿枝。"]', '["关山今不掩，軍候鸟先知。","大漢嫖姚入，烏孫部曲隨。","高旌天外駐，寒角月中吹。","归到长安第，花應再满枝。"]', '诗', 'shi', '', NULL, '送常大夫赴朔方 法振 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a313f472-a62c-45df-90cc-d4f0fa508732', '送人遊閩越', '送人游閩越', 'da2e4d02-9cd9-4ef9-a4d1-76a0178585e5', '唐', '["不須行借問，爲爾話閩中。","海島陰晴日，江帆來去風。","道游玄度宅，身寄朗陵公。","此別何傷遠，如今關塞通。"]', '["不須行借问，爲爾話閩中。","海島陰晴日，江帆来去风。","道游玄度宅，身寄朗陵公。","此別何傷远，如今关塞通。"]', '诗', 'shi', '', NULL, '送人遊閩越 法振 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('12b1b340-0cb9-4ddb-b1e5-b7758e47ca29', '送褚先生海上尋封鍊師', '送褚先生海上尋封鍊師', 'da2e4d02-9cd9-4ef9-a4d1-76a0178585e5', '唐', '["潮落風初定，天吳避客舟。","近承三殿旨，欲向五湖游。","不厭烏皮几，新縫鶴氅裘。","明珠漂斷岸，陰火映中流。","華蓋芝童引，神丹桂女收。","懸知居縹緲，因爲識浮丘。"]', '["潮落风初定，天吳避客舟。","近承三殿旨，欲向五湖游。","不厭烏皮几，新縫鹤氅裘。","明珠漂斷岸，陰火映中流。","华蓋芝童引，神丹桂女收。","懸知居縹緲，因爲識浮丘。"]', '诗', 'shi', '', NULL, '送褚先生海上尋封鍊師 法振 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('96c807aa-8284-4bff-995d-e53848d30ee4', '送韓侍御自使幕巡海北', '送韓侍御自使幕巡海北', 'da2e4d02-9cd9-4ef9-a4d1-76a0178585e5', '唐', '["微雨空山夜洗兵，繡衣朝拂海雲清。","幕中運策心應苦，馬上吟詩卷已成。","離亭不惜花源醉，古道猶看蔓草生。","因說元戎能破敵，高歌一曲隴關情。"]', '["微雨空山夜洗兵，繡衣朝拂海云清。","幕中運策心應苦，马上吟诗卷已成。","離亭不惜花源醉，古道猶看蔓草生。","因说元戎能破敵，高歌一曲隴关情。"]', '诗', 'shi', '', NULL, '送韓侍御自使幕巡海北 法振 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a36ddea5-8195-42d5-a684-16a9b01ced63', '張舍人南谿別業', '張舍人南谿別業', 'da2e4d02-9cd9-4ef9-a4d1-76a0178585e5', '唐', '["新田繞屋半春耕，藜杖閑門引客行。","山翠自成微雨色，谿花不隱亂泉聲。","漁家遠到堪留興，公府懸知欲厭名。","入夜更宜明月滿，雙童喚出解吹笙。"]', '["新田繞屋半春耕，藜杖闲门引客行。","山翠自成微雨色，谿花不隐亂泉声。","漁家远到堪留兴，公府懸知欲厭名。","入夜更宜明月满，雙童喚出解吹笙。"]', '诗', 'shi', '', NULL, '張舍人南谿別業 法振 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3a040e1c-e431-499e-a0d3-f2375f744ef4', '別盧使君歸故柵村', '別盧使君归故柵村', 'da2e4d02-9cd9-4ef9-a4d1-76a0178585e5', '唐', '["歸風白馬引嘶聲，落日猶看楚客情。","塞口竹緣空戍沒，潮頭沙擁慢岡成。","松田且欲親耕種，郡守何偏問姓名。","東道宿程投故柵，依依漁父解相迎。"]', '["归风白马引嘶声，落日猶看楚客情。","塞口竹緣空戍沒，潮头沙擁慢岡成。","松田且欲親耕種，郡守何偏问姓名。","东道宿程投故柵，依依漁父解相迎。"]', '诗', 'shi', '', NULL, '別盧使君歸故柵村 法振 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('36b5947b-2140-4c62-9dce-33b00e0eb4c8', '丹陽浦送客之海上', '丹陽浦送客之海上', 'da2e4d02-9cd9-4ef9-a4d1-76a0178585e5', '唐', '["不到終南向幾秋，移居更欲近滄洲。","風吹雨色連村暗，潮擁菱花出岸浮。","漠漠望中春自豔，寥寥泊處夜堪愁。","如君豈得空高枕，只益天書遣遠求。"]', '["不到終南向幾秋，移居更欲近滄洲。","风吹雨色連村暗，潮擁菱花出岸浮。","漠漠望中春自豔，寥寥泊处夜堪愁。","如君豈得空高枕，只益天书遣远求。"]', '诗', 'shi', '', NULL, '丹陽浦送客之海上 法振 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a363d7df-7ac4-4a52-a920-b8839410ca1b', '月夜泛舟', '月夜泛舟', 'da2e4d02-9cd9-4ef9-a4d1-76a0178585e5', '唐', '["西塞長雲盡，南湖片月斜。","漾舟人不見，臥入武陵花。"]', '["西塞长云尽，南湖片月斜。","漾舟人不见，臥入武陵花。"]', '诗', 'shi', '', NULL, '月夜泛舟 法振 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2fb4c0b8-9e27-4faf-b223-2cb218feb6cc', '送友人之上都', '送友人之上都', 'da2e4d02-9cd9-4ef9-a4d1-76a0178585e5', '唐', '["玉帛徵賢楚客稀，猨啼相送武陵歸。","湖頭望入桃花去，一片春帆帶雨飛。"]', '["玉帛徵賢楚客稀，猨啼相送武陵归。","湖头望入桃花去，一片春帆带雨飞。"]', '诗', 'shi', '', NULL, '送友人之上都 法振 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e6cf796d-47d6-443e-bbe3-4f2422ab0744', '句', '句', 'da2e4d02-9cd9-4ef9-a4d1-76a0178585e5', '唐', '["畫鼓催來錦臂襄，小娥雙起整霓裳。"]', '["畫鼓催来錦臂襄，小娥雙起整霓裳。"]', '诗', 'shi', '', NULL, '句 法振 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5d47e8be-e0ba-4942-b6a1-e1684e3f39d6', '早發陝州途中贈嚴祕書', '早發陝州途中贈嚴祕书', '9f12d2ef-93ce-4209-9f17-d619af50c122', '唐', '["此身雖不繫，憂道亦勞生。","萬里江湖夢，千山雨雪行。","人家依舊壘，關路閉層城。","未盡交河虜，猶屯細柳兵。","艱難嗟遠客，棲託賴深情。","貧病吾將有，精修許少卿。"]', '["此身雖不繫，憂道亦勞生。","万里江湖梦，千山雨雪行。","人家依旧壘，关路閉層城。","未尽交河虜，猶屯細柳兵。","艱难嗟远客，棲託賴深情。","貧病吾將有，精修許少卿。"]', '诗', 'shi', '', NULL, '早發陝州途中贈嚴祕書 清江 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('934fbd4a-4df4-47a7-9dc4-bc25b52b3af3', '早春書情寄河南崔少府', '早春书情寄河南崔少府', '9f12d2ef-93ce-4209-9f17-d619af50c122', '唐', '["春日春風至，陽和似不均。","病身空益老，愁鬢不知春。","宇宙成遺物，光陰促幻身。","客遊傷末路，心事向行人。","道薄猶懷土，時難欲厭貧。","微才如可寄，赤縣有鄉親。"]', '["春日春风至，陽和似不均。","病身空益老，愁鬢不知春。","宇宙成遺物，光陰促幻身。","客游傷末路，心事向行人。","道薄猶懷土，时难欲厭貧。","微才如可寄，赤縣有乡親。"]', '诗', 'shi', '', NULL, '早春書情寄河南崔少府 清江 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9dfb39b4-ae3c-4bb3-9f01-53b70ffc20cc', '春遊司直城西鸕鶿谿別業', '春游司直城西鸕鶿谿別業', '9f12d2ef-93ce-4209-9f17-d619af50c122', '唐', '["別墅軍城下，閑諠未可齊。","春深花蝶夢，曉隔柳煙鞞。","韶景浮寒水，疎楊映綠堤。","沿洄看竹色，來往聽鶯啼。","久慢持生術，多親種藥畦。","家貧知素行，心苦見清溪。","越客初投分，南枝得寄棲。","禪機空寂寞，雅趣賴招攜。","本寺重江外，遊方二室西。","裴回戀知己，日夕草萋萋。"]', '["別墅軍城下，闲諠未可齊。","春深花蝶梦，晓隔柳煙鞞。","韶景浮寒水，疎楊映綠堤。","沿洄看竹色，来往听鶯啼。","久慢持生術，多親種藥畦。","家貧知素行，心苦见清溪。","越客初投分，南枝得寄棲。","禪機空寂寞，雅趣賴招携。","本寺重江外，游方二室西。","裴回戀知己，日夕草萋萋。"]', '诗', 'shi', '', NULL, '春遊司直城西鸕鶿谿別業 清江 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a4a57aed-cd42-417f-b1b9-00e183448196', '夕次襄邑', '夕次襄邑', '9f12d2ef-93ce-4209-9f17-d619af50c122', '唐', '["何處戒吾道，經年遠路中。","客心猶向北，河水自歸東。","古戍鳴寒角，疎林振夕風。","輕舟惟載月，那與故人同。"]', '["何处戒吾道，經年远路中。","客心猶向北，河水自归东。","古戍鳴寒角，疎林振夕风。","轻舟惟載月，那與故人同。"]', '诗', 'shi', '', NULL, '夕次襄邑 清江 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('26c6bc29-5e78-4cdb-8b36-b068e89af845', '宿嚴維宅簡章八元', '宿嚴維宅簡章八元', '9f12d2ef-93ce-4209-9f17-d619af50c122', '唐', '["佳期曾不遠，甲第即南鄰。","惠愛偏相及，經過豈厭頻。","秋寒林葉動，夕霽月華新。","莫話羈棲事，平原是主人。"]', '["佳期曾不远，甲第即南鄰。","惠愛偏相及，經過豈厭頻。","秋寒林葉动，夕霽月华新。","莫話羈棲事，平原是主人。"]', '诗', 'shi', '', NULL, '宿嚴維宅簡章八元 清江 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7887d2d9-3655-45b1-a556-349d95304058', '贈淮西賈兵馬使', '贈淮西賈兵马使', '9f12d2ef-93ce-4209-9f17-d619af50c122', '唐', '["破虜功成百戰場，天書新拜漢中郎。","映門旌斾春風起，對客弦歌白日長。","階下鬬雞花乍發，營南試馬柳初黃。","由來吳楚多同調，感激逢君共異鄉。"]', '["破虜功成百戰場，天书新拜漢中郎。","映门旌斾春风起，对客弦歌白日长。","階下鬬雞花乍發，營南試马柳初黄。","由来吳楚多同調，感激逢君共異乡。"]', '诗', 'shi', '', NULL, '贈淮西賈兵馬使 清江 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1864aa5b-f2ea-4e19-8d6f-b28511dbdc4f', '送堅上人歸杭州天竺寺', '送堅上人归杭州天竺寺', '9f12d2ef-93ce-4209-9f17-d619af50c122', '唐', '["十年勞負笈，經論化中朝。","流水知鄉近，和風惜別遙。","雲山零夜雨，花岸上春潮。","歸臥南天竺，禪心更寂寥。"]', '["十年勞負笈，經論化中朝。","流水知乡近，和风惜別遙。","云山零夜雨，花岸上春潮。","归臥南天竺，禪心更寂寥。"]', '诗', 'shi', '', NULL, '送堅上人歸杭州天竺寺 清江 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f3d72feb-7141-4da9-935c-39da0b15738f', '送贊律師歸嵩山', '送贊律師归嵩山', '9f12d2ef-93ce-4209-9f17-d619af50c122', '唐', '["禪意歸心急，山深定易安。","清貧修道苦，孝友別家難。","雪路侵溪轉，花宮映嶽看。","到時瞻塔暮，松月向人寒。"]', '["禪意归心急，山深定易安。","清貧修道苦，孝友別家难。","雪路侵溪轉，花宮映嶽看。","到时瞻塔暮，松月向人寒。"]', '诗', 'shi', '', NULL, '送贊律師歸嵩山 清江 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab1108a9-1317-4fb4-bec4-2f02dbc12674', '上都酬章十八兄', '上都酬章十八兄', '9f12d2ef-93ce-4209-9f17-d619af50c122', '唐', '["每歎經年別，人生有幾年。","關河長問道，風雨獨隨緣。","寓蝶成莊夢，懷人識禰賢。","徽猷不及此，空媿白華篇。"]', '["每歎經年別，人生有幾年。","关河长问道，风雨独隨緣。","寓蝶成莊梦，懷人識禰賢。","徽猷不及此，空媿白华篇。"]', '诗', 'shi', '', NULL, '上都酬章十八兄 清江 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('366a47e4-b1df-48c2-965f-e3e6295412c6', '登樓望月寄鳳翔李少尹', '登楼望月寄鳳翔李少尹', '9f12d2ef-93ce-4209-9f17-d619af50c122', '唐', '["陌上涼風槐葉凋，夕陽秋露濕寒條。","登樓望月楚山上，月到樓南山獨遙。","心送秦人趨鳳闕，月隨陽鴈極煙霄。","軒車不重無名客，此地誰能訪寂寥。"]', '["陌上涼风槐葉凋，夕陽秋露濕寒條。","登楼望月楚山上，月到楼南山独遙。","心送秦人趨鳳闕，月隨陽鴈極煙霄。","軒车不重無名客，此地誰能訪寂寥。"]', '诗', 'shi', '', NULL, '登樓望月寄鳳翔李少尹 清江 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('85f65a5e-2acb-48ba-817d-e2741c02e04c', '湘川懷古', '湘川懷古', '9f12d2ef-93ce-4209-9f17-d619af50c122', '唐', '["瀟湘連汨羅，復對九嶷河。","浪勢屈原塚，竹聲漁父歌。","地荒征騎少，天暖浴禽多。","脉脉東流水，古今同奈何。"]', '["瀟湘連汨羅，复对九嶷河。","浪勢屈原塚，竹声漁父歌。","地荒征騎少，天暖浴禽多。","脉脉东流水，古今同奈何。"]', '诗', 'shi', '', NULL, '湘川懷古 清江 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4c6782e2-c072-4db5-926d-cd2a40009e7b', '七夕', '七夕', '9f12d2ef-93ce-4209-9f17-d619af50c122', '唐', '["七夕景迢迢，相逢只一宵。","月爲開帳燭，雲作渡河橋。","映水金冠動，當風玉珮搖。","惟愁更漏促，離別在明朝。"]', '["七夕景迢迢，相逢只一宵。","月爲开帳燭，云作渡河橋。","映水金冠动，當风玉珮搖。","惟愁更漏促，離別在明朝。"]', '诗', 'shi', '', NULL, '七夕 清江 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eca40cb9-f19d-4bee-919e-010293f506e5', '長安臥病', '长安臥病', '9f12d2ef-93ce-4209-9f17-d619af50c122', '唐', '["身世足堪悲，空房臥病時。","卷簾花雨滴，掃石竹陰移。","已覺生如夢，堪嗟壽不知。","未能通法性，詎可免支離。"]', '["身世足堪悲，空房臥病时。","卷簾花雨滴，掃石竹陰移。","已覺生如梦，堪嗟壽不知。","未能通法性，詎可免支離。"]', '诗', 'shi', '', NULL, '長安臥病 清江 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a1624979-ef20-428f-9a71-4932ac6d22b8', '送婆羅門', '送婆羅门', '9f12d2ef-93ce-4209-9f17-d619af50c122', '唐', '["雪嶺金河獨向東，吳山楚澤意無窮。","如今白首鄉心盡，萬里歸程在夢中。"]', '["雪嶺金河独向东，吳山楚澤意無窮。","如今白首乡心尽，万里归程在梦中。"]', '诗', 'shi', '', NULL, '送婆羅門 清江 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('882c5540-ae02-437a-b50f-ce6f18bb703f', '喜皇甫大夫同宿大梁驛', '喜皇甫大夫同宿大梁驛', '9f12d2ef-93ce-4209-9f17-d619af50c122', '唐', '["江頭旌斾去，花外卷簾空。","夜色臨城月，春聲渡水風。","也知行李別，蹔喜話言同。","若問廬山事，終身愧遠公。"]', '["江头旌斾去，花外卷簾空。","夜色臨城月，春声渡水风。","也知行李別，蹔喜話言同。","若问廬山事，終身愧远公。"]', '诗', 'shi', '', NULL, '喜皇甫大夫同宿大梁驛 清江 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f7f4a4fe-6bef-4cf0-aa48-5c8534a8b344', '酬姚補闕南仲雲溪館中戲題隨書見寄', '酬姚補闕南仲云溪館中戲題隨书见寄', '9f12d2ef-93ce-4209-9f17-d619af50c122', '唐', '["寺溪臨使府，風景借仁祠。","補衮周官貴，能名漢主慈。","臥雲知獨處，望月憶同時。","忽枉緘中贈，瓊瑤滿手持。"]', '["寺溪臨使府，风景借仁祠。","補衮周官貴，能名漢主慈。","臥云知独处，望月憶同时。","忽枉緘中贈，瓊瑤满手持。"]', '诗', 'shi', '', NULL, '酬姚補闕南仲雲溪館中戲題隨書見寄 清江 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f21e1426-ed83-4fe3-af8b-3195630a708d', '喜嚴侍御蜀還贈嚴祕書', '喜嚴侍御蜀還贈嚴祕书', '9f12d2ef-93ce-4209-9f17-d619af50c122', '唐', '["往年分首出咸秦，木落花開秋又春。","江客不曾知蜀路，旅魂何處訪情人。","當時望月思文友，今日迎驄見近臣。","多羨二龍同漢代，繡衣芸閣共榮親。"]', '["往年分首出咸秦，木落花开秋又春。","江客不曾知蜀路，旅魂何处訪情人。","當时望月思文友，今日迎驄见近臣。","多羨二龙同漢代，繡衣芸閣共榮親。"]', '诗', 'shi', '', NULL, '喜嚴侍御蜀還贈嚴祕書 清江 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b3737b9a-376f-4a0e-a852-6389802ceca9', '送韋參軍江陵', '送韋參軍江陵', '9f12d2ef-93ce-4209-9f17-d619af50c122', '唐', '["槐花落盡柳陰清，蕭索涼天楚客情。","海上舊山無的信，東門歸路不堪行。","身隨幻境勞多事，跡學禪心厭有名。","公子道存知不棄，欲依劉表住南荆。"]', '["槐花落尽柳陰清，蕭索涼天楚客情。","海上旧山無的信，东门归路不堪行。","身隨幻境勞多事，跡学禪心厭有名。","公子道存知不棄，欲依劉表住南荆。"]', '诗', 'shi', '', NULL, '送韋參軍江陵 清江 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b5485622-5ffb-4f27-98cd-f89ca13d82f1', '月夜有懷黃端公兼簡朱孫二判官', '月夜有懷黄端公兼簡朱孫二判官', '9f12d2ef-93ce-4209-9f17-d619af50c122', '唐', '["月照疎林驚鵲飛，羈人此夜共無依。","青門旅寓身空老，白首頭陀力漸微。","屢向曲池陪逸少，幾回戎幕接玄暉。","四科弟子稱文學，五馬諸侯是繡衣。","江雁往來曾不定，野雲搖曳本無機。","修行未盡身將盡，欲向東山掩舊扉。"]', '["月照疎林驚鵲飞，羈人此夜共無依。","青门旅寓身空老，白首头陀力漸微。","屢向曲池陪逸少，幾回戎幕接玄暉。","四科弟子稱文学，五马諸侯是繡衣。","江雁往来曾不定，野云搖曳本無機。","修行未尽身將尽，欲向东山掩旧扉。"]', '诗', 'shi', '', NULL, '月夜有懷黃端公兼簡朱孫二判官 清江 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a2012b95-b50d-4000-a720-148e3a6323be', '精舍遇雨', '精舍遇雨', '9f12d2ef-93ce-4209-9f17-d619af50c122', '唐', '["空門寂寂淡吾身，溪雨微微洗客塵。","臥向白雲情未盡，任他黃鳥醉芳春。"]', '["空门寂寂淡吾身，溪雨微微洗客塵。","臥向白云情未尽，任他黄鸟醉芳春。"]', '诗', 'shi', '', NULL, '精舍遇雨 清江 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a279670d-cb7a-4208-b9f3-7d63da2247cd', '小雪', '小雪', '9f12d2ef-93ce-4209-9f17-d619af50c122', '唐', '["落雪臨風不厭看，更多還恐蔽林巒。","愁人正在書窗下，一片飛來一片寒。"]', '["落雪臨风不厭看，更多還恐蔽林巒。","愁人正在书窗下，一片飞来一片寒。"]', '诗', 'shi', '', NULL, '小雪 清江 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d003895f-9092-4a7f-b842-0c3a1e131254', '句', '句', '9f12d2ef-93ce-4209-9f17-d619af50c122', '唐', '["萬木無一葉，客心悲此時。"]', '["万木無一葉，客心悲此时。"]', '诗', 'shi', '', NULL, '句 清江 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('27643374-5bbd-47de-a805-f1718a214935', '送呂郎中赴滄州', '送呂郎中赴滄州', '09ae4540-719e-4aeb-800d-e2ead27742b9', '唐', '["出守滄州去，西風送斾旌。","路遙經幾郡，地盡到孤城。","拜廟千山綠，登樓遍海清。","何人共東望，日向積濤生。"]', '["出守滄州去，西风送斾旌。","路遙經幾郡，地尽到孤城。","拜廟千山綠，登楼遍海清。","何人共东望，日向積濤生。"]', '诗', 'shi', '', NULL, '送呂郎中赴滄州 無可 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ecec768-e1d4-4231-a59a-34eda00963f8', '書馬如文石門居', '书马如文石门居', '09ae4540-719e-4aeb-800d-e2ead27742b9', '唐', '["別業逸高情，暮泉喧客亭。","林迴天闕近，雨過石門青。","野果誰來拾，山禽獨臥聽。","要迎文會友，時復掃柴扃。"]', '["別業逸高情，暮泉喧客亭。","林迴天闕近，雨過石门青。","野果誰来拾，山禽独臥听。","要迎文會友，时复掃柴扃。"]', '诗', 'shi', '', NULL, '書馬如文石門居 無可 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f8687f09-0ec3-4c94-a2f3-7118449ba8ff', '送章正字秩滿東歸', '送章正字秩满东归', '09ae4540-719e-4aeb-800d-e2ead27742b9', '唐', '["朝衣登別席，春色滿秦關。","芸閣吏誰替，海門身又還。","尋僧流水僻，見月遠林閑。","雖是忘機者，難齊去住間。"]', '["朝衣登別席，春色满秦关。","芸閣吏誰替，海门身又還。","尋僧流水僻，见月远林闲。","雖是忘機者，难齊去住间。"]', '诗', 'shi', '', NULL, '送章正字秩滿東歸 無可 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('00cedd54-c856-4eab-b0f3-e6be6dcddfb4', '賦得望遠山送客歸', '賦得望远山送客归', '09ae4540-719e-4aeb-800d-e2ead27742b9', '唐', '["遙山寒雨過，正向暮天橫。","隱隱凌雲出，蒼蒼與水平。","何時凝厚地，幾處映孤城。","歸客秋風裏，迴看傷別情。"]', '["遙山寒雨過，正向暮天橫。","隐隐凌云出，蒼蒼與水平。","何时凝厚地，幾处映孤城。","归客秋风裏，迴看傷別情。"]', '诗', 'shi', '', NULL, '賦得望遠山送客歸 無可 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ee890bde-8ee6-40b5-b127-1692d7e4f6d5', '送宜春裴宰是將軍旻之孫', '送宜春裴宰是將軍旻之孫', '09ae4540-719e-4aeb-800d-e2ead27742b9', '唐', '["垂白方爲縣，徒知大父雄。","山春南去棹，楚夜北飛鴻。","疊嶂和雲滅，孤城與嶺通。","誰知持惠花，一境動清風。"]', '["垂白方爲縣，徒知大父雄。","山春南去棹，楚夜北飞鴻。","叠嶂和云滅，孤城與嶺通。","誰知持惠花，一境动清风。"]', '诗', 'shi', '', NULL, '送宜春裴宰是將軍旻之孫 無可 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b9aa147e-5a46-46ce-8bdb-c568d055b95f', '送朴山人歸日本', '送朴山人归日本', '09ae4540-719e-4aeb-800d-e2ead27742b9', '唐', '["海霽晚帆開，應無鄉信催。","水從荒外積，人指日邊迴。","望國乘風久，浮天絕島來。","儻因華夏使，書札轉悠哉。"]', '["海霽晚帆开，應無乡信催。","水從荒外積，人指日邊迴。","望国乘风久，浮天絕島来。","儻因华夏使，书札轉悠哉。"]', '诗', 'shi', '', NULL, '送朴山人歸日本 無可 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('80ae35ac-4792-4fed-a111-32e95d4fb546', '送姚宰任吉州安福縣', '送姚宰任吉州安福縣', '09ae4540-719e-4aeb-800d-e2ead27742b9', '唐', '["落絮滿衣裳，攜琴問酒鄉。","挂帆南入楚，到縣半浮湘。","吏散翠禽下，庭閑斑竹長。","人安宜遠泛，沙上蕙蘭香。"]', '["落絮满衣裳，携琴问酒乡。","挂帆南入楚，到縣半浮湘。","吏散翠禽下，庭闲斑竹长。","人安宜远泛，沙上蕙蘭香。"]', '诗', 'shi', '', NULL, '送姚宰任吉州安福縣 無可 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7ae6f4f3-3a61-44c4-b61b-20ab85d9b44a', '送李少府之任臨邛', '送李少府之任臨邛', '09ae4540-719e-4aeb-800d-e2ead27742b9', '唐', '["邛南方作尉，調補一何卑。","發論唯公幹，承家乃帝枝。","山長風褭棧，江蔭石和澌。","舊井王孫宅，還尋獨有期。"]', '["邛南方作尉，調補一何卑。","發論唯公幹，承家乃帝枝。","山长风褭棧，江蔭石和澌。","旧井王孫宅，還尋独有期。"]', '诗', 'shi', '', NULL, '送李少府之任臨邛 無可 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('599dccb6-9f23-4eaa-b657-e1d27f18bc35', '遊山寺', '游山寺', '09ae4540-719e-4aeb-800d-e2ead27742b9', '唐', '["千峰路盤盡，林寺昔何名。","步步入山影，房房聞水聲。","多年人跡斷，殘照石陰清。","自可求居止，安閑過此生。"]', '["千峰路盤尽，林寺昔何名。","步步入山影，房房闻水声。","多年人跡斷，殘照石陰清。","自可求居止，安闲過此生。"]', '诗', 'shi', '', NULL, '遊山寺 無可 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9ae48cba-4fe7-4a9e-9ec7-b183b3f26ebf', '酬姚員外見過林下', '酬姚員外见過林下', '09ae4540-719e-4aeb-800d-e2ead27742b9', '唐', '["掃苔迎五馬，蒔藥過申鐘。","鶴共林僧見，雲隨野客逢。","入樓山隔水，滴斾露垂松。","日暮題詩去，空知雅調重。"]', '["掃苔迎五马，蒔藥過申鐘。","鹤共林僧见，云隨野客逢。","入楼山隔水，滴斾露垂松。","日暮題诗去，空知雅調重。"]', '诗', 'shi', '', NULL, '酬姚員外見過林下 無可 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2613c223-087f-4e53-a9b1-233825d60cdd', '寄華州馬戴', '寄华州马戴', '09ae4540-719e-4aeb-800d-e2ead27742b9', '唐', '["三峰待秋上，鳥外挂衣巾。","猶見無窮景，應非暫往身。","水寒仙掌路，山遠華陽人。","欲問壇邊月，尋思闕復新。"]', '["三峰待秋上，鸟外挂衣巾。","猶见無窮景，應非暫往身。","水寒仙掌路，山远华陽人。","欲问壇邊月，尋思闕复新。"]', '诗', 'shi', '', NULL, '寄華州馬戴 無可 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3ea092bf-b5e6-4a61-b64a-14f509ea81a1', '秋夜寄青龍寺空貞二上人', '秋夜寄青龙寺空貞二上人', '09ae4540-719e-4aeb-800d-e2ead27742b9', '唐', '["夜來思道侶，木葉向人飄。","精舍池邊古，秋山樹下遙。","磬寒徹幾里，雲白已經宵。","未得同居止，蕭然自寂寥。"]', '["夜来思道侶，木葉向人飄。","精舍池邊古，秋山樹下遙。","磬寒徹幾里，云白已經宵。","未得同居止，蕭然自寂寥。"]', '诗', 'shi', '', NULL, '秋夜寄青龍寺空貞二上人 無可 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab0597d1-78d6-49f3-a6ea-72c400e4203a', '過杏溪寺寄姚員外', '過杏溪寺寄姚員外', '09ae4540-719e-4aeb-800d-e2ead27742b9', '唐', '["門徑衆峰頭，盤巖復轉溝。","雲僧隨樹老，杏水落江流。","峽狖有時到，秦人今日遊。","謝公多晚眺，此景在南樓。"]', '["门徑衆峰头，盤巖复轉溝。","云僧隨樹老，杏水落江流。","峽狖有时到，秦人今日游。","謝公多晚眺，此景在南楼。"]', '诗', 'shi', '', NULL, '過杏溪寺寄姚員外 無可 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('93363b37-54c5-4331-aec4-9788f3eecce5', '送僧歸中條', '送僧归中條', '09ae4540-719e-4aeb-800d-e2ead27742b9', '唐', '["夜葉動飄飄，寒來話數宵。","卷經歸鳥外，轉雪過山椒。","舊長松杉大，難行水石遙。","元戎宗內學，應就白雲招。"]', '["夜葉动飄飄，寒来話數宵。","卷經归鸟外，轉雪過山椒。","旧长松杉大，难行水石遙。","元戎宗內学，應就白云招。"]', '诗', 'shi', '', NULL, '送僧歸中條 無可 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('66e55178-5606-407a-a758-a5708b2612df', '送人罷舉東遊', '送人罷舉东游', '09ae4540-719e-4aeb-800d-e2ead27742b9', '唐', '["東堂今已負，況此遠行難。","兼雨風聲過，連天草色乾。","鴻嘶荒壘閉，兵燒廣川寒。","若向龍門宿，懸知拭淚看。"]', '["东堂今已負，況此远行难。","兼雨风声過，連天草色乾。","鴻嘶荒壘閉，兵燒廣川寒。","若向龙门宿，懸知拭泪看。"]', '诗', 'shi', '', NULL, '送人罷舉東遊 無可 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0530cce2-a459-41a3-a9ea-db89ac122bc4', '金州冬月陪太宗遊池', '金州冬月陪太宗游池', '09ae4540-719e-4aeb-800d-e2ead27742b9', '唐', '["殘臘雪紛紛，林間起送君。","苦吟行迥野，投跡向寒雲。","絕頂晴多去，幽泉凍不聞。","唯應草堂寺，高枕脫人羣。"]', '["殘臘雪紛紛，林间起送君。","苦吟行迥野，投跡向寒云。","絕頂晴多去，幽泉凍不闻。","唯應草堂寺，高枕脫人羣。"]', '诗', 'shi', '', NULL, '金州冬月陪太宗遊池 無可 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b3a399cd-6019-4c79-81c7-ebc92bf92d4d', '寄青龍寺原上人', '寄青龙寺原上人', '09ae4540-719e-4aeb-800d-e2ead27742b9', '唐', '["斂屨入寒竹，安禪過漏聲。","高杉殘子落，深井凍痕生。","罷磬風枝動，懸燈雪屋明。","何當招我宿，乘月上方行。"]', '["斂屨入寒竹，安禪過漏声。","高杉殘子落，深井凍痕生。","罷磬风枝动，懸灯雪屋明。","何當招我宿，乘月上方行。"]', '诗', 'shi', '', NULL, '寄青龍寺原上人 無可 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cd186dc1-43b5-40f3-a888-9a75c4e95289', '秋寄從兄賈島', '秋寄從兄賈島', '09ae4540-719e-4aeb-800d-e2ead27742b9', '唐', '["暝蟲喧暮色，默思坐西林。","聽雨寒更徹，開門落葉深。","昔因京邑病，併起洞庭心。","亦是吾兄事，遲迴共至今。"]', '["暝蟲喧暮色，默思坐西林。","听雨寒更徹，开门落葉深。","昔因京邑病，併起洞庭心。","亦是吾兄事，遲迴共至今。"]', '诗', 'shi', '', NULL, '秋寄從兄賈島 無可 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e38f801e-1ab7-4b85-aa62-5ab3238deda2', '新年', '新年', '09ae4540-719e-4aeb-800d-e2ead27742b9', '唐', '["燃燈朝復夕，漸作長年身。","紫閣未歸日，青門又見春。","掩關寒過盡，開定草生新。","自有林中趣，誰驚歲去頻。"]', '["燃灯朝复夕，漸作长年身。","紫閣未归日，青门又见春。","掩关寒過尽，开定草生新。","自有林中趣，誰驚歲去頻。"]', '诗', 'shi', '', NULL, '新年 無可 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e795761d-bcdf-4ad1-a68b-b4a5cee77333', '夏日送崔秀才遊南', '夏日送崔秀才游南', '09ae4540-719e-4aeb-800d-e2ead27742b9', '唐', '["南方山水地，念子爲貧遊。","縱是逢佳景，那能緩旅愁。","夕陽行遠道，煩暑在孤舟。","莫向巴江過，猨啼促淚流。"]', '["南方山水地，念子爲貧游。","縱是逢佳景，那能緩旅愁。","夕陽行远道，煩暑在孤舟。","莫向巴江過，猨啼促泪流。"]', '诗', 'shi', '', NULL, '夏日送崔秀才遊南 無可 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d7499059-41dc-4492-a640-0e2756a1d627', '晚秋酬姚合見寄', '晚秋酬姚合见寄', '09ae4540-719e-4aeb-800d-e2ead27742b9', '唐', '["新命起高眠，江湖空浩然。","木衰猶有菊，燕去即無蟬。","分察千官內，孤懷遠嶽邊。","蕭條人外寺，暌阻又經年。"]', '["新命起高眠，江湖空浩然。","木衰猶有菊，燕去即無蟬。","分察千官內，孤懷远嶽邊。","蕭條人外寺，暌阻又經年。"]', '诗', 'shi', '', NULL, '晚秋酬姚合見寄 無可 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('16cd1399-09ed-4caa-b204-17ef7300d18d', '暮秋宿友人居', '暮秋宿友人居', '09ae4540-719e-4aeb-800d-e2ead27742b9', '唐', '["招我郊居宿，開門但苦吟。","秋眠山燒盡，暮歇竹園深。","寒浦鴻相呌，風窗月欲沈。","翻嫌坐禪石，不在此松陰。"]', '["招我郊居宿，开门但苦吟。","秋眠山燒尽，暮歇竹园深。","寒浦鴻相呌，风窗月欲沈。","翻嫌坐禪石，不在此松陰。"]', '诗', 'shi', '', NULL, '暮秋宿友人居 無可 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dc5b9550-1690-4a7a-90d7-b65b853888c0', '送李騎曹之武寧', '送李騎曹之武寧', '09ae4540-719e-4aeb-800d-e2ead27742b9', '唐', '["一歲一歸寧，涼天數騎行。","河來當塞曲，山遠與沙平。","縱獵旗風卷，聽笳帳月生。","新鴻引寒色，迴日滿京城。"]', '["一歲一归寧，涼天數騎行。","河来當塞曲，山远與沙平。","縱獵旗风卷，听笳帳月生。","新鴻引寒色，迴日满京城。"]', '诗', 'shi', '', NULL, '送李騎曹之武寧 無可 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d0c158a-37ec-457a-91d7-bec3ac504634', '秋日寄厲玄先輩', '秋日寄厲玄先輩', '09ae4540-719e-4aeb-800d-e2ead27742b9', '唐', '["楊柳起秋色，故人猶未還。","別離俱自苦，少壯豈能閑。","夜雨吟殘燭，秋城憶遠山。","何當一相見，語默此林間。"]', '["楊柳起秋色，故人猶未還。","別離俱自苦，少壯豈能闲。","夜雨吟殘燭，秋城憶远山。","何當一相见，語默此林间。"]', '诗', 'shi', '', NULL, '秋日寄厲玄先輩 無可 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5fad3912-8afd-45f4-93e2-b88f32a87d30', '冬晚與諸文士會太僕田卿宅', '冬晚與諸文士會太僕田卿宅', '09ae4540-719e-4aeb-800d-e2ead27742b9', '唐', '["從容啓華館，饌玉復燒蘭。","是歲茲旬盡，良宵幾刻殘。","風迴松竹動，人息斗牛寒。","此後思良集，須期月再圓。"]', '["從容啓华館，饌玉复燒蘭。","是歲茲旬尽，良宵幾刻殘。","风迴松竹动，人息斗牛寒。","此後思良集，須期月再圓。"]', '诗', 'shi', '', NULL, '冬晚與諸文士會太僕田卿宅 無可 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('57ea902a-21be-4363-838c-87127eb912b9', '贈詩僧', '贈诗僧', '09ae4540-719e-4aeb-800d-e2ead27742b9', '唐', '["寒山對水塘，竹葉影侵堂。","洗藥冰生岸，開門月滿牀。","病多身又老，枕倦夜兼長。","來謁吾曹者，呈詩問否臧。"]', '["寒山对水塘，竹葉影侵堂。","洗藥冰生岸，开门月满牀。","病多身又老，枕倦夜兼长。","来謁吾曹者，呈诗问否臧。"]', '诗', 'shi', '', NULL, '贈詩僧 無可 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d2df576c-77d6-4cea-a28a-fb214b0ce6ae', '寒夜過叡川師院', '寒夜過叡川師院', '09ae4540-719e-4aeb-800d-e2ead27742b9', '唐', '["長生推獻壽，法坐四朝登。","問難無[彊]敵，聲名掩古僧。","絕塵苔積地，栖竹鳥驚燈。","語默俱忘寐，殘窗半月稜。"]', '["长生推獻壽，法坐四朝登。","问难無[彊]敵，声名掩古僧。","絕塵苔積地，栖竹鸟驚灯。","語默俱忘寐，殘窗半月稜。"]', '诗', 'shi', '', NULL, '寒夜過叡川師院 無可 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e8b8103e-8d1c-4294-8073-4149d63f323c', '送顥法師往太原講兼呈李司徒', '送顥法師往太原講兼呈李司徒', '09ae4540-719e-4aeb-800d-e2ead27742b9', '唐', '["近臘辭精舍，幷州謁尚公。","路長山忽盡，塞廣雪無窮。","講席開晴壘，禪衣涉遠風。","聞經諸弟子，應滿此門中。"]', '["近臘辞精舍，幷州謁尚公。","路长山忽尽，塞廣雪無窮。","講席开晴壘，禪衣涉远风。","闻經諸弟子，應满此门中。"]', '诗', 'shi', '', NULL, '送顥法師往太原講兼呈李司徒 無可 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5e8a82b8-429e-4f18-beba-0ef50e8d3f7d', '冬日諸禪自商山禮正師真塔迴見訪', '冬日諸禪自商山禮正師真塔迴见訪', '09ae4540-719e-4aeb-800d-e2ead27742b9', '唐', '["久思今忽來，雙屨汚青苔。","拂雪從山起，過房禮塔迴。","偈留閑夜作，禪請暫時開。","欲作孤雲去，賦詩余不才。"]', '["久思今忽来，雙屨汚青苔。","拂雪從山起，過房禮塔迴。","偈留闲夜作，禪請暫时开。","欲作孤云去，賦诗余不才。"]', '诗', 'shi', '', NULL, '冬日諸禪自商山禮正師真塔迴見訪 無可 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a033d766-5bd1-4fe8-b96f-017305b28c8d', '題青龍寺縱公房', '題青龙寺縱公房', '09ae4540-719e-4aeb-800d-e2ead27742b9', '唐', '["從誰得法印，不離上方傳。","夕磬城霜下，寒房竹月圓。","煙殘衰木畔，客住積雲邊。","未隱滄洲去，時來於此禪。"]', '["從誰得法印，不離上方傳。","夕磬城霜下，寒房竹月圓。","煙殘衰木畔，客住積云邊。","未隐滄洲去，时来於此禪。"]', '诗', 'shi', '', NULL, '題青龍寺縱公房 無可 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5abdd571-5f2f-4e52-9aa3-5f7e7ebfac4d', '贈圭峰禪師', '贈圭峰禪師', '09ae4540-719e-4aeb-800d-e2ead27742b9', '唐', '["絕壑禪林底，泉分落石層。","霧交高頂草，雲隱下方燈。","朝滿傾心客，溪連學道僧。","半旬持一食，此事有誰能。"]', '["絕壑禪林底，泉分落石層。","霧交高頂草，云隐下方灯。","朝满傾心客，溪連学道僧。","半旬持一食，此事有誰能。"]', '诗', 'shi', '', NULL, '贈圭峰禪師 無可 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1fd46bb8-c1e4-44f8-a8e8-b7d642b83e36', '陪姚合遊金州南池', '陪姚合游金州南池', '09ae4540-719e-4aeb-800d-e2ead27742b9', '唐', '["柳暗清波漲，衝萍復漱苔。","張筵白鳥起，掃岸使君來。","洲島秋應沒，荷花晚盡開。","高城吹角絕，騶馭尚裴回。"]', '["柳暗清波漲，衝萍复漱苔。","張筵白鸟起，掃岸使君来。","洲島秋應沒，荷花晚尽开。","高城吹角絕，騶馭尚裴回。"]', '诗', 'shi', '', NULL, '陪姚合遊金州南池 無可 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('90bb95bd-c0b8-487d-924a-ba3729be1f61', '金州別姚合', '金州別姚合', '09ae4540-719e-4aeb-800d-e2ead27742b9', '唐', '["日日西亭上，春留到夏殘。","言之離別易，勉以道途難。","山出一千里，溪行三百灘。","松間樓裏月，秋入五陵看。"]', '["日日西亭上，春留到夏殘。","言之離別易，勉以道途难。","山出一千里，溪行三百灘。","松间楼裏月，秋入五陵看。"]', '诗', 'shi', '', NULL, '金州別姚合 無可 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a2c21e1-134f-418a-b4d4-e7b63cfe4a68', '夏日送田中丞赴蔡州', '夏日送田中丞赴蔡州', '09ae4540-719e-4aeb-800d-e2ead27742b9', '唐', '["出守汝南城，應多戀闕情。","地遙人久望，風起斾初行。","楚廟繁蟬斷，淮田細雨生。","賞心知有處，蔣宅古津平。"]', '["出守汝南城，應多戀闕情。","地遙人久望，风起斾初行。","楚廟繁蟬斷，淮田細雨生。","賞心知有处，蔣宅古津平。"]', '诗', 'shi', '', NULL, '夏日送田中丞赴蔡州 無可 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a3cd1615-4f9f-49b0-8c5d-a191318af012', '菊', '菊', '09ae4540-719e-4aeb-800d-e2ead27742b9', '唐', '["東籬搖落後，密豔被寒催。","夾雨驚新拆，經霜忽盡開。","野香盈客袖，禁蘂泛天杯。","不共春蘭竝，悠揚遠蝶來。"]', '["东籬搖落後，密豔被寒催。","夾雨驚新拆，經霜忽尽开。","野香盈客袖，禁蘂泛天杯。","不共春蘭竝，悠揚远蝶来。"]', '诗', 'shi', '', NULL, '菊 無可 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('73773614-a641-42a4-8cce-9556d4934097', '松', '松', '09ae4540-719e-4aeb-800d-e2ead27742b9', '唐', '["枝幹怪鱗皴，烟梢出澗新。","屈盤高極目，蒼翠遠驚人。","待鶴移陰過，聽風落子頻。","青青寒木外，自與九霄鄰。"]', '["枝幹怪鱗皴，烟梢出澗新。","屈盤高極目，蒼翠远驚人。","待鹤移陰過，听风落子頻。","青青寒木外，自與九霄鄰。"]', '诗', 'shi', '', NULL, '松 無可 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ae92a828-11c5-4b90-817f-ff7593ea559b', '蘭', '蘭', '09ae4540-719e-4aeb-800d-e2ead27742b9', '唐', '["蘭色結春光，氛氳掩衆芳。","過門階露葉，尋澤徑連香。","畹靜風吹亂，亭秋雨引長。","靈鈞曾采擷，紉珮掛荷裳。"]', '["蘭色結春光，氛氳掩衆芳。","過门階露葉，尋澤徑連香。","畹静风吹亂，亭秋雨引长。","靈鈞曾采擷，紉珮掛荷裳。"]', '诗', 'shi', '', NULL, '蘭 無可 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f753a071-7a97-4c0b-9e75-f3207d0672bf', '隕葉', '隕葉', '09ae4540-719e-4aeb-800d-e2ead27742b9', '唐', '["遶巷夾溪紅，蕭條逐北風。","別林遺宿鳥，浮水載鳴蟲。","石小埋初盡，枝長落未終。","帶霜書麗什，閑讀白雲中。"]', '["遶巷夾溪紅，蕭條逐北风。","別林遺宿鸟，浮水載鳴蟲。","石小埋初尽，枝长落未終。","带霜书丽什，闲读白云中。"]', '诗', 'shi', '', NULL, '隕葉 無可 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bd10ed68-78f0-47c3-b870-92ad1ede2802', '李常侍書堂', '李常侍书堂', '09ae4540-719e-4aeb-800d-e2ead27742b9', '唐', '["結構因墳籍，簷前竹未生。","塗油窗日早，閱槧幌風輕。","息架蛩驚客，垂燈雨過城。","已應窮古史，師律孰齊名。"]', '["結構因墳籍，簷前竹未生。","塗油窗日早，閱槧幌风轻。","息架蛩驚客，垂灯雨過城。","已應窮古史，師律孰齊名。"]', '诗', 'shi', '', NULL, '李常侍書堂 無可 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f0c5d0d6-752c-4537-88dd-16afdca6305d', '寄和蔡州田郎中', '寄和蔡州田郎中', '09ae4540-719e-4aeb-800d-e2ead27742b9', '唐', '["遺跡仍留蔡，幽人出漢朝。","門深荒徑在，臺迥數峰遙。","岸石欹相倚，窗松偃未凋。","尋思方一去，豈待使君招。"]', '["遺跡仍留蔡，幽人出漢朝。","门深荒徑在，台迥數峰遙。","岸石欹相倚，窗松偃未凋。","尋思方一去，豈待使君招。"]', '诗', 'shi', '', NULL, '寄和蔡州田郎中 無可 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a45c1977-b24a-4636-afdd-14fe66feac7a', '經貞女祠', '經貞女祠', '09ae4540-719e-4aeb-800d-e2ead27742b9', '唐', '["朝賽暮還祈，開唐復歷隋。","精誠山雨至，歲月廟松衰。","窺穴龍潭黑，過門鳥道危。","不同巫峽女，來往楚王祠。"]', '["朝賽暮還祈，开唐复歷隋。","精誠山雨至，歲月廟松衰。","窺穴龙潭黑，過门鸟道危。","不同巫峽女，来往楚王祠。"]', '诗', 'shi', '', NULL, '經貞女祠 無可 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('37b1bed6-dcd3-48c5-9674-f507da9c7b37', '行漢水晚次神灘阻風', '行漢水晚次神灘阻风', '09ae4540-719e-4aeb-800d-e2ead27742b9', '唐', '["驚風山半起，舟子忽停橈。","岸荻吹先亂，灘聲落更跳。","聽松今欲暮，過島或明朝。","若盡平生趣，東浮看石橋。"]', '["驚风山半起，舟子忽停橈。","岸荻吹先亂，灘声落更跳。","听松今欲暮，過島或明朝。","若尽平生趣，东浮看石橋。"]', '诗', 'shi', '', NULL, '行漢水晚次神灘阻風 無可 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ad7b2d19-b4b3-465b-9f37-0b8ef2030199', '送田中丞使西戎', '送田中丞使西戎', '09ae4540-719e-4aeb-800d-e2ead27742b9', '唐', '["朝元下赤墀，玉節使西夷。","關隴風迴首，河湟雪灑旗。","磧砂行幾月，戎帳到何時。","應盡平生志，高全大國儀。"]', '["朝元下赤墀，玉節使西夷。","关隴风迴首，河湟雪灑旗。","磧砂行幾月，戎帳到何时。","應尽平生志，高全大国儀。"]', '诗', 'shi', '', NULL, '送田中丞使西戎 無可 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('847d5d0e-ac42-42bc-b704-f596c2ae5754', '送董正字歸覲毘陵', '送董正字归覲毘陵', '09ae4540-719e-4aeb-800d-e2ead27742b9', '唐', '["暫辭讐校去，未發見新鴻。","路入江波上，人歸楚邑東。","山遙晴出樹，野極暮連空。","何以念兄弟，應思潔膳同。"]', '["暫辞讐校去，未發见新鴻。","路入江波上，人归楚邑东。","山遙晴出樹，野極暮連空。","何以念兄弟，應思潔膳同。"]', '诗', 'shi', '', NULL, '送董正字歸覲毘陵 無可 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('37909002-c9a7-4720-8123-0d4023d62cea', '送邵錫及第歸湖州', '送邵錫及第归湖州', '09ae4540-719e-4aeb-800d-e2ead27742b9', '唐', '["春關鳥罷啼，歸慶浙煙西。","郡守招延重，鄉人慕仰齊。","橘青逃暑寺，茶長隔湖溪。","乘暇知高眺，微應辨會稽。"]', '["春关鸟罷啼，归慶浙煙西。","郡守招延重，乡人慕仰齊。","橘青逃暑寺，茶长隔湖溪。","乘暇知高眺，微應辨會稽。"]', '诗', 'shi', '', NULL, '送邵錫及第歸湖州 無可 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5859de0c-22b4-4bd0-b536-b51dd99fc6b3', '送薛重中丞充太原副使', '送薛重中丞充太原副使', '09ae4540-719e-4aeb-800d-e2ead27742b9', '唐', '["中司出華省，副相晉陽行。","書答偏州啓，籌參上將營。","踏沙夜馬細，吹雨曉笳清。","正報胡塵滅，桃花汾水生。"]', '["中司出华省，副相晉陽行。","书答偏州啓，籌參上將營。","踏沙夜马細，吹雨晓笳清。","正報胡塵滅，桃花汾水生。"]', '诗', 'shi', '', NULL, '送薛重中丞充太原副使 無可 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('360ae234-18b7-4b26-baef-2062786d4610', '送靈武李侍御', '送靈武李侍御', '09ae4540-719e-4aeb-800d-e2ead27742b9', '唐', '["靈州天一涯，幕客似還家。","地得江南壤，程分磧裏砂。","禁鹽調上味，麥穗結秋花。","前席因籌畫，清吟塞日斜。"]', '["靈州天一涯，幕客似還家。","地得江南壤，程分磧裏砂。","禁鹽調上味，麦穗結秋花。","前席因籌畫，清吟塞日斜。"]', '诗', 'shi', '', NULL, '送靈武李侍御 無可 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8117787b-d81d-4685-8290-9f17702e4884', '冬夜姚侍御宅送李廓少府', '冬夜姚侍御宅送李廓少府', '09ae4540-719e-4aeb-800d-e2ead27742b9', '唐', '["王事圭峰下，將還禁漏餘。","偶歡新歲近，惜別後期疎。","雪罷見來吏，川昏聊整車。","獨吟多暇日，應寄柏臺書。"]', '["王事圭峰下，將還禁漏餘。","偶歡新歲近，惜別後期疎。","雪罷见来吏，川昏聊整车。","独吟多暇日，應寄柏台书。"]', '诗', 'shi', '', NULL, '冬夜姚侍御宅送李廓少府 無可 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('baac66a9-7ae0-4f28-b6db-1c4946013390', '送喻鳧及第歸陽羨', '送喻鳧及第归陽羨', '09ae4540-719e-4aeb-800d-e2ead27742b9', '唐', '["姓字載科名，無過子最榮。","宗中初及第，江上覲難兄。","月向波濤沒，茶連洞壑生。","石橋高思在，且爲看東坑。"]', '["姓字載科名，無過子最榮。","宗中初及第，江上覲难兄。","月向波濤沒，茶連洞壑生。","石橋高思在，且爲看东坑。"]', '诗', 'shi', '', NULL, '送喻鳧及第歸陽羨 無可 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fd80a088-f7c8-44ec-897b-2189e12ff79e', '送沅江宋明府即開府璟之孫', '送沅江宋明府即开府璟之孫', '09ae4540-719e-4aeb-800d-e2ead27742b9', '唐', '["初聞從事日，鄂渚動芳菲。","一遂鈞衡薦，今爲長吏歸。","人臨沅水望，鴈映楚山飛。","唯有傳聲政，家風重發揮。"]', '["初闻從事日，鄂渚动芳菲。","一遂鈞衡薦，今爲长吏归。","人臨沅水望，鴈映楚山飞。","唯有傳声政，家风重發揮。"]', '诗', 'shi', '', NULL, '送沅江宋明府即開府璟之孫 無可 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d4a45677-b8c3-4c8a-baf0-422e3a4cf050', '送薛秀才遊河中兼投任郎中留後', '送薛秀才游河中兼投任郎中留後', '09ae4540-719e-4aeb-800d-e2ead27742b9', '唐', '["詩古賦縱橫，令人畏後生。","駕言遊禹跡，知己在蒲城。","日射雲煙散，風吹草木榮。","孤吟臨寇境，莫問請長纓。"]', '["诗古賦縱橫，令人畏後生。","駕言游禹跡，知己在蒲城。","日射云煙散，风吹草木榮。","孤吟臨寇境，莫问請长纓。"]', '诗', 'shi', '', NULL, '送薛秀才遊河中兼投任郎中留後 無可 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c2201bb1-c41e-4c91-8696-fe91280f5c43', '寄姚諫議', '寄姚諫議', '09ae4540-719e-4aeb-800d-e2ead27742b9', '唐', '["鳴鞭靜路塵，籍籍諫垣臣。","函疏辭專密，爐香立獨親。","篋多臨水作，窗宿臥雲人。","危坐開寒紙，燈前起草頻。"]', '["鳴鞭静路塵，籍籍諫垣臣。","函疏辞專密，爐香立独親。","篋多臨水作，窗宿臥云人。","危坐开寒紙，灯前起草頻。"]', '诗', 'shi', '', NULL, '寄姚諫議 無可 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3de65749-fe62-4aa3-9107-2377893203d8', '大理正任二十和江淹擬古詩二十章寄示', '大理正任二十和江淹擬古诗二十章寄示', '09ae4540-719e-4aeb-800d-e2ead27742b9', '唐', '["不啻迴青眼，應疑似碧雲。","古風真往哲，雅道濫朝聞。","活獄威豪右，銷時賴典墳。","如何經濟意，未克致吾君。"]', '["不啻迴青眼，應疑似碧云。","古风真往哲，雅道濫朝闻。","活獄威豪右，銷时賴典墳。","如何經濟意，未克致吾君。"]', '诗', 'shi', '', NULL, '大理正任二十和江淹擬古詩二十章寄示 無可 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef632490-cfd7-44b0-8b52-23ff0d8bfd4b', '寄殿院薛侍御', '寄殿院薛侍御', '09ae4540-719e-4aeb-800d-e2ead27742b9', '唐', '["名高意本閑，浮俗自難攀。","佐蜀連錢出，朝天獬豸還。","迴翔歷清院，彈奏迥離班。","休澣通玄旨，留僧晝掩關。"]', '["名高意本闲，浮俗自难攀。","佐蜀連錢出，朝天獬豸還。","迴翔歷清院，彈奏迥離班。","休澣通玄旨，留僧晝掩关。"]', '诗', 'shi', '', NULL, '寄殿院薛侍御 無可 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('29147d93-a1a1-4396-aa11-aa0aebf19be9', '禪林寺', '禪林寺', '09ae4540-719e-4aeb-800d-e2ead27742b9', '唐', '["台山朝佛隴，勝地絕埃氛。","冷色石橋月，素光華頂雲。","遠泉和雪溜，幽磬帶松聞。","終斷游方念，爐香繼此焚。"]', '["台山朝佛隴，勝地絕埃氛。","冷色石橋月，素光华頂云。","远泉和雪溜，幽磬带松闻。","終斷游方念，爐香繼此焚。"]', '诗', 'shi', '', NULL, '禪林寺 無可 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e9c9e03c-2625-48a2-b996-802c83ca2cb1', '奉和裴舍人春日杜城舊事', '奉和裴舍人春日杜城旧事', '09ae4540-719e-4aeb-800d-e2ead27742b9', '唐', '["早晚辭綸綍，觀農下杜西。","草新池似鏡，麥暖土如泥。","鵷鷺依川宿，驊騮向野嘶。","春來詩更苦，松韻亦含淒。"]', '["早晚辞綸綍，观農下杜西。","草新池似镜，麦暖土如泥。","鵷鷺依川宿，驊騮向野嘶。","春来诗更苦，松韻亦含淒。"]', '诗', 'shi', '', NULL, '奉和裴舍人春日杜城舊事 無可 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7a992026-4e07-4311-915b-a21abd8cdc6e', '酬厲侍御秋中思歸樹石所居見寄', '酬厲侍御秋中思归樹石所居见寄', '09ae4540-719e-4aeb-800d-e2ead27742b9', '唐', '["三峰居接近，數里躡雲行。","深去通仙境，思歸厭宦名。","月從高掌出，泉向亂松鳴。","坐石眠霞侶，秋來短褐成。"]', '["三峰居接近，數里躡云行。","深去通仙境，思归厭宦名。","月從高掌出，泉向亂松鳴。","坐石眠霞侶，秋来短褐成。"]', '诗', 'shi', '', NULL, '酬厲侍御秋中思歸樹石所居見寄 無可 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('742ef325-7040-47e5-ba0a-153885ce51d3', '奉和段著作山居呈諸同志三首次本韻 一', '奉和段著作山居呈諸同志三首次本韻 一', '09ae4540-719e-4aeb-800d-e2ead27742b9', '唐', '["香花懷道侶，巾舃立雙童。","解印鴛鴻內，抽毫水石中。","履溫行燒地，衣赤動霞風。","又似朝天去，諸僧不可同。"]', '["香花懷道侶，巾舃立雙童。","解印鴛鴻內，抽毫水石中。","履溫行燒地，衣赤动霞风。","又似朝天去，諸僧不可同。"]', '诗', 'shi', '', NULL, '奉和段著作山居呈諸同志三首次本韻 一 無可 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5701b9e2-c755-47a4-873a-09165b755143', '奉和段著作山居呈諸同志三首次本韻 二', '奉和段著作山居呈諸同志三首次本韻 二', '09ae4540-719e-4aeb-800d-e2ead27742b9', '唐', '["官辭中祕府，疎放野麋齊。","偃仰青霄近，登臨白日低。","折腰窺乳竇，定足涉冰溪。","染翰揮嵐翠，僧名幾處題。"]', '["官辞中祕府，疎放野麋齊。","偃仰青霄近，登臨白日低。","折腰窺乳竇，定足涉冰溪。","染翰揮嵐翠，僧名幾处題。"]', '诗', 'shi', '', NULL, '奉和段著作山居呈諸同志三首次本韻 二 無可 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f22ed7e9-699c-4656-8776-1a3a5047221a', '奉和段著作山居呈諸同志三首次本韻 三', '奉和段著作山居呈諸同志三首次本韻 三', '09ae4540-719e-4aeb-800d-e2ead27742b9', '唐', '["蹔收丹陛跡，獨往亂山居。","入雪知人遠，眠雲覺俗虛。","足垂巖頂石，纓濯洞中渠。","只見僧酬答，新歸絕壑書。"]', '["蹔收丹陛跡，独往亂山居。","入雪知人远，眠云覺俗虛。","足垂巖頂石，纓濯洞中渠。","只见僧酬答，新归絕壑书。"]', '诗', 'shi', '', NULL, '奉和段著作山居呈諸同志三首次本韻 三 無可 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('792658ad-996a-4ac4-bef1-fd1f925410d7', '春日送麗處士歸龍山', '春日送丽处士归龙山', '09ae4540-719e-4aeb-800d-e2ead27742b9', '唐', '["愛弟直霜臺，家山羨獨迴。","出門時返顧，何日更西來。","柳亦臨關發，花應到越開。","漁舟誰伴上，依舊恣沿洄。"]', '["愛弟直霜台，家山羨独迴。","出门时返顧，何日更西来。","柳亦臨关發，花應到越开。","漁舟誰伴上，依旧恣沿洄。"]', '诗', 'shi', '', NULL, '春日送麗處士歸龍山 無可 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9877e2df-6ae2-4695-8297-6d8b6f4d4a1e', '寄興善寺崔律師', '寄兴善寺崔律師', '09ae4540-719e-4aeb-800d-e2ead27742b9', '唐', '["沐浴前朝像，深秋白髮師。","從來居此寺，未省有東池。","幽石叢圭片，孤松動雪枝。","頃曾聽道話，別起遠山思。"]', '["沐浴前朝像，深秋白髮師。","從来居此寺，未省有东池。","幽石叢圭片，孤松动雪枝。","頃曾听道話，別起远山思。"]', '诗', 'shi', '', NULL, '寄興善寺崔律師 無可 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6aacd0bf-50f6-4d12-8ea8-8600264a0f89', '送清散遊太白山', '送清散游太白山', '09ae4540-719e-4aeb-800d-e2ead27742b9', '唐', '["卷經歸太白，躡蘚別蘿龕。","若履浮雲上，須看積翠南。","倚身松入漢，瞑目月離潭。","此境堪長往，塵中事可諳。"]', '["卷經归太白，躡蘚別蘿龕。","若履浮云上，須看積翠南。","倚身松入漢，瞑目月離潭。","此境堪长往，塵中事可諳。"]', '诗', 'shi', '', NULL, '送清散遊太白山 無可 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a50d78f2-d718-48b2-899c-3d650599e235', '冬晚姚諫議宅會送元緒上人歸南山', '冬晚姚諫議宅會送元緒上人归南山', '09ae4540-719e-4aeb-800d-e2ead27742b9', '唐', '["禪客詩家見，凝寒忽告還。","分題迴諫筆，留偈在商關。","盤徑緣高雪，閑房在半山。","自知麋鹿性，亦欲離人間。"]', '["禪客诗家见，凝寒忽告還。","分題迴諫笔，留偈在商关。","盤徑緣高雪，闲房在半山。","自知麋鹿性，亦欲離人间。"]', '诗', 'shi', '', NULL, '冬晚姚諫議宅會送元緒上人歸南山 無可 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c80fac5-46e1-40f6-8599-455d65183fdc', '送契公自桂陽赴南海', '送契公自桂陽赴南海', '09ae4540-719e-4aeb-800d-e2ead27742b9', '唐', '["南行登嶺首，與俗洗煩埃。","磬罷孤舟發，禪移積瘴開。","中餐湘鳥下，朝講海人來。","莫便將經卷，炎方去不迴。"]', '["南行登嶺首，與俗洗煩埃。","磬罷孤舟發，禪移積瘴开。","中餐湘鸟下，朝講海人来。","莫便將經卷，炎方去不迴。"]', '诗', 'shi', '', NULL, '送契公自桂陽赴南海 無可 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b72efd2c-ee9c-415f-b8c7-e4c6e1fbd06f', '冬中與諸公會宿姚端公宅懷永樂殷侍御', '冬中與諸公會宿姚端公宅懷永乐殷侍御', '09ae4540-719e-4aeb-800d-e2ead27742b9', '唐', '["柱史靜開筵，所思何地偏。","故人爲縣吏，五老遠峰前。","賓榻寒侵樹，公庭夜落泉。","會當隨假務，一就白雲禪。"]', '["柱史静开筵，所思何地偏。","故人爲縣吏，五老远峰前。","賓榻寒侵樹，公庭夜落泉。","會當隨假務，一就白云禪。"]', '诗', 'shi', '', NULL, '冬中與諸公會宿姚端公宅懷永樂殷侍御 無可 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b9fcba60-5f82-4d7c-9134-8173aa472fa0', '同劉秀才宿見贈', '同劉秀才宿见贈', '09ae4540-719e-4aeb-800d-e2ead27742b9', '唐', '["浮雲流水心，只是愛山林。","共恨多年別，相逢一夜吟。","既能持苦節，勿謂少知音。","憶就西池宿，月圓松竹深。"]', '["浮云流水心，只是愛山林。","共恨多年別，相逢一夜吟。","既能持苦節，勿謂少知音。","憶就西池宿，月圓松竹深。"]', '诗', 'shi', '', NULL, '同劉秀才宿見贈 無可 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6292240b-8d8b-4c2e-93bb-01fb7f684af6', '官池上', '官池上', '09ae4540-719e-4aeb-800d-e2ead27742b9', '唐', '["迥疏城闕內，寒瀉出雲波。","岸廣山魚到，汀閑海鷺過。","泛溝侵道急，流葉入宮多。","移舸浮中沚，清宵徹曉河。"]', '["迥疏城闕內，寒瀉出云波。","岸廣山鱼到，汀闲海鷺過。","泛溝侵道急，流葉入宮多。","移舸浮中沚，清宵徹晓河。"]', '诗', 'shi', '', NULL, '官池上 無可 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1db834be-c4ca-4552-a1e8-96ef9b55a5ca', '中秋月', '中秋月', '09ae4540-719e-4aeb-800d-e2ead27742b9', '唐', '["蟾宜天地靜，三五對堦蓂。","照耀超諸夜，光芒掩衆星。","影寒池更澈，露冷樹銷青。","枉值中秋半，長乖宿洞庭。"]', '["蟾宜天地静，三五对堦蓂。","照耀超諸夜，光芒掩衆星。","影寒池更澈，露冷樹銷青。","枉值中秋半，长乖宿洞庭。"]', '诗', 'shi', '', NULL, '中秋月 無可 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d3b8c73d-f1d7-4937-a386-8a58cd42df76', '雪', '雪', '09ae4540-719e-4aeb-800d-e2ead27742b9', '唐', '["松亞竹珊珊，心知萬井歡。","山明迷舊逕，溪滿漲新瀾。","客醉瑤臺曙，兵防玉塞寒。","紅樓知有酒，誰肯學袁安。"]', '["松亞竹珊珊，心知万井歡。","山明迷旧逕，溪满漲新瀾。","客醉瑤台曙，兵防玉塞寒。","紅楼知有酒，誰肯学袁安。"]', '诗', 'shi', '', NULL, '雪 無可 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0aedb99f-597e-4c5d-9298-1ca2941a284e', '宿西嶽白石院', '宿西嶽白石院', '09ae4540-719e-4aeb-800d-e2ead27742b9', '唐', '["白石上嵌空，寒雲西復東。","瀑流懸住處，雛鶴失禪中。","岳壁松多古，壇基雪不通。","未能親近去，擁褐媿相同。"]', '["白石上嵌空，寒云西复东。","瀑流懸住处，雛鹤失禪中。","岳壁松多古，壇基雪不通。","未能親近去，擁褐媿相同。"]', '诗', 'shi', '', NULL, '宿西嶽白石院 無可 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ab64fb15-44fc-4ad7-8164-74627f1299ee', '送僧', '送僧', '09ae4540-719e-4aeb-800d-e2ead27742b9', '唐', '["四海無拘繫，行心興自濃。","百年三事衲，萬里一枝筇。","夜減當晴影，春消過雪蹤。","白雲深處去，知宿在何峰。"]', '["四海無拘繫，行心兴自濃。","百年三事衲，万里一枝筇。","夜減當晴影，春消過雪蹤。","白云深处去，知宿在何峰。"]', '诗', 'shi', '', NULL, '送僧 無可 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3e890612-c660-4adb-af77-f6515add9568', '送贊律師歸嵩山', '送贊律師归嵩山', '09ae4540-719e-4aeb-800d-e2ead27742b9', '唐', '["禪意歸心急，山深定易安。","清貧脩道苦，孝友別家難。","雪路尋溪轉，花宮映嶽看。","到時孤塔暮，松月向人寒。"]', '["禪意归心急，山深定易安。","清貧脩道苦，孝友別家难。","雪路尋溪轉，花宮映嶽看。","到时孤塔暮，松月向人寒。"]', '诗', 'shi', '', NULL, '送贊律師歸嵩山 無可 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ef597c18-00ae-470b-a44b-02c631fbff37', '春晚喜悟禪師自琉璃上方見過', '春晚喜悟禪師自琉璃上方见過', '09ae4540-719e-4aeb-800d-e2ead27742b9', '唐', '["琉璃師到城，談性外諸經。","下嶺雪霜在，近人林木清。","苔痕深草履，瀑布滴銅瓶。","樂問山中事，宵言徹曉星。"]', '["琉璃師到城，談性外諸經。","下嶺雪霜在，近人林木清。","苔痕深草履，瀑布滴銅瓶。","乐问山中事，宵言徹晓星。"]', '诗', 'shi', '', NULL, '春晚喜悟禪師自琉璃上方見過 無可 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('97e0c005-215f-49c6-abe3-6b2653145082', '秋暮與諸文士集宿姚端公所居', '秋暮與諸文士集宿姚端公所居', '09ae4540-719e-4aeb-800d-e2ead27742b9', '唐', '["宵清月復圓，共集侍臣筵。","獨寡區中學，空論樹下禪。","風多秋晚竹，雲盡夜深天。","此會東西去，堪愁又隔年。"]', '["宵清月复圓，共集侍臣筵。","独寡區中学，空論樹下禪。","风多秋晚竹，云尽夜深天。","此會东西去，堪愁又隔年。"]', '诗', 'shi', '', NULL, '秋暮與諸文士集宿姚端公所居 無可 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('23761c5d-3d9a-4609-9f6a-19d720285748', '客中聞從兄島遊蒲絳因寄', '客中闻從兄島游蒲絳因寄', '09ae4540-719e-4aeb-800d-e2ead27742b9', '唐', '["遙遙行李心，蒼野入寒深。","吟待黃河雪，眠聽絳郡砧。","差期逢缺月，訪信出空林。","何處孤燈下，只聞嘹唳禽。"]', '["遙遙行李心，蒼野入寒深。","吟待黄河雪，眠听絳郡砧。","差期逢缺月，訪信出空林。","何处孤灯下，只闻嘹唳禽。"]', '诗', 'shi', '', NULL, '客中聞從兄島遊蒲絳因寄 無可 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f7d64016-a1e2-4f3b-b16e-124ff2448863', '送李長吉之任東井', '送李长吉之任东井', '09ae4540-719e-4aeb-800d-e2ead27742b9', '唐', '["江盤棧轉虛，候吏拜行車。","家世維城後，官資宰邑初。","市饒黃犢賣，田躡白雲鉏。","萬里千山路，何因欲寄書。"]', '["江盤棧轉虛，候吏拜行车。","家世維城後，官資宰邑初。","市饒黄犢賣，田躡白云鉏。","万里千山路，何因欲寄书。"]', '诗', 'shi', '', NULL, '送李長吉之任東井 無可 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3a3e7928-8562-4c91-8b78-23055b2c7295', '宿安國簡公院', '宿安国簡公院', '09ae4540-719e-4aeb-800d-e2ead27742b9', '唐', '["雨後清涼境，因還欲不回。","井甘桐有露，竹迸地多苔。","幡映宮牆動，香從御苑來。","青龍舊經疏，寥落有誰開。"]', '["雨後清涼境，因還欲不回。","井甘桐有露，竹迸地多苔。","幡映宮牆动，香從御苑来。","青龙旧經疏，寥落有誰开。"]', '诗', 'shi', '', NULL, '宿安國簡公院 無可 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('384bf196-1ffe-447a-942e-da1b6dc8741e', '京中別崔固', '京中別崔固', '09ae4540-719e-4aeb-800d-e2ead27742b9', '唐', '["積雨晴時近，西風葉滿泉。","相逢嵩嶽客，共聽楚城蟬。","宿館橫秋島，歸帆張遠田。","別君還寂寞，不似剡中年。"]', '["積雨晴时近，西风葉满泉。","相逢嵩嶽客，共听楚城蟬。","宿館橫秋島，归帆張远田。","別君還寂寞，不似剡中年。"]', '诗', 'shi', '', NULL, '京中別崔固 無可 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5e428dfd-4a72-409c-bac6-c1d1a9a49af6', '中秋夜隴州徐常侍座中詠月', '中秋夜隴州徐常侍座中詠月', '09ae4540-719e-4aeb-800d-e2ead27742b9', '唐', '["隴城秋月滿，太守待停歌。","與鶴來松杪，開煙出海波。","氣籠星欲盡，光滿露初多。","若遣山僧說，高明不可過。"]', '["隴城秋月满，太守待停歌。","與鹤来松杪，开煙出海波。","氣籠星欲尽，光满露初多。","若遣山僧说，高明不可過。"]', '诗', 'shi', '', NULL, '中秋夜隴州徐常侍座中詠月 無可 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f662e694-8414-4068-afa9-2ee0ebe3338e', '中秋江驛示韋益', '中秋江驛示韋益', '09ae4540-719e-4aeb-800d-e2ead27742b9', '唐', '["莫惜三更坐，難銷萬里情。","同看一片月，俱在廣州城。","淚逐金波滿，魂隨夜鵲驚。","支頤鄉思斷，無語到雞鳴。"]', '["莫惜三更坐，难銷万里情。","同看一片月，俱在廣州城。","泪逐金波满，魂隨夜鵲驚。","支頤乡思斷，無語到雞鳴。"]', '诗', 'shi', '', NULL, '中秋江驛示韋益 無可 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1f7e8ca2-66a8-4c08-bbec-d0e2f7094417', '中秋臺看月', '中秋台看月', '09ae4540-719e-4aeb-800d-e2ead27742b9', '唐', '["海雨洗煙埃，月從空碧來。","水光籠草樹，練影挂樓臺。","皓耀迷鯨口，晶熒失蚌胎。","宵分凭欄望，應合見蓬萊。"]', '["海雨洗煙埃，月從空碧来。","水光籠草樹，練影挂楼台。","皓耀迷鯨口，晶熒失蚌胎。","宵分凭欄望，應合见蓬萊。"]', '诗', 'shi', '', NULL, '中秋臺看月 無可 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b55c317d-2aff-44b4-8310-024921857243', '中秋夜南樓寄友人', '中秋夜南楼寄友人', '09ae4540-719e-4aeb-800d-e2ead27742b9', '唐', '["海月出白浪，湖光射高樓。","朗吟無綠酒，賤價買清秋。","氣冷魚龍寂，輪高星漢幽。","他鄉此夜客，對酌經多愁。"]', '["海月出白浪，湖光射高楼。","朗吟無綠酒，賤價買清秋。","氣冷鱼龙寂，輪高星漢幽。","他乡此夜客，对酌經多愁。"]', '诗', 'shi', '', NULL, '中秋夜南樓寄友人 無可 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0e50281c-4c74-4af1-8b52-2eccc6e8c280', '弔從兄島', '弔從兄島', '09ae4540-719e-4aeb-800d-e2ead27742b9', '唐', '["盡日歎沉淪，孤高碣石人。","詩名從蓋代，謫宦竟終身。","蜀集重編否，巴儀薄葬新。","青門臨舊卷，欲見永無因。"]', '["尽日歎沉淪，孤高碣石人。","诗名從蓋代，謫宦竟終身。","蜀集重編否，巴儀薄葬新。","青门臨旧卷，欲见永無因。"]', '诗', 'shi', '', NULL, '弔從兄島 無可 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7e9b0466-dd5e-41c0-bbdd-a578d46a9503', '題崔駙馬林亭', '題崔駙马林亭', '09ae4540-719e-4aeb-800d-e2ead27742b9', '唐', '["宮花野藥半相和，藤蔓參差惜不科。","纖草連門留徑細，高樓出樹見山多。","洞中避暑青苔滿，池上吟詩白鳥過。","更買太湖千片石，疊成雲頂綠㠁峨。"]', '["宮花野藥半相和，藤蔓參差惜不科。","纖草連门留徑細，高楼出樹见山多。","洞中避暑青苔满，池上吟诗白鸟過。","更買太湖千片石，叠成云頂綠㠁峨。"]', '诗', 'shi', '', NULL, '題崔駙馬林亭 無可 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ad107ad-9c84-4927-832c-bb1069a3e799', '送韓校書赴江西', '送韓校书赴江西', '09ae4540-719e-4aeb-800d-e2ead27742b9', '唐', '["車馬東門別，揚帆過楚津。","花繁期到幕，雪在已離秦。","吟落江沙月，行飛驛騎塵。","猨聲孤島雨，草色五湖春。","折葦鳴風岸，遙煙起暮蘋。","鄱江連郡府，高興寄何人。"]', '["车马东门別，揚帆過楚津。","花繁期到幕，雪在已離秦。","吟落江沙月，行飞驛騎塵。","猨声孤島雨，草色五湖春。","折葦鳴风岸，遙煙起暮蘋。","鄱江連郡府，高兴寄何人。"]', '诗', 'shi', '', NULL, '送韓校書赴江西 無可 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('84f9b32b-8f70-47bc-bb74-ad0a91521b8d', '送姚中丞赴陝州', '送姚中丞赴陝州', '09ae4540-719e-4aeb-800d-e2ead27742b9', '唐', '["二陝周分地，恩除左掖臣。","門闌開幕重，槍甲下天新。","夾道行霜騎，迎風滿草人。","河流銀漢水，城賽鐵牛神。","意氣思高謝，依違許上陳。","何妨向紅斾，自與白雲親。"]', '["二陝周分地，恩除左掖臣。","门闌开幕重，槍甲下天新。","夾道行霜騎，迎风满草人。","河流銀漢水，城賽鐵牛神。","意氣思高謝，依違許上陳。","何妨向紅斾，自與白云親。"]', '诗', 'shi', '', NULL, '送姚中丞赴陝州 無可 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('104c25dc-b030-4c2b-8a7c-8e18e1d553ee', '送李使君赴瓊州兼五州招討使', '送李使君赴瓊州兼五州招討使', '09ae4540-719e-4aeb-800d-e2ead27742b9', '唐', '["分竹雄兼使，南方到海行。","臨門雙斾引，隔嶺五州迎。","猨鶴同枝宿，蘭蕉夾道生。","雲垂前騎失，山豁去帆輕。","雨霧蒸秋岸，浪濤震夜城。","政閑開迥閣，欹枕島風清。"]', '["分竹雄兼使，南方到海行。","臨门雙斾引，隔嶺五州迎。","猨鹤同枝宿，蘭蕉夾道生。","云垂前騎失，山豁去帆轻。","雨霧蒸秋岸，浪濤震夜城。","政闲开迥閣，欹枕島风清。"]', '诗', 'shi', '', NULL, '送李使君赴瓊州兼五州招討使 無可 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5982642f-9c57-4a22-9e82-75c00f9760c6', '送姚明府赴招義縣', '送姚明府赴招義縣', '09ae4540-719e-4aeb-800d-e2ead27742b9', '唐', '["濠梁古縣城，結束赴王程。","道路攜家去，波濤隔月行。","車臨芳草下，吏踏落花迎。","暮郭山遙見，春洲鳥不驚。","風煙譙國遠，桑柘楚田平。","何以書能化，長淮徹海清。"]', '["濠梁古縣城，結束赴王程。","道路携家去，波濤隔月行。","车臨芳草下，吏踏落花迎。","暮郭山遙见，春洲鸟不驚。","风煙譙国远，桑柘楚田平。","何以书能化，长淮徹海清。"]', '诗', 'shi', '', NULL, '送姚明府赴招義縣 無可 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('8dc67a62-e46e-4df3-a84d-6645ca9d4224', '送杜司馬再遊蜀中', '送杜司马再游蜀中', '09ae4540-719e-4aeb-800d-e2ead27742b9', '唐', '["爲客應非願，愁成欲別時。","還遊蜀國去，不惜杜陵期。","劍水啼猨在，關林轉棧遲。","日光低峽口，雨勢出蛾眉。","山迥逢殘角，雲開識遠夷。","勿令雙鬢髮，併向錦城衰。"]', '["爲客應非願，愁成欲別时。","還游蜀国去，不惜杜陵期。","劍水啼猨在，关林轉棧遲。","日光低峽口，雨勢出蛾眉。","山迥逢殘角，云开識远夷。","勿令雙鬢髮，併向錦城衰。"]', '诗', 'shi', '', NULL, '送杜司馬再遊蜀中 無可 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1a2ddadf-e786-4ecb-88fc-7393dd62efdb', '贈王將軍', '贈王將軍', '09ae4540-719e-4aeb-800d-e2ead27742b9', '唐', '["勳高絕少年，分衛玉階前。","雄勇明王重，溫恭執友賢。","功書唐史滿，名到虜庭偏。","劒彩浮龍影，衣香襲御煙。","搜書秋霽閣，走馬夕陽田。","急兔投深草，瞋鷹下半天。","野人盈邸第，朝客醉盤筵。","位在將軍列，官隨憲府遷。","刻心思報國，吁氣欲開邊。","選帥如公議，須知少比肩。"]', '["勳高絕少年，分衛玉階前。","雄勇明王重，溫恭執友賢。","功书唐史满，名到虜庭偏。","劒彩浮龙影，衣香襲御煙。","搜书秋霽閣，走马夕陽田。","急兔投深草，瞋鷹下半天。","野人盈邸第，朝客醉盤筵。","位在將軍列，官隨憲府遷。","刻心思報国，吁氣欲开邊。","選帥如公議，須知少比肩。"]', '诗', 'shi', '', NULL, '贈王將軍 無可 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d6680cc6-ca76-45ef-8a53-9c9970b4edd4', '寄羽林盧大夫將軍', '寄羽林盧大夫將軍', '09ae4540-719e-4aeb-800d-e2ead27742b9', '唐', '["將軍直禁闈，繡服耀金羈。","羽衛九天靜，英豪四塞知。","望雲回朔鴈，隔水射宮麋。","舊國無歸思，秋堂夢戰時。","門風荀氏敵，劒藝霍家推。","計日旌旄下，蕭蕭萬馬隨。"]', '["將軍直禁闈，繡服耀金羈。","羽衛九天静，英豪四塞知。","望云回朔鴈，隔水射宮麋。","旧国無归思，秋堂梦戰时。","门风荀氏敵，劒藝霍家推。","計日旌旄下，蕭蕭万马隨。"]', '诗', 'shi', '', NULL, '寄羽林盧大夫將軍 無可 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('af076467-cfb2-4f87-8524-111e7c9443d4', '書事寄萬年厲員外', '书事寄万年厲員外', '09ae4540-719e-4aeb-800d-e2ead27742b9', '唐', '["帝城皆劇縣，令尹美居東。","遂拜趙張下，暫離星象中。","擁歸從北闕，送上動南宮。","舉起盆中日，驅行草上風。","不驚盧犬吠，漸見夏臺空。","紫禁黃山遶，滄溟素滻通。","封疆親日月，邑里出王公。","逐盜千門啓，興祥五稼豐。","胥徒迎曉集，賦稅共秋終。","條教關天道，歌謠入聖聰。","土膏寒麥覆，人海晝塵蒙。","廨宇松連翠，朝街日散紅。","文塲新桂茂，粉署舊蘭崇。","留客把盈爵，抽毫詠早鴻。","前騶潘岳貴，故里邵平窮。","勸隱蓮峰久，期耕樹谷同。","鳧飛將去葉，劒氣尚埋豐。","何必華陰土，方垂拂拭功。"]', '["帝城皆劇縣，令尹美居东。","遂拜趙張下，暫離星象中。","擁归從北闕，送上动南宮。","舉起盆中日，驱行草上风。","不驚盧犬吠，漸见夏台空。","紫禁黄山遶，滄溟素滻通。","封疆親日月，邑里出王公。","逐盜千门啓，兴祥五稼豐。","胥徒迎晓集，賦稅共秋終。","條教关天道，歌謠入聖聰。","土膏寒麦覆，人海晝塵蒙。","廨宇松連翠，朝街日散紅。","文塲新桂茂，粉署旧蘭崇。","留客把盈爵，抽毫詠早鴻。","前騶潘岳貴，故里邵平窮。","勸隐蓮峰久，期耕樹谷同。","鳧飞將去葉，劒氣尚埋豐。","何必华陰土，方垂拂拭功。"]', '诗', 'shi', '', NULL, '書事寄萬年厲員外 無可 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('338d2e85-f87e-4b2d-8dcb-6bdc72151737', '小雪', '小雪', '09ae4540-719e-4aeb-800d-e2ead27742b9', '唐', '["片片互玲瓏，飛揚玉漏終。","乍微全滿地，漸密更無風。","集物圓方別，連雲遠近同。","作膏凝瘠土，呈瑞下深宮。","氣射重衣透，花窺小隙通。","飄秦增舊嶺，發漢攬長空。","迥冒巢松鶴，孤鳴穴島蟲。","過三知臘盡，盈尺賀年豐。","委積休聞竹，稀疎漸見鴻。","蓋沙資澶漫，灑海助沖融。","草木潛加潤，山河更益雄。","因知天地力，覆育有全功。"]', '["片片互玲瓏，飞揚玉漏終。","乍微全满地，漸密更無风。","集物圓方別，連云远近同。","作膏凝瘠土，呈瑞下深宮。","氣射重衣透，花窺小隙通。","飄秦增旧嶺，發漢攬长空。","迥冒巢松鹤，孤鳴穴島蟲。","過三知臘尽，盈尺賀年豐。","委積休闻竹，稀疎漸见鴻。","蓋沙資澶漫，灑海助沖融。","草木潛加潤，山河更益雄。","因知天地力，覆育有全功。"]', '诗', 'shi', '', NULL, '小雪 無可 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c2249df1-73be-40c8-8862-d4e20902a054', '和賓客相國詠雪詩', '和賓客相国詠雪诗', '09ae4540-719e-4aeb-800d-e2ead27742b9', '唐', '["近臘千巖白，迎春四氣催。","雲陰連海起，風急度山來。","盡日隋堤絮，經冬越嶺梅。","豔疑歌處散，輕似舞時迴。","道蘊詩傳麗，相如賦騁才。","霽添松篠媚，寒積蕙蘭猜。","暗漲宮池水，平封輦路埃。","燭龍初照耀，巢鶴乍裴回。","簷日瓊先挂，牆風粉旋摧。","五門環玉壘，雙闕封瑤臺。","綺席陵寒坐，珠簾遠曙開。","靈芝霜下秀，仙桂月中栽。","卷幌書千帙，援琴酒百杯。","垂休編太史，呈瑞表中台。","皓夜迷三徑，浮光徹九垓。","茲辰是豐歲，歌詠屬良哉。"]', '["近臘千巖白，迎春四氣催。","云陰連海起，风急度山来。","尽日隋堤絮，經冬越嶺梅。","豔疑歌处散，轻似舞时迴。","道蘊诗傳丽，相如賦騁才。","霽添松篠媚，寒積蕙蘭猜。","暗漲宮池水，平封輦路埃。","燭龙初照耀，巢鹤乍裴回。","簷日瓊先挂，牆风粉旋摧。","五门环玉壘，雙闕封瑤台。","綺席陵寒坐，珠簾远曙开。","靈芝霜下秀，仙桂月中栽。","卷幌书千帙，援琴酒百杯。","垂休編太史，呈瑞表中台。","皓夜迷三徑，浮光徹九垓。","茲辰是豐歲，歌詠屬良哉。"]', '诗', 'shi', '', NULL, '和賓客相國詠雪詩 無可 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('30534dae-0840-4636-9b31-7263ba0b418a', '中秋夜君山脚下看月', '中秋夜君山脚下看月', '09ae4540-719e-4aeb-800d-e2ead27742b9', '唐', '["洶湧吹蒼霧，朦朣吐玉盤。","雨師清滓穢，川后掃波瀾。","氣射繁星滅，光籠八表寒。","來驅雲漲晚，路上碧霄寬。","熠燿遊何在，蟾蜍食漸難。","棹飛銀電碎，林映白虹攢。","水魄連空合，霜輝壓樹乾。","夜深高不動，天下仰頭看。"]', '["洶湧吹蒼霧，朦朣吐玉盤。","雨師清滓穢，川后掃波瀾。","氣射繁星滅，光籠八表寒。","来驱云漲晚，路上碧霄寬。","熠燿游何在，蟾蜍食漸难。","棹飞銀電碎，林映白虹攢。","水魄連空合，霜輝壓樹乾。","夜深高不动，天下仰头看。"]', '诗', 'shi', '', NULL, '中秋夜君山脚下看月 無可 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bdb09d2d-c20f-4ff6-a5a5-214eae70d405', '哭張籍司業', '哭張籍司業', '09ae4540-719e-4aeb-800d-e2ead27742b9', '唐', '["先生抱衰疾，不起茂陵間。","夕臨諸孤少，荒居弔客還。","遺文禪東岳，留語葬鄉山。","多雨銘旌故，殘燈素帳閑。","樂章誰與集，壠樹即堪攀。","神理今難問，予將呌帝關。"]', '["先生抱衰疾，不起茂陵间。","夕臨諸孤少，荒居弔客還。","遺文禪东岳，留語葬乡山。","多雨銘旌故，殘灯素帳闲。","乐章誰與集，壠樹即堪攀。","神理今难问，予將呌帝关。"]', '诗', 'shi', '', NULL, '哭張籍司業 無可 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('452638c1-0384-4cc4-bf3d-9fb44c6c8845', '寄題廬山二林寺', '寄題廬山二林寺', '09ae4540-719e-4aeb-800d-e2ead27742b9', '唐', '["廬岳東南秀，香花惠遠蹤。","名齊松嶺峻，氣比沃州濃。","積岫連何處，幽崖越幾重。","雙流湓隱隱，九派棹憧憧。","山限東西寺，林交旦暮鐘。","半天傾瀑溜，數郡見鑪峰。","巖竝金繩道，潭分玉像容。","江微匡俗路，日杲晉朝松。","椶逕新苞拆，梅籬故葉壅。","嵐光生疊砌，霞焰發高墉。","窗籟虛聞狖，庭煙黑過龍。","定僧仙嶠起，逋客虎溪逢。","濩落垂楊戶，荒涼種杏封。","塔留紅舍利，池吐白芙蓉。","畫壁披雲見，禪衣對鶴縫。","喧經泉滴瀝，沒履草丰茸。","翠竇欹攀乳，苔橋側杖筇。","探奇盈夢想，搜峭滌心胸。","冥奧終難盡，登臨惜未從。","上方薇蕨滿，歸去養乖慵。"]', '["廬岳东南秀，香花惠远蹤。","名齊松嶺峻，氣比沃州濃。","積岫連何处，幽崖越幾重。","雙流湓隐隐，九派棹憧憧。","山限东西寺，林交旦暮鐘。","半天傾瀑溜，數郡见鑪峰。","巖竝金繩道，潭分玉像容。","江微匡俗路，日杲晉朝松。","椶逕新苞拆，梅籬故葉壅。","嵐光生叠砌，霞焰發高墉。","窗籟虛闻狖，庭煙黑過龙。","定僧仙嶠起，逋客虎溪逢。","濩落垂楊戶，荒涼種杏封。","塔留紅舍利，池吐白芙蓉。","畫壁披云见，禪衣对鹤縫。","喧經泉滴瀝，沒履草丰茸。","翠竇欹攀乳，苔橋側杖筇。","探奇盈梦想，搜峭滌心胸。","冥奧終难尽，登臨惜未從。","上方薇蕨满，归去養乖慵。"]', '诗', 'shi', '', NULL, '寄題廬山二林寺 無可 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9b47dded-b15a-43d4-bca8-de97a7d81f70', '御溝水', '御溝水', '09ae4540-719e-4aeb-800d-e2ead27742b9', '唐', '["鑿禁疏雲數道開，垂風岸柳拂青苔。","銀波玉沫空池去，曾歷千巖萬壑來。"]', '["鑿禁疏云數道开，垂风岸柳拂青苔。","銀波玉沫空池去，曾歷千巖万壑来。"]', '诗', 'shi', '', NULL, '御溝水 無可 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('728abe7b-c6bb-4b5f-b25f-bd97bea61e09', '中秋月彩如晝寄上南海從翁侍御', '中秋月彩如晝寄上南海從翁侍御', '09ae4540-719e-4aeb-800d-e2ead27742b9', '唐', '["海靜天高景氣殊，鯨睛失彩蚌潛珠。","不知今夜越臺上，望見瀛洲方丈無。"]', '["海静天高景氣殊，鯨睛失彩蚌潛珠。","不知今夜越台上，望见瀛洲方丈無。"]', '诗', 'shi', '', NULL, '中秋月彩如晝寄上南海從翁侍御 無可 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b8f0e764-21df-4b21-8980-96c205607d78', '奉酬于中丞使君郡齋臥病見示一首', '奉酬于中丞使君郡斋臥病见示一首', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["宿昔祖師教，了空無不可。","枯槁未死身，理心寄行坐。","仁公施春令，和風來澤我。","生成一草木，大道無負荷。","論入空王室，明月開心胸。","性起妙不染，心行寂無蹤。","若非禪中侶，君爲雷次宗。","比聞朝端名，今貽郡齋作。","真思凝瑤瑟，高情屬雲鶴。","抉得驪龍珠，光彩曜掌握。","若作詩中友，君爲謝康樂。","盤薄西山氣，貯在君子衿。","澄澹秋水影，用爲字人心。","羣物如鳧鷖，遊翺愛清深。","格居第一品，高步凌前躅。","精義究天人，四坐聽不足。","伊昔柳太守，曾賞汀洲蘋。","如何五百年，重見江南春。","公每省往事，詠歌懷昔辰。","以茲得高臥，任物化自淳。","還因訪禪隱，知有雪山人。"]', '["宿昔祖師教，了空無不可。","枯槁未死身，理心寄行坐。","仁公施春令，和风来澤我。","生成一草木，大道無負荷。","論入空王室，明月开心胸。","性起妙不染，心行寂無蹤。","若非禪中侶，君爲雷次宗。","比闻朝端名，今貽郡斋作。","真思凝瑤瑟，高情屬云鹤。","抉得驪龙珠，光彩曜掌握。","若作诗中友，君爲謝康乐。","盤薄西山氣，貯在君子衿。","澄澹秋水影，用爲字人心。","羣物如鳧鷖，游翺愛清深。","格居第一品，高步凌前躅。","精義究天人，四坐听不足。","伊昔柳太守，曾賞汀洲蘋。","如何五百年，重见江南春。","公每省往事，詠歌懷昔辰。","以茲得高臥，任物化自淳。","還因訪禪隐，知有雪山人。"]', '诗', 'shi', '', NULL, '奉酬于中丞使君郡齋臥病見示一首 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('14aa628d-c0e4-4bf2-9943-689c8a2999b8', '贈李中丞洪一首', '贈李中丞洪一首', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["深沈閫外畧，奕世當榮寄。","地裂大將封，家傳介珪瑞。","至今漳河俗，猶受仁人賜。","公初鎮惟邢，決勝無精兵。","重圍逼大敵，六月守孤城。","政用仁恕立，恩由賞罰明。","遂令麾下士，感德不顧生。","於時聞王師，諸將兵頗黷。","天子狩南漢，煙塵滿函谷。","純臣獨耿介，下士多反覆。","明公仗忠節，一言感萬夫。","物性如蒺蔾，化作春蘭敷。","見說金被爍，終期玉有瑜。","移官萬里道，君子情何如。","伊昔避事心，乃是方袍客。","頓了空王旨，仍高致君策。","安知七十年，一朝值宗伯。","言如及清風，醒然開我懷。","宴息與遊樂，不將衣褐乖。","海底取明月，鯨波不可度。","上有巨蟒吞，下有毒龍護。","一與吾師言，乃於中心悟。","咄哉冥冥子，胡爲自塵汚。"]', '["深沈閫外畧，奕世當榮寄。","地裂大將封，家傳介珪瑞。","至今漳河俗，猶受仁人賜。","公初鎮惟邢，決勝無精兵。","重圍逼大敵，六月守孤城。","政用仁恕立，恩由賞罰明。","遂令麾下士，感德不顧生。","於时闻王師，諸將兵頗黷。","天子狩南漢，煙塵满函谷。","純臣独耿介，下士多反覆。","明公仗忠節，一言感万夫。","物性如蒺蔾，化作春蘭敷。","见说金被爍，終期玉有瑜。","移官万里道，君子情何如。","伊昔避事心，乃是方袍客。","頓了空王旨，仍高致君策。","安知七十年，一朝值宗伯。","言如及清风，醒然开我懷。","宴息與游乐，不將衣褐乖。","海底取明月，鯨波不可度。","上有巨蟒吞，下有毒龙護。","一與吾師言，乃於中心悟。","咄哉冥冥子，胡爲自塵汚。"]', '诗', 'shi', '', NULL, '贈李中丞洪一首 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1e0bba31-6b98-45ef-844b-ecfba931bde8', '杼山禪居寄贈東溪吳處士馮一首', '杼山禪居寄贈东溪吳处士馮一首', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["青雲何潤澤，下有賢人隱。","路入菱湖深，跡與黃鶴近。","野風吹白芷，山月搖清軫。","詩祖吳叔庠，致君名不盡。","身當青山秀，文體多郢聲。","澄澈湘水碧，泬寥楚山青。","時人格不同，至今罕知名。","昔賢敦師友，此道君獨行。","既得廬霍趣，乃高雷遠情。","別時春風多，掃盡雪山雪。","爲君中夜起，孤坐石上月。","悠然遺塵想，邈矣達性說。","故人不在茲，幽桂惜未結。"]', '["青云何潤澤，下有賢人隐。","路入菱湖深，跡與黄鹤近。","野风吹白芷，山月搖清軫。","诗祖吳叔庠，致君名不尽。","身當青山秀，文體多郢声。","澄澈湘水碧，泬寥楚山青。","时人格不同，至今罕知名。","昔賢敦師友，此道君独行。","既得廬霍趣，乃高雷远情。","別时春风多，掃尽雪山雪。","爲君中夜起，孤坐石上月。","悠然遺塵想，邈矣達性说。","故人不在茲，幽桂惜未結。"]', '诗', 'shi', '', NULL, '杼山禪居寄贈東溪吳處士馮一首 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('76d78e8e-6424-4da6-8282-9cab52d94c96', '妙喜寺高房期靈澈上人不至重招之一首', '妙喜寺高房期靈澈上人不至重招之一首', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["晨起峰頂心，懷人望空碧。","掃雪開寺門，灑水淨僧席。","言笑形外阻，風儀想中覿。","馳心驚葉動，傾耳聞泉滴。","豈慮咆虎逢，乍疑崩湍隔。","前期或不顧，知爾隳常格。","如今誰山下，秋霖步淅瀝。","吾亦聊自得，行禪荷輕策。","松聲暢幽情，山意導遐跡。","舉目無世人，題詩足奇石。","貧山何所有，特此邀來客。"]', '["晨起峰頂心，懷人望空碧。","掃雪开寺门，灑水淨僧席。","言笑形外阻，风儀想中覿。","驰心驚葉动，傾耳闻泉滴。","豈慮咆虎逢，乍疑崩湍隔。","前期或不顧，知爾隳常格。","如今誰山下，秋霖步淅瀝。","吾亦聊自得，行禪荷轻策。","松声暢幽情，山意導遐跡。","舉目無世人，題诗足奇石。","貧山何所有，特此邀来客。"]', '诗', 'shi', '', NULL, '妙喜寺高房期靈澈上人不至重招之一首 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3fa2b1aa-7277-42f4-8610-6dc0046307b0', '奉和薛員外誼贈湯評事衡反招隱之跡兼見寄十二韻', '奉和薛員外誼贈湯評事衡反招隐之跡兼见寄十二韻', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["喜友稱高儒，曠懷美無度。","近爲東田誘，遂耽西山趣。","庭有介隱心，得無雲泉誤。","府公中司貴，頻貽咫尺素。","郡佐仙省高，亦贈瓊瑤句。","誚茲長往志，紆彼獨遊步。","禪子方外期，夢想山中路。","艱難親稼穡，晨夕苦煙霧。","曷若孟嘗門，日榮國士遇。","鏗鏘聆綺瑟，攀折邇瓊樹。","幽踐隨鹿麋，久期怨蟾兔。","情同不繫舟，有跡道所惡。"]', '["喜友稱高儒，曠懷美無度。","近爲东田誘，遂耽西山趣。","庭有介隐心，得無云泉誤。","府公中司貴，頻貽咫尺素。","郡佐仙省高，亦贈瓊瑤句。","誚茲长往志，紆彼独游步。","禪子方外期，梦想山中路。","艱难親稼穡，晨夕苦煙霧。","曷若孟嘗门，日榮国士遇。","鏗鏘聆綺瑟，攀折邇瓊樹。","幽踐隨鹿麋，久期怨蟾兔。","情同不繫舟，有跡道所惡。"]', '诗', 'shi', '', NULL, '奉和薛員外誼贈湯評事衡反招隱之跡兼見寄十二韻 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('863868eb-c356-4066-8d37-07024b992182', '荅黎士曹黎生前適越後之楚', '荅黎士曹黎生前適越後之楚', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["楚木紛如麻，高松自孤直。","願得苦寒枝，與君比顏色。","故鄉眇天末，羇旅滄江隅。","委質在忠信，苦心無變渝。","何繇表名義，贈君金轆轤。","何以美知才，投我懸黎珠。","遽爲千里別，南風思越絕。","愛君隨海鷗，倚櫂宿沙月。","不栖惡木上，肯蹈巴蛇穴。","一上蕭然峰，擬蹤幽人轍。","晨興獨西望，郢水期泝沿。","夜到洞庭月，秋經雲夢天。","黎生知吾道，此地不潸然。","欲寄楚人住，學拏漁子船。","奈何北風至，攪我窗中弦。","遊子動歸思，江蘺亦綿綿。","篋中封禪書，欲獻無由緣。","豈乏晨風翼，翻飛到日邊。"]', '["楚木紛如麻，高松自孤直。","願得苦寒枝，與君比顏色。","故乡眇天末，羇旅滄江隅。","委質在忠信，苦心無变渝。","何繇表名義，贈君金轆轤。","何以美知才，投我懸黎珠。","遽爲千里別，南风思越絕。","愛君隨海鷗，倚櫂宿沙月。","不栖惡木上，肯蹈巴蛇穴。","一上蕭然峰，擬蹤幽人轍。","晨兴独西望，郢水期泝沿。","夜到洞庭月，秋經云梦天。","黎生知吾道，此地不潸然。","欲寄楚人住，学拏漁子船。","奈何北风至，攪我窗中弦。","游子动归思，江蘺亦綿綿。","篋中封禪书，欲獻無由緣。","豈乏晨风翼，翻飞到日邊。"]', '诗', 'shi', '', NULL, '荅黎士曹黎生前適越後之楚 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('fe93054f-edf0-47ee-80ce-7b3c3ca17c79', '荅豆盧次方', '荅豆盧次方', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["吾愛道交論，爲高貴世名。","昔稱柴桑令，今聞豆盧生。","彼生清淮氣，獨鍾文中彩。","近作公讌詩，如逢何柳在。","吾用古人耳，採君四坐珍。","賢士勝朝暉，溫溫無冬春。","朝暉爍我肌，賢士清我神。","微爾與雲鵠，幽懷何由申。","別來秋風至，獨坐楚山碧。","高月當清冥，禪心正寂歷。","增波徒相駭，人遠情不隔。","有書遺瓊什，以代貂襜褕。","風教凌越絕，聲名掩吳趨。","懸璧安可酬，徙倚還踟躕。"]', '["吾愛道交論，爲高貴世名。","昔稱柴桑令，今闻豆盧生。","彼生清淮氣，独鍾文中彩。","近作公讌诗，如逢何柳在。","吾用古人耳，採君四坐珍。","賢士勝朝暉，溫溫無冬春。","朝暉爍我肌，賢士清我神。","微爾與云鵠，幽懷何由申。","別来秋风至，独坐楚山碧。","高月當清冥，禪心正寂歷。","增波徒相駭，人远情不隔。","有书遺瓊什，以代貂襜褕。","风教凌越絕，声名掩吳趨。","懸璧安可酬，徙倚還踟躕。"]', '诗', 'shi', '', NULL, '荅豆盧次方 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dd7907df-caea-403d-8ec3-a16933e56943', '荅蘇州韋應物郎中', '荅蘇州韋應物郎中', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["詩教殆淪缺，庸音互相傾。","忽觀風騷韻，會我夙昔情。","蕩漾學海資，鬱爲詩人英。","格將寒松高，氣與秋江清。","何必鄴中作，可爲千載程。","受辭分虎竹，萬里臨江城。","到日掃煩政，況今休黷兵。","應憐禪家子，林下寂無營。","跡隳世上華，心得道中精。","脫畧文字累，免爲外物攖。","書衣流埃積，硯石駮蘚生。","恨未識君子，空傳手中瓊。","安可誘我性，始願愆素誠。","爲無鸑鷟音，繼公雲和笙。","吟之向禪藪，反媿幽松聲。"]', '["诗教殆淪缺，庸音互相傾。","忽观风騷韻，會我夙昔情。","蕩漾学海資，鬱爲诗人英。","格將寒松高，氣與秋江清。","何必鄴中作，可爲千載程。","受辞分虎竹，万里臨江城。","到日掃煩政，況今休黷兵。","應怜禪家子，林下寂無營。","跡隳世上华，心得道中精。","脫畧文字累，免爲外物攖。","书衣流埃積，硯石駮蘚生。","恨未識君子，空傳手中瓊。","安可誘我性，始願愆素誠。","爲無鸑鷟音，繼公云和笙。","吟之向禪藪，反媿幽松声。"]', '诗', 'shi', '', NULL, '荅蘇州韋應物郎中 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('11c10589-06ec-4659-834d-3563b52b2426', '荅鄭方回', '荅鄭方回', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["獨禪外念入，中夜不成定。","顧我顦顇容，澤君陽春詠。","詞貞思且逸，瓊彩何暉映。","如聆雲和音，況覩聲名盛。","琴語掩爲聞，山心聲宜聽。","是時寒光澈，萬境澄以淨。","高秋日月清，中氣天地正。","遠情偶茲夕，道用增寥敻。","思君處虛空，一操不可更。","時美城北徐，家承谷口鄭。","軒車未有轍，蒿蘭且同徑。","莊生誡近名，夫子罕言命。","是以耕楚田，曠然殊獨行。","萎蕤鸞鳳彩，特達珪璋性。","通隱嘉黃綺，高儒重荀孟。","世汚我未起，道蹇吾猶病。","逸翮思冥冥，潛鱗樂游泳。","宗師許學外，恨不逢孔聖。","說詩迷頹靡，偶俗傷趨競。","此道誰共詮，因君情欲罄。"]', '["独禪外念入，中夜不成定。","顧我顦顇容，澤君陽春詠。","词貞思且逸，瓊彩何暉映。","如聆云和音，況覩声名盛。","琴語掩爲闻，山心声宜听。","是时寒光澈，万境澄以淨。","高秋日月清，中氣天地正。","远情偶茲夕，道用增寥敻。","思君处虛空，一操不可更。","时美城北徐，家承谷口鄭。","軒车未有轍，蒿蘭且同徑。","莊生誡近名，夫子罕言命。","是以耕楚田，曠然殊独行。","萎蕤鸾鳳彩，特達珪璋性。","通隐嘉黄綺，高儒重荀孟。","世汚我未起，道蹇吾猶病。","逸翮思冥冥，潛鱗乐游泳。","宗師許学外，恨不逢孔聖。","说诗迷頹靡，偶俗傷趨競。","此道誰共詮，因君情欲罄。"]', '诗', 'shi', '', NULL, '荅鄭方回 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('00db1630-ec79-4fa8-8234-54283b8cccad', '答俞校書冬夜', '答俞校书冬夜', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["夜閑禪用精，空界亦清迥。","子真仙曹吏，好我如宗炳。","一宿覿幽勝，形清煩慮屏。","新聲殊激楚，麗句同歌郢。","遺此感予懷，沈吟忘夕永。","月彩散瑤碧，示君禪中境。","真思在杳冥，浮念寄形影。","遙得四明心，何須蹈岑嶺。","詩情聊作用，空性惟寂靜。","若許林下期，看君辭簿領。"]', '["夜闲禪用精，空界亦清迥。","子真仙曹吏，好我如宗炳。","一宿覿幽勝，形清煩慮屏。","新声殊激楚，丽句同歌郢。","遺此感予懷，沈吟忘夕永。","月彩散瑤碧，示君禪中境。","真思在杳冥，浮念寄形影。","遙得四明心，何須蹈岑嶺。","诗情聊作用，空性惟寂静。","若許林下期，看君辞簿領。"]', '诗', 'shi', '', NULL, '答俞校書冬夜 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ec22288f-c16f-40fa-96b0-dc2d6fafbe4a', '妙喜寺達公禪齋寄李司直公孫房都曹德裕從事方舟顏武康士騁四十二韻', '妙喜寺達公禪斋寄李司直公孫房都曹德裕從事方舟顏武康士騁四十二韻', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["我祖傳六經，精義思朝徹。","方舟頗周覽，逸書亦備閱。","墨家傷刻薄，儒氏知優劣。","弱植庶可彫，苦心未嘗輟。","中年慕仙術，永願傳其訣。","歲駐若木景，日餐瓊禾屑。","嬋娟羨門子，斯語豈徒設。","天上生白榆，葳蕤信好折。","實可反柔顏，花堪養玄髮。","求之性分外，業棄金亦竭。","藥化成白雲，形彫辭素穴。","一聞西天旨，初禪已無熱。","涓子非我宗，然公有真訣。","却尋丘壑趣，始與纓紱別。","野飯敵膏粱，山楹代藻梲。","與君北巖侶，遊寓日常昳。","靜對春谷泉，晴披陽林雪。","境清覺神王，道勝知機滅。","詣寂長杳冥，忘歸暫采擷。","物生豈有心，麗容俟予別。","桂子何蓂苓，琪葩亦皎潔。","此木生意高，亦與衆芳列。","賞墨識屢換，省躬悟彌切。","微尚若不虧，足以全吾節。","北風吹蕙帶，蕭寥聞蜻蛚。","宿昔廬峰期，流芳已再歇。","不有清屏鑒，使我商弦絕。","願寄千里心，月高不可掇。","優游邦之直，遠矣踵前烈。","立俗忘毀譽，遇物遺巧拙。","真氣獨翛然，軒裳詎能紲。","都曹風韻整，綱紀信明決。","於交必傾寫，立行豈矜伐。","政與清渭同，分流自澄澈。","裴侯資亮直，中誠豈徒說。","古人比明義，清士願交結。","溫溫躬珪彩，終始聲不缺。","顏生炯介士，有志不可越。","仗義冒險難，持操去淄湼。","世論高二賢，賢賢繼前哲。","四子遭明盛，裒然皆秀傑。","理名雖殊跡，悟道寧異轍。","愛爾竹柏姿，爲予寒不折。"]', '["我祖傳六經，精義思朝徹。","方舟頗周覽，逸书亦備閱。","墨家傷刻薄，儒氏知優劣。","弱植庶可彫，苦心未嘗輟。","中年慕仙術，永願傳其訣。","歲駐若木景，日餐瓊禾屑。","嬋娟羨门子，斯語豈徒設。","天上生白榆，葳蕤信好折。","實可反柔顏，花堪養玄髮。","求之性分外，業棄金亦竭。","藥化成白云，形彫辞素穴。","一闻西天旨，初禪已無熱。","涓子非我宗，然公有真訣。","却尋丘壑趣，始與纓紱別。","野飯敵膏粱，山楹代藻梲。","與君北巖侶，游寓日常昳。","静对春谷泉，晴披陽林雪。","境清覺神王，道勝知機滅。","詣寂长杳冥，忘归暫采擷。","物生豈有心，丽容俟予別。","桂子何蓂苓，琪葩亦皎潔。","此木生意高，亦與衆芳列。","賞墨識屢換，省躬悟彌切。","微尚若不虧，足以全吾節。","北风吹蕙带，蕭寥闻蜻蛚。","宿昔廬峰期，流芳已再歇。","不有清屏鑒，使我商弦絕。","願寄千里心，月高不可掇。","優游邦之直，远矣踵前烈。","立俗忘毀譽，遇物遺巧拙。","真氣独翛然，軒裳詎能紲。","都曹风韻整，綱紀信明決。","於交必傾寫，立行豈矜伐。","政與清渭同，分流自澄澈。","裴侯資亮直，中誠豈徒说。","古人比明義，清士願交結。","溫溫躬珪彩，終始声不缺。","顏生炯介士，有志不可越。","仗義冒險难，持操去淄湼。","世論高二賢，賢賢繼前哲。","四子遭明盛，裒然皆秀傑。","理名雖殊跡，悟道寧異轍。","愛爾竹柏姿，爲予寒不折。"]', '诗', 'shi', '', NULL, '妙喜寺達公禪齋寄李司直公孫房都曹德裕從事方舟顏武康士騁四十二韻 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('84ad15d8-b61c-4bbf-b028-70e11b96e74f', '遙酬袁使君高春暮行縣過報德寺見懷', '遙酬袁使君高春暮行縣過報德寺见懷', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["江春行求瘼，偶與真境期。","見說三陵下，前朝開佛祠。","停舟仰麗剎，繡組發香墀。","咫尺空界色，天人花落時。","盛游限羸疾，悚踴瞻旌旗。","峰翠羨閑步，松聲入遙思。","素高淮陽理，況負東山姿。","迨此一登覽，深情見新詩。"]', '["江春行求瘼，偶與真境期。","见说三陵下，前朝开佛祠。","停舟仰丽剎，繡組發香墀。","咫尺空界色，天人花落时。","盛游限羸疾，悚踴瞻旌旗。","峰翠羨闲步，松声入遙思。","素高淮陽理，況負东山姿。","迨此一登覽，深情见新诗。"]', '诗', 'shi', '', NULL, '遙酬袁使君高春暮行縣過報德寺見懷 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7c1c148f-d4f6-4a08-bc8f-228106284683', '冬日遙和盧使君幼平綦毋居士遊法華寺高頂臨湖亭', '冬日遙和盧使君幼平綦毋居士游法华寺高頂臨湖亭', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["仁坊標絕境，廉守躡高蹤。","天曉纔分剎，風傳欲盡鐘。","城中歸路遠，湖上碧山重。","水照千花界，雲開七葉峰。","寒芳艾綬滿，空翠白綸濃。","逸韻知難繼，佳遊恨不逢。","仍聞撫禪石，爲我久從容。"]', '["仁坊標絕境，廉守躡高蹤。","天晓纔分剎，风傳欲尽鐘。","城中归路远，湖上碧山重。","水照千花界，云开七葉峰。","寒芳艾綬满，空翠白綸濃。","逸韻知难繼，佳游恨不逢。","仍闻撫禪石，爲我久從容。"]', '诗', 'shi', '', NULL, '冬日遙和盧使君幼平綦毋居士遊法華寺高頂臨湖亭 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c4ef89c2-674e-4c3c-9892-ad52c474ea35', '秋日遙和盧使君遊何山寺宿敭上人房論湼槃經義', '秋日遙和盧使君游何山寺宿敭上人房論湼槃經義', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["江郡當秋景，期將道者同。","跡高憐竹寺，夜靜賞蓮宮。","古磬清霜下，寒山曉月中。","詩情緣境發，法性寄筌空。","翻譯推南本，何人繼謝公。"]', '["江郡當秋景，期將道者同。","跡高怜竹寺，夜静賞蓮宮。","古磬清霜下，寒山晓月中。","诗情緣境發，法性寄筌空。","翻譯推南本，何人繼謝公。"]', '诗', 'shi', '', NULL, '秋日遙和盧使君遊何山寺宿敭上人房論湼槃經義 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('95de409d-5e91-4f3b-b39d-873c74579ceb', '酬秦山人系題贈', '酬秦山人系題贈', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["出齋步杉影，手自開禪扉。","花滿不汚地，雲多從觸衣。","思山石蘚淨，款客露葵肥。","果得宗居士，論心到極微。"]', '["出斋步杉影，手自开禪扉。","花满不汚地，云多從觸衣。","思山石蘚淨，款客露葵肥。","果得宗居士，論心到極微。"]', '诗', 'shi', '', NULL, '酬秦山人系題贈 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('bf099252-29af-429e-8444-28b0e9805236', '奉酬袁使君高寺院新亭對雨', '奉酬袁使君高寺院新亭对雨', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["茲亭跡素淺，勝事併隨公。","法界飄香雨，禪窗灑竹風。","浮煙披夕景，高鶴下秋空。","冥寂四山久，寧期此會同。"]', '["茲亭跡素淺，勝事併隨公。","法界飄香雨，禪窗灑竹风。","浮煙披夕景，高鹤下秋空。","冥寂四山久，寧期此會同。"]', '诗', 'shi', '', NULL, '奉酬袁使君高寺院新亭對雨 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1434b681-cc52-4fc3-a1ea-930df29e3c36', '奉酬顏使君真卿見過郭中寺寺無山水之賞故予述其意以荅焉', '奉酬顏使君真卿见過郭中寺寺無山水之賞故予述其意以荅焉', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["州西柳家寺，禪舍隱人間。","證性輕觀水，棲心不買山。","履聲知客貴，雲影悟身閑。","彥會前賢事，方今可得攀。"]', '["州西柳家寺，禪舍隐人间。","證性轻观水，棲心不買山。","履声知客貴，云影悟身闲。","彥會前賢事，方今可得攀。"]', '诗', 'shi', '', NULL, '奉酬顏使君真卿見過郭中寺寺無山水之賞故予述其意以荅焉 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e7ae1828-8451-46ef-a30c-1ee2b6b0892e', '酬烏程楊明府華雨後小亭對月見呈', '酬烏程楊明府华雨後小亭对月见呈', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["夜涼喜無訟，霽色搖閑情。","暑退不因雨，陶家風自清。","凝弦停片景，發詠靜秋聲。","何事禪中隱，詩題忽記名。"]', '["夜涼喜無訟，霽色搖闲情。","暑退不因雨，陶家风自清。","凝弦停片景，發詠静秋声。","何事禪中隐，诗題忽記名。"]', '诗', 'shi', '', NULL, '酬烏程楊明府華雨後小亭對月見呈 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b28b276e-7015-400d-a642-534e35758344', '自蘇州訪醫迴酬盧士關判官見贈', '自蘇州訪醫迴酬盧士关判官见贈', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["尋醫初疾理，忽憶故山雲。","遠訪桑公子，還依柳使君。","周旋承惠愛，佩服比蘭薰。","從事因高唱，秋風起處聞。"]', '["尋醫初疾理，忽憶故山云。","远訪桑公子，還依柳使君。","周旋承惠愛，佩服比蘭薰。","從事因高唱，秋风起处闻。"]', '诗', 'shi', '', NULL, '自蘇州訪醫迴酬盧士關判官見贈 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('90a36d5a-67b6-4084-afc0-14ef6b3befc9', '題沈道士新亭', '題沈道士新亭', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["何處好攀躋，新亭俯舊溪。","坐中千里近，簷下四山低。","小浦依林曲，迴塘遶郭西。","桃花春滿地，歸路莫相迷。"]', '["何处好攀躋，新亭俯旧溪。","坐中千里近，簷下四山低。","小浦依林曲，迴塘遶郭西。","桃花春满地，归路莫相迷。"]', '诗', 'shi', '', NULL, '題沈道士新亭 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('a9f9aeeb-77f2-4a32-9dfa-1cabef93e1aa', '送盧仲舒移家海陵', '送盧仲舒移家海陵', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["世故多離散，東西不可嗟。","小秦非本國，楚塞復移家。","海島無鄰里，鹽居少物華。","山中吟夜月，相送在天涯。"]', '["世故多離散，东西不可嗟。","小秦非本国，楚塞复移家。","海島無鄰里，鹽居少物华。","山中吟夜月，相送在天涯。"]', '诗', 'shi', '', NULL, '送盧仲舒移家海陵 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('7ff16065-3607-457f-b38a-86605468b818', '陪盧使君登樓送方巨之還京', '陪盧使君登楼送方巨之還京', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["萬里汀洲上，東樓欲別難。","春風潮水漫，正月柳條寒。","旅逸逢漁浦，清高愛鳥冠。","雲山寧不起，今日向長安。"]', '["万里汀洲上，东楼欲別难。","春风潮水漫，正月柳條寒。","旅逸逢漁浦，清高愛鸟冠。","云山寧不起，今日向长安。"]', '诗', 'shi', '', NULL, '陪盧使君登樓送方巨之還京 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('46b91254-d158-4763-9ff5-8a9d678b7ff5', '同裴錄事樓上望', '同裴錄事楼上望', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["退食高樓上，湖山向晚晴。","桐花落萬井，月影出重城。","水竹涼風起，簾幃暑氣清。","蕭蕭獨無事，因見涖人情。"]', '["退食高楼上，湖山向晚晴。","桐花落万井，月影出重城。","水竹涼风起，簾幃暑氣清。","蕭蕭独無事，因见涖人情。"]', '诗', 'shi', '', NULL, '同裴錄事樓上望 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('be5a8c29-513d-4b1a-bb04-037e10dbc296', '寓興', '寓兴', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["天下生白榆，白榆直上連天根。","高枝不知幾萬丈，世人仰望徒攀援。","誰能上天採其子，種向人間笑桃李。","因問老仙求種法，老仙咍我愚不答。","始知此道無所成，還如瞽夫學長生。"]', '["天下生白榆，白榆直上連天根。","高枝不知幾万丈，世人仰望徒攀援。","誰能上天採其子，種向人间笑桃李。","因问老仙求種法，老仙咍我愚不答。","始知此道無所成，還如瞽夫学长生。"]', '诗', 'shi', '', NULL, '寓興 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d6a5e687-73c2-46a9-9834-54af759f2f62', '寄常一上人', '寄常一上人', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["雁塞五山臨汗漫，雲州一路出青冥。","何因請住嘉祥寺，內史新修湖上亭。"]', '["雁塞五山臨汗漫，云州一路出青冥。","何因請住嘉祥寺，內史新修湖上亭。"]', '诗', 'shi', '', NULL, '寄常一上人 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('1583aebb-74a9-4e41-b852-d87700cdb8eb', '送祕上人遊京', '送祕上人游京', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["共君方異路，山伴與誰同。","日冷行人少，時清古鎮空。","煖瓶和雪水，鳴錫帶江風。","撩亂終南色，遙應入夢中。"]', '["共君方異路，山伴與誰同。","日冷行人少，时清古鎮空。","煖瓶和雪水，鳴錫带江风。","撩亂終南色，遙應入梦中。"]', '诗', 'shi', '', NULL, '送祕上人遊京 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9c49f610-d0f1-4d1b-944c-6a3141dfecec', '賦得啼猨送客', '賦得啼猨送客', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["萬里巴江外，三聲月峽深。","何年有此路，幾客共霑襟。","斷壁分垂影，流泉入苦吟。","悽涼離別後，聞此更傷心。"]', '["万里巴江外，三声月峽深。","何年有此路，幾客共霑襟。","斷壁分垂影，流泉入苦吟。","悽涼離別後，闻此更傷心。"]', '诗', 'shi', '', NULL, '賦得啼猨送客 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d9f6c9fa-2003-451e-bba8-6af25298e8be', '南樓望月', '南楼望月', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["夜月家家望，亭亭愛此樓。","纖雲溪上斷，疎柳影中秋。","漸映千峰出，遙分萬派流。","關山誰復見，應獨起邊愁。"]', '["夜月家家望，亭亭愛此楼。","纖云溪上斷，疎柳影中秋。","漸映千峰出，遙分万派流。","关山誰复见，應独起邊愁。"]', '诗', 'shi', '', NULL, '南樓望月 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('565d931a-ff49-4f37-b633-524b48c2f4f0', '尋陸鴻漸不遇', '尋陸鴻漸不遇', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["移家雖帶郭，野徑入桑麻。","近種籬邊菊，秋來未著花。","扣門無犬吠，欲去問西家。","報道山中去，歸時每日斜。"]', '["移家雖带郭，野徑入桑麻。","近種籬邊菊，秋来未著花。","扣门無犬吠，欲去问西家。","報道山中去，归时每日斜。"]', '诗', 'shi', '', NULL, '尋陸鴻漸不遇 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('376733c2-fa07-4423-b494-fca090ba1a7d', '懷舊山', '懷旧山', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["一坐西林寺，從來未下山。","不因尋長者，無事到人間。","宿雨愁爲客，寒花笑未還。","空懷舊山月，童子念經閑。"]', '["一坐西林寺，從来未下山。","不因尋长者，無事到人间。","宿雨愁爲客，寒花笑未還。","空懷旧山月，童子念經闲。"]', '诗', 'shi', '', NULL, '懷舊山 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('33e086a3-db83-407e-ac80-5775ab6cf3d7', '宿吳匡山破寺', '宿吳匡山破寺', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["雙峰百戰後，真界滿塵埃。","蔓草緣空壁，悲風起故臺。","野花寒更發，山月暝還來。","何事池中水，東流獨不迴。"]', '["雙峰百戰後，真界满塵埃。","蔓草緣空壁，悲风起故台。","野花寒更發，山月暝還来。","何事池中水，东流独不迴。"]', '诗', 'shi', '', NULL, '宿吳匡山破寺 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9cbfa6fb-822d-4eb3-a6c3-01921a9383c2', '九月十日', '九月十日', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["愛殺柴桑隱，名溪近訟庭。","掃沙開野步，搖舸出閑汀。","宿簡邀詩伴，餘花在酒瓶。","悠然南望意，自有峴山情。"]', '["愛殺柴桑隐，名溪近訟庭。","掃沙开野步，搖舸出闲汀。","宿簡邀诗伴，餘花在酒瓶。","悠然南望意，自有峴山情。"]', '诗', 'shi', '', NULL, '九月十日 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('ba29d8ca-702d-48e6-a5e7-8bccaed81eee', '秋晚宿破山寺', '秋晚宿破山寺', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["秋風落葉滿空山，古寺殘燈石壁間。","昔日經行人去盡，寒雲夜夜自飛還。"]', '["秋风落葉满空山，古寺殘灯石壁间。","昔日經行人去尽，寒云夜夜自飞還。"]', '诗', 'shi', '', NULL, '秋晚宿破山寺 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('314751bd-00d3-4388-ad5e-c4430f917f25', '青陽上人院說金陵故事', '青陽上人院说金陵故事', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["君說南朝全盛日，秣陵才子更多人。","千年秋色古池館，誰見齊王西邸春。"]', '["君说南朝全盛日，秣陵才子更多人。","千年秋色古池館，誰见齊王西邸春。"]', '诗', 'shi', '', NULL, '青陽上人院說金陵故事 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('08728318-88da-47ec-bb71-db8eb83d3f48', '送僧之京師', '送僧之京師', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["綿綿渺渺楚雲繁，萬里西歸望國門。","禪子初心易悽斷，秋風莫上少陵原。"]', '["綿綿渺渺楚云繁，万里西归望国门。","禪子初心易悽斷，秋风莫上少陵原。"]', '诗', 'shi', '', NULL, '送僧之京師 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('f710670c-48ba-4092-b77b-2e1646203272', '送許丞還洛陽', '送許丞還洛陽', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["剡茗情來亦好斟，空門一別肯霑襟。","悲風不動罷瑤軫，忘却洛陽歸客心。"]', '["剡茗情来亦好斟，空门一別肯霑襟。","悲风不动罷瑤軫，忘却洛陽归客心。"]', '诗', 'shi', '', NULL, '送許丞還洛陽 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b3a3c964-8842-45b3-9160-e32e0778230d', '題湖上草堂', '題湖上草堂', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["山居不買剡中山，湖上千峰處處閑。","芳草白雲留我住，世人何事得相關。"]', '["山居不買剡中山，湖上千峰处处闲。","芳草白云留我住，世人何事得相关。"]', '诗', 'shi', '', NULL, '題湖上草堂 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6a4d651e-2ecd-4a05-a234-f34af7a8b66b', '酬李司直縱諸公冬日遊妙喜寺題照昱二上人房寄長城潘丞述', '酬李司直縱諸公冬日游妙喜寺題照昱二上人房寄长城潘丞述', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["達賢貴貞隱，常懼跡不滅。","遂與永公期，遺身坐林樾。","華軒何轔轔，爲我到幽絕。","心境寒草花，空門青山月。","潘生獨不見，清景屢盈缺。","林下常寂寥，人間自離別。","何時解輕佩，來稅丘中轍。"]', '["達賢貴貞隐，常懼跡不滅。","遂與永公期，遺身坐林樾。","华軒何轔轔，爲我到幽絕。","心境寒草花，空门青山月。","潘生独不见，清景屢盈缺。","林下常寂寥，人间自離別。","何时解轻佩，来稅丘中轍。"]', '诗', 'shi', '', NULL, '酬李司直縱諸公冬日遊妙喜寺題照昱二上人房寄長城潘丞述 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('0a940d3e-b268-40e5-9a07-9591322ce4dd', '贈烏程李明府伯宜沈兵曹仲昌', '贈烏程李明府伯宜沈兵曹仲昌', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["水國苦彫瘵，東臯豈遺黍。","雲陰無盡時，日出常帶雨。","昨夜西溪漲，扁舟入簷廡。","野人同鳥巢，暴客若蜂聚。","歲晏無斗粟，寄身欲何所。","空羨鸞鶴姿，翩翩自輕舉。"]', '["水国苦彫瘵，东臯豈遺黍。","云陰無尽时，日出常带雨。","昨夜西溪漲，扁舟入簷廡。","野人同鸟巢，暴客若蜂聚。","歲晏無斗粟，寄身欲何所。","空羨鸾鹤姿，翩翩自轻舉。"]', '诗', 'shi', '', NULL, '贈烏程李明府伯宜沈兵曹仲昌 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('e0bbf92a-b334-46a1-b662-e6334826f43c', '奉酬顏使君真卿王員外圓宿寺兼送員外使迴', '奉酬顏使君真卿王員外圓宿寺兼送員外使迴', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["魯公邀省客，貧寺人過少。","錦帳惟野花，竹屏有窗篠。","朝行石色淨，夜聽泉聲小。","釋事情已高，依禪境無擾。","超遙長路首，悵望空林杪。","離思從此生，還將此心了。"]', '["魯公邀省客，貧寺人過少。","錦帳惟野花，竹屏有窗篠。","朝行石色淨，夜听泉声小。","釋事情已高，依禪境無擾。","超遙长路首，悵望空林杪。","離思從此生，還將此心了。"]', '诗', 'shi', '', NULL, '奉酬顏使君真卿王員外圓宿寺兼送員外使迴 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9a805605-bfd7-47f6-8473-d1b428ab883b', '杼山上峰和顏使君真卿袁侍御五韻賦得印字仍期明日登開元寺樓之會', '杼山上峰和顏使君真卿袁侍御五韻賦得印字仍期明日登开元寺楼之會', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["道情寄遠岳，放曠臨千仞。","香路延絳騶，華泉寫金印。","日欹諸天近，雨過三華潤。","留客雲外心，忘機松中韻。","靈嘉早晚期，爲布東山信。"]', '["道情寄远岳，放曠臨千仞。","香路延絳騶，华泉寫金印。","日欹諸天近，雨過三华潤。","留客云外心，忘機松中韻。","靈嘉早晚期，爲布东山信。"]', '诗', 'shi', '', NULL, '杼山上峰和顏使君真卿袁侍御五韻賦得印字仍期明日登開元寺樓之會 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b55470ee-c645-4315-a91a-44b5dc412267', '同薛員外誼喜雨詩兼上楊使君', '同薛員外誼喜雨诗兼上楊使君', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["積旱忽飛澍，烝民心亦傾。","郊雲不待族，雨色飛江城。","燋稼濯又發，敗荷滋更榮。","時隨霧縠重，乍集柳絲輕。","一宿恐魚飛，數朝徵鸛鳴。","毒暑澄爲冷，高塵滌還清。","乃知陰隲數，制在造化情。","及此接歡賀，臨風聞頌聲。"]', '["積旱忽飞澍，烝民心亦傾。","郊云不待族，雨色飞江城。","燋稼濯又發，敗荷滋更榮。","时隨霧縠重，乍集柳絲轻。","一宿恐鱼飞，數朝徵鸛鳴。","毒暑澄爲冷，高塵滌還清。","乃知陰隲數，制在造化情。","及此接歡賀，臨风闻頌声。"]', '诗', 'shi', '', NULL, '同薛員外誼喜雨詩兼上楊使君 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9778f6d6-c727-43b1-b7a2-687b81baa8f6', '南湖春泛有客自北至說友人岑元和見懷因叙相思之志以寄焉', '南湖春泛有客自北至说友人岑元和见懷因叙相思之志以寄焉', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["故人隔楚水，日夕望芳洲。","春草思眇眇，征雲暮悠悠。","心期無形影，跡曠成阻修。","有客江上至，知君佐雄州。","鏗鏹佩蒼玉，躞蹀驅絳騶。","伊昔中峰心，從來非此流。","資予長生訣，希彼高山儔。","此情今如何，宿昔師吾謀。","別後謁禪老，更添石室籌。","深見人間世，飄如水上漚。","蟬號齊王邸，月苦隋帝樓。","聲華盡冥寞，麋鹿徒呦呦。","我有一字教，坐然遺此憂。","何煩脫珪組，不用辭王侯。","祗在名位中，空門兼可遊。"]', '["故人隔楚水，日夕望芳洲。","春草思眇眇，征云暮悠悠。","心期無形影，跡曠成阻修。","有客江上至，知君佐雄州。","鏗鏹佩蒼玉，躞蹀驱絳騶。","伊昔中峰心，從来非此流。","資予长生訣，希彼高山儔。","此情今如何，宿昔師吾謀。","別後謁禪老，更添石室籌。","深见人间世，飄如水上漚。","蟬號齊王邸，月苦隋帝楼。","声华尽冥寞，麋鹿徒呦呦。","我有一字教，坐然遺此憂。","何煩脫珪組，不用辞王侯。","祗在名位中，空门兼可游。"]', '诗', 'shi', '', NULL, '南湖春泛有客自北至說友人岑元和見懷因叙相思之志以寄焉 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('3a783ec4-b803-431d-8593-df60fde235cc', '同薛員外誼久旱感懷寄兼呈上楊使君', '同薛員外誼久旱感懷寄兼呈上楊使君', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["皇天鑒不昧，愐想何亢極。","絲雨久愆期，綺霞徒相惑。","陰雲舒又卷，濯枝安可得。","涸井不纍瓶，乾溪一憑軾。","赤地芳草死，飆塵驚四塞。","戎寇夜刺閨，民荒歲傷國。","賴以王猷盛，中原無凶慝。","楊公當此晨，省災常旰食。","獨感下堂雨，偏嘉越境域。","秋郊天根見，我疆看稼穡。","請迴雲漢詩，爲君歌樂職。"]', '["皇天鑒不昧，愐想何亢極。","絲雨久愆期，綺霞徒相惑。","陰云舒又卷，濯枝安可得。","涸井不纍瓶，乾溪一憑軾。","赤地芳草死，飆塵驚四塞。","戎寇夜刺閨，民荒歲傷国。","賴以王猷盛，中原無凶慝。","楊公當此晨，省災常旰食。","独感下堂雨，偏嘉越境域。","秋郊天根见，我疆看稼穡。","請迴云漢诗，爲君歌乐職。"]', '诗', 'shi', '', NULL, '同薛員外誼久旱感懷寄兼呈上楊使君 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('eec34419-ad78-42b4-84b9-ac0a05a15fa9', '兵後早春登故鄣南樓望崑山寺白鶴觀示清道人幷沈道士', '兵後早春登故鄣南楼望崑山寺白鹤观示清道人幷沈道士', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["新陽故樓上，眇眇傷遐睠。","違世情易忘，羇時得無倦。","春歸華柳發，世故陵谷變。","擾擾陌上心，悠悠夢中見。","蒼林有靈境，杳映遙可羨。","春日倚東峰，華泉落西甸。","鐘聲在空碧，幡影搖蔥蒨。","緬想山中人，神期如會面。","別離芳月積，岐路浮雲徧。","正□入空門，仙君依苦縣。","隳形捨簪紱，烹玉思精鍊。","事外宜我心，人間豈予戀。","身遺世自薄，道勝名必賤。","耳目何所娛，白雲與黃卷。"]', '["新陽故楼上，眇眇傷遐睠。","違世情易忘，羇时得無倦。","春归华柳發，世故陵谷变。","擾擾陌上心，悠悠梦中见。","蒼林有靈境，杳映遙可羨。","春日倚东峰，华泉落西甸。","鐘声在空碧，幡影搖蔥蒨。","緬想山中人，神期如會面。","別離芳月積，岐路浮云徧。","正□入空门，仙君依苦縣。","隳形捨簪紱，烹玉思精鍊。","事外宜我心，人间豈予戀。","身遺世自薄，道勝名必賤。","耳目何所娛，白云與黄卷。"]', '诗', 'shi', '', NULL, '兵後早春登故鄣南樓望崑山寺白鶴觀示清道人幷沈道士 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('dafc03ab-f819-4a5c-a94d-e3211612b9c3', '酬烏程楊明府華將赴渭北對月見懷', '酬烏程楊明府华將赴渭北对月见懷', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["釋印及秋夜，身閑境亦清。","風襟自瀟灑，月意何高明。","聞說武安君，萬里驅妖精。","開府集秀士，先招士林英。","晉家用元凱，亦是魯諸生。","北望撫長劒，感君知已行。","邊塵昏玉帳，殺氣凝金鐙。","大敵折齊俎，一書下聊城。","翻飛青雲路，宿昔滄洲情。"]', '["釋印及秋夜，身闲境亦清。","风襟自瀟灑，月意何高明。","闻说武安君，万里驱妖精。","开府集秀士，先招士林英。","晉家用元凱，亦是魯諸生。","北望撫长劒，感君知已行。","邊塵昏玉帳，殺氣凝金鐙。","大敵折齊俎，一书下聊城。","翻飞青云路，宿昔滄洲情。"]', '诗', 'shi', '', NULL, '酬烏程楊明府華將赴渭北對月見懷 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('531b5d8a-136f-491e-9da0-11c9dfdc5d7c', '酬邢端公濟春日蘇臺有呈袁州李使君兼書幷寄辛陽王三侍御', '酬邢端公濟春日蘇台有呈袁州李使君兼书幷寄辛陽王三侍御', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["大賢當佐世，堯時難退身。","如何丹霄侶，却在滄江濱。","柳色變又徧，鶯聲聞亦頻。","賴逢宜春守，共賞南湖春。","營道知止足，飾躬無緇磷。","家將詩流近，跡與禪僧親。","放曠臨海門，翺翔望雲津。","雖高空王說，不久山中人。"]', '["大賢當佐世，堯时难退身。","如何丹霄侶，却在滄江濱。","柳色变又徧，鶯声闻亦頻。","賴逢宜春守，共賞南湖春。","營道知止足，飾躬無緇磷。","家將诗流近，跡與禪僧親。","放曠臨海门，翺翔望云津。","雖高空王说，不久山中人。"]', '诗', 'shi', '', NULL, '酬邢端公濟春日蘇臺有呈袁州李使君兼書幷寄辛陽王三侍御 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9f4d5a97-3172-4a94-9293-96be6cb07db7', '奉和裴使君清春夜南堂聽陳山人彈白雪', '奉和裴使君清春夜南堂听陳山人彈白雪', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["春宵凝麗思，閑坐開南圍。","郢客彈白雪，紛綸發金徽。","散從天上至，集向瓊臺飛。","弦上凝颯颯，虛中想霏霏。","通幽鬼神駭，合道精鑒稀。","變態風更入，含情月初歸。","方知阮太守，一聽識其微。"]', '["春宵凝丽思，闲坐开南圍。","郢客彈白雪，紛綸發金徽。","散從天上至，集向瓊台飞。","弦上凝颯颯，虛中想霏霏。","通幽鬼神駭，合道精鑒稀。","变態风更入，含情月初归。","方知阮太守，一听識其微。"]', '诗', 'shi', '', NULL, '奉和裴使君清春夜南堂聽陳山人彈白雪 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('b765d611-2817-4494-b383-e3eab2604eee', '荅孟秀才', '荅孟秀才', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["羸疾依小院，空閑趣自深。","躡苔憐靜色，掃樹共芳陰。","物外好風至，意中佳客尋。","虛名誰欲累，世事我無心。","投贈荷君芷，馨香滿幽襟。"]', '["羸疾依小院，空闲趣自深。","躡苔怜静色，掃樹共芳陰。","物外好风至，意中佳客尋。","虛名誰欲累，世事我無心。","投贈荷君芷，馨香满幽襟。"]', '诗', 'shi', '', NULL, '荅孟秀才 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2951b1a7-89bc-48c3-9b4d-f96c9648e995', '酬崔侍御見贈', '酬崔侍御见贈', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["買得東山後，逢君小隱時。","五湖遊不厭，柏署跡如遺。","市隱何妨道，禪棲不廢詩。","與君爲此說，長破小乘疑。"]', '["買得东山後，逢君小隐时。","五湖游不厭，柏署跡如遺。","市隐何妨道，禪棲不廢诗。","與君爲此说，长破小乘疑。"]', '诗', 'shi', '', NULL, '酬崔侍御見贈 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('108d711a-7647-4c50-bd1e-da1562f34446', '贈柳喜得嵩山法門自號嵩山老', '贈柳喜得嵩山法门自號嵩山老', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["一見嵩山老，吾生恨太遲。","問君年幾許，曾出上皇時。"]', '["一见嵩山老，吾生恨太遲。","问君年幾許，曾出上皇时。"]', '诗', 'shi', '', NULL, '贈柳喜得嵩山法門自號嵩山老 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('212043ae-d73e-4655-9560-6289a8976e62', '酬李補闕紓', '酬李補闕紓', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["不住東林寺，雲泉處處行。","近臣那得識，禪客本無名。"]', '["不住东林寺，云泉处处行。","近臣那得識，禪客本無名。"]', '诗', 'shi', '', NULL, '酬李補闕紓 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('741cdc50-fca8-4b9b-9147-3fc5c34c55bd', '湖南蘭若示大乘諸公', '湖南蘭若示大乘諸公', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["未到無爲岸，空憐不繫舟。","東山白雲意，歲晚尚悠悠。"]', '["未到無爲岸，空怜不繫舟。","东山白云意，歲晚尚悠悠。"]', '诗', 'shi', '', NULL, '湖南蘭若示大乘諸公 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('19fb967f-b3f4-442c-89f5-832803878b94', '兵後經永安法空寺寄悟禪師', '兵後經永安法空寺寄悟禪師', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["常說人間法自空，何言出世法還同。","微蹤舊是香林下，餘燼今成火宅中。","後夜池心生素月，春天樹色起悲風。","吾知世代相看盡，誰悟浮生似影公。"]', '["常说人间法自空，何言出世法還同。","微蹤旧是香林下，餘燼今成火宅中。","後夜池心生素月，春天樹色起悲风。","吾知世代相看尽，誰悟浮生似影公。"]', '诗', 'shi', '', NULL, '兵後經永安法空寺寄悟禪師 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b2e7509-c3ae-42b6-9a70-62ac0046e378', '春日杼山寄贈李員外縱', '春日杼山寄贈李員外縱', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["南山唯與北山鄰，古樹連拳伴我身。","黃鶴有心多不住，白雲無事獨相親。","閑持竹錫深看水，嬾繫麻衣出見人。","欲掇幽芳聊贈遠，郎官那賞石門春。"]', '["南山唯與北山鄰，古樹連拳伴我身。","黄鹤有心多不住，白云無事独相親。","闲持竹錫深看水，嬾繫麻衣出见人。","欲掇幽芳聊贈远，郎官那賞石门春。"]', '诗', 'shi', '', NULL, '春日杼山寄贈李員外縱 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2569a5e8-696a-439d-88e8-516a3560f86f', '酬秦山人贈別二首 一', '酬秦山人贈別二首 一', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["知君高隱占賢星，卷葉時時注佛經。","姓被名公題舊里，詩將麗句號新亭。","來觀新月依清室，欲漱香泉護觸瓶。","我有主人江太守，如何相伴住禪靈。"]', '["知君高隐占賢星，卷葉时时注佛經。","姓被名公題旧里，诗將丽句號新亭。","来观新月依清室，欲漱香泉護觸瓶。","我有主人江太守，如何相伴住禪靈。"]', '诗', 'shi', '', NULL, '酬秦山人贈別二首 一 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('d857eb0a-4c2c-4af9-bf0f-013fc83b804c', '酬秦山人贈別二首 二', '酬秦山人贈別二首 二', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["誰知臥病不妨禪，跡寄詩流性似偏。","葉示黃金童子愛，書題青字古人傳。","時高獨鶴來雲外，每羨閑花在眼前。","對此留君還欲別，應思石瀃訪春泉。"]', '["誰知臥病不妨禪，跡寄诗流性似偏。","葉示黄金童子愛，书題青字古人傳。","时高独鹤来云外，每羨闲花在眼前。","对此留君還欲別，應思石瀃訪春泉。"]', '诗', 'shi', '', NULL, '酬秦山人贈別二首 二 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6b477609-0d51-4a2b-ab3c-f568bb5e19c2', '山居示靈澈上人', '山居示靈澈上人', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["晴明路出山初暖，行踏春蕪看茗歸。","乍削柳枝聊代札，時窺雲影學裁衣。","身閑始覺隳名是，心了方知苦行非。","外物寂中誰似我，松聲草色共無機。"]', '["晴明路出山初暖，行踏春蕪看茗归。","乍削柳枝聊代札，时窺云影学裁衣。","身闲始覺隳名是，心了方知苦行非。","外物寂中誰似我，松声草色共無機。"]', '诗', 'shi', '', NULL, '山居示靈澈上人 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('c6e76531-1973-40a9-b4d4-a9e109cffb3f', '遙和康錄事李侍御萼小寒食夜重集康氏園林', '遙和康錄事李侍御萼小寒食夜重集康氏园林', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["習家寒食會何頻，應恐流芳不待人。","已愛治書詩句逸，更聞從事酒名新。","庭蕪暗積承雙履，林蘤雷飛灑幅巾。","誰見柰園時節共，還持綠茗賞殘春。"]', '["習家寒食會何頻，應恐流芳不待人。","已愛治书诗句逸，更闻從事酒名新。","庭蕪暗積承雙履，林蘤雷飞灑幅巾。","誰见柰园时節共，還持綠茗賞殘春。"]', '诗', 'shi', '', NULL, '遙和康錄事李侍御萼小寒食夜重集康氏園林 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('07f9f636-65eb-4f34-b0de-3af51576a7c6', '釋裴循春愁', '釋裴循春愁', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["蝶舞鶯歌喜歲芳，柳絲褭褭蕙帶長。","江南春色共君有，何事君心獨自傷。"]', '["蝶舞鶯歌喜歲芳，柳絲褭褭蕙带长。","江南春色共君有，何事君心独自傷。"]', '诗', 'shi', '', NULL, '釋裴循春愁 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d6a979c-d58b-46f2-b6bc-b2a16c9b176d', '西白溪期裴方舟不至', '西白溪期裴方舟不至', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["望君不見復何情，野草閑雲處處生。","應向秦時武陵路，花間寂歷一人行。"]', '["望君不见复何情，野草闲云处处生。","應向秦时武陵路，花间寂歷一人行。"]', '诗', 'shi', '', NULL, '西白溪期裴方舟不至 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('4a94e78d-5747-40ab-a800-41fd44b2abb3', '勞山憶棲霞寺道素上人久期不至', '勞山憶棲霞寺道素上人久期不至', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["遠寺蕭蕭獨坐心，山情自得趣何深。","泉聲稍滴芙蓉漏，月影纔分鸚鵡林。","滿地雲輕長礙屣，繞松風近每吹襟。","貪閑不記前心偈，念別聊爲出世吟。","更待花開徧山雪，山山相似若爲尋。"]', '["远寺蕭蕭独坐心，山情自得趣何深。","泉声稍滴芙蓉漏，月影纔分鸚鵡林。","满地云轻长礙屣，繞松风近每吹襟。","貪闲不記前心偈，念別聊爲出世吟。","更待花开徧山雪，山山相似若爲尋。"]', '诗', 'shi', '', NULL, '勞山憶棲霞寺道素上人久期不至 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('68af631d-9665-40e5-8431-5bb3e81b9853', '酬秦山人出山見呈', '酬秦山人出山见呈', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["手攜酒榼共書幃，迴語長松我即歸。","若是出山機已息，嶺雲何事背君飛。"]', '["手携酒榼共书幃，迴語长松我即归。","若是出山機已息，嶺云何事背君飞。"]', '诗', 'shi', '', NULL, '酬秦山人出山見呈 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5a4f4d23-320a-449d-b5e4-4f1bf37c3ffa', '酬秦山人見尋', '酬秦山人见尋', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["左右香童不識君，擔簦訪我領鷗羣。","山僧待客無俗物，唯有窗前片碧雲。"]', '["左右香童不識君，擔簦訪我領鷗羣。","山僧待客無俗物，唯有窗前片碧云。"]', '诗', 'shi', '', NULL, '酬秦山人見尋 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('cb7a9cbc-2b89-4d6d-a19c-78d6d10db9fc', '宿法華寺簡靈澈上人', '宿法华寺簡靈澈上人', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["至道無機但杳冥，孤燈寒竹自青熒。","不知何處小乘客，一夜風來聞誦經。"]', '["至道無機但杳冥，孤灯寒竹自青熒。","不知何处小乘客，一夜风来闻誦經。"]', '诗', 'shi', '', NULL, '宿法華寺簡靈澈上人 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('6ac30981-e79e-4260-a0e6-fc98530e04dd', '潛別離', '潛別離', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["烏頭雖黑白有時，唯有潛離與暗別，彼此甘心無後期。"]', '["烏头雖黑白有时，唯有潛離與暗別，彼此甘心無後期。"]', '诗', 'shi', '', NULL, '潛別離 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('59af369d-0a5a-42d0-a9e6-81d2d555570f', '奉酬袁使君高春遊鶺鴒峰蘭若見懷', '奉酬袁使君高春游鶺鴒峰蘭若见懷', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["鶺鴒中峰近，高奇古人遺。","常欲乞此地，養松挂藤絲。","昨聞雙旌出，一川花滿時。","恨無翔雲步，遠赴關山期。","躋險與誰賞，折芳應自怡。","遙知忘歸趣，喜得春景遲。","已見郢人唱，新題石門詩。"]', '["鶺鴒中峰近，高奇古人遺。","常欲乞此地，養松挂藤絲。","昨闻雙旌出，一川花满时。","恨無翔云步，远赴关山期。","躋險與誰賞，折芳應自怡。","遙知忘归趣，喜得春景遲。","已见郢人唱，新題石门诗。"]', '诗', 'shi', '', NULL, '奉酬袁使君高春遊鶺鴒峰蘭若見懷 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('5ff4a393-5302-4e3f-a50e-f1d215acffa8', '荅裴濟從事', '荅裴濟從事', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["遲遲雲鶴意，奮翅知有期。","三秉綱紀局，累登清白資。","應懷青塘居，蕙草沒前墀。","舊月照秋水，廢田留故陂。","至今高風在，爲君吹桂枝。","昨逢洞庭客，果得故人詩。","何異王內史，來招道林師。","欲攜山侶出，難與白雲辭。"]', '["遲遲云鹤意，奮翅知有期。","三秉綱紀局，累登清白資。","應懷青塘居，蕙草沒前墀。","旧月照秋水，廢田留故陂。","至今高风在，爲君吹桂枝。","昨逢洞庭客，果得故人诗。","何異王內史，来招道林師。","欲携山侶出，难與白云辞。"]', '诗', 'shi', '', NULL, '荅裴濟從事 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9613a13b-9388-4984-9626-cb66afb315ae', '白雲上人精舍尋杼山禪師兼示崔子向何山道上人', '白云上人精舍尋杼山禪師兼示崔子向何山道上人', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["望遠涉寒水，懷人在幽境。","爲高皎皎姿，及愛蒼蒼嶺。","果見栖禪子，潺湲灌真頂。","積疑一念破，澄息萬緣靜。","世事花上塵，惠心空中境。","清閑誘我性，遂使腸慮屏。","許共林客遊，欲從山王請。","木栖無名樹，水汲忘機井。","持此一日高，未肯謝箕潁。","夕霽山態好，空月生俄頃。","識妙聆細泉，悟深滌清茗。","此心誰得失，笑向西林永。"]', '["望远涉寒水，懷人在幽境。","爲高皎皎姿，及愛蒼蒼嶺。","果见栖禪子，潺湲灌真頂。","積疑一念破，澄息万緣静。","世事花上塵，惠心空中境。","清闲誘我性，遂使腸慮屏。","許共林客游，欲從山王請。","木栖無名樹，水汲忘機井。","持此一日高，未肯謝箕潁。","夕霽山態好，空月生俄頃。","識妙聆細泉，悟深滌清茗。","此心誰得失，笑向西林永。"]', '诗', 'shi', '', NULL, '白雲上人精舍尋杼山禪師兼示崔子向何山道上人 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('780d237f-2675-490f-8fa1-747021ce863a', '酬薛員外誼苦熱行見寄', '酬薛員外誼苦熱行见寄', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["六月金數伏，茲辰日在庚。","炎曦爍肌膚，毒霧昏性情。","安得奮輕翮，超遙出雲征。","不知天地心，如何匠生成。","火德燒百卉，瑤草不及榮。","省客當此時，忽貽懷中瓊。","捧翫煩袂滌，嘯歌美風生。","遲君佐元氣，調使四序平。","中令霜不祓，大餘氣常貞。","江南詩騷客，休吟苦熱行。"]', '["六月金數伏，茲辰日在庚。","炎曦爍肌膚，毒霧昏性情。","安得奮轻翮，超遙出云征。","不知天地心，如何匠生成。","火德燒百卉，瑤草不及榮。","省客當此时，忽貽懷中瓊。","捧翫煩袂滌，嘯歌美风生。","遲君佐元氣，調使四序平。","中令霜不祓，大餘氣常貞。","江南诗騷客，休吟苦熱行。"]', '诗', 'shi', '', NULL, '酬薛員外誼苦熱行見寄 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('2d138595-e6e1-4241-b59a-6d61d3db897d', '採實心竹杖寄贈李萼侍御', '採實心竹杖寄贈李萼侍御', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["竹杖裁碧鮮，步林賞高直。","實心去內矯，全節無外飾。","行藥聊自持，扶危資爾力。","初生在榛莽，孤秀豈封殖。","干雪不死枝，贈君期君識。"]', '["竹杖裁碧鲜，步林賞高直。","實心去內矯，全節無外飾。","行藥聊自持，扶危資爾力。","初生在榛莽，孤秀豈封殖。","干雪不死枝，贈君期君識。"]', '诗', 'shi', '', NULL, '採實心竹杖寄贈李萼侍御 皎然 shi');
INSERT INTO poems (id, title, title_simplified, author_id, dynasty, content, content_simplified, form_type, poem_type, rhythmic, tags, search_content) VALUES ('9eef0b94-1966-40ca-b6af-bedac75ced7a', '酬薛員外誼見戲一首', '酬薛員外誼见戲一首', 'bb4ad56e-6b2d-4af7-b957-2025be7b7ced', '唐', '["方知正始作，麗掩碧雲詩。","文彩盈懷袖，風規發詠思。","遺弓逢大敵，摩壘怯偏師。","頻有移書讓，多慙繫組遲。","淺才迂且拙，虛譽喜還疑。","猶倚披沙鑒，長歌向子期。"]', '["方知正始作，丽掩碧云诗。","文彩盈懷袖，风規發詠思。","遺弓逢大敵，摩壘怯偏師。","頻有移书讓，多慙繫組遲。","淺才迂且拙，虛譽喜還疑。","猶倚披沙鑒，长歌向子期。"]', '诗', 'shi', '', NULL, '酬薛員外誼見戲一首 皎然 shi');
